(window.JCPA_DATA=window.JCPA_DATA||{})["insolvency"]={"id":"insolvency","name":"قانون الإعسار","full":"قانون الإعسار رقم (21) لسنة 2018","icon":"⚖️","articles":[{"n":"1","chapter":"","notes":[],"source":"يسمى هذا القانون ( قانون الاعسار لسنة 2018) ويعمل به بعد مرور مائة وثمانين يوما من تاريخ نشره في الجريدة الرسمية.","title":"اسم القانون وبدء العمل به","memo":"⭐ يعمل بقانون الإعسار لسنة 2018 بعد مرور مائة وثمانين يوماً من تاريخ نشره في الجريدة الرسمية","qs":[{"q":"متى يعمل بقانون الإعسار لسنة 2018؟","o":["بعد مرور مائة وثمانين يوماً من تاريخ نشره في الجريدة الرسمية","من تاريخ نشره في الجريدة الرسمية","بعد مرور ثلاثين يوماً من تاريخ نشره في الجريدة الرسمية","بعد مرور تسعين يوماً من تاريخ نشره في الجريدة الرسمية"],"a":0}]},{"n":"2","chapter":"","notes":[],"source":"يكون للكلمات والعبارات التالية حيثما وردت في هذا القانون المعاني المخصصة لها أدناه ما لم تدل القرينة على غير ذلك:\nالاعسار : توقف المدين أو عجزه عن سداد الديون الاعسار المستحقة عليه بانتظام أو عند تجاوز إجمالي الالتزامات المترتبة عليه إجمالي قيمة أمواله.\nالاعسار الوشيك : الحالة التي يتوقع فيها أن يفقد المدين القدرة المستقبليه على سداد ديونه عند استحقاقها خلال ستة أشهر رغم قدرته الحالية على سدادها.\nالمدين : الشخص الطبيعي أو الاعتباري الذي تنطبق المدين عليه حالات الإعسار أو الإعسار الوشيك.\nوكيل الاعسار : الشخص الطبيعي أو الاعتباري المرخص له بممارسه أعمال وكيل الإعسار المنصوص عليها في هذا القانون.\nسجل الاعسار : السجل الذي ينشأ في وزارة الصناعة والتجارة والتموين وتشهر فيه الإجراءات المتعلقة بالإعسار .\nذمة الاعسار : الأموال والحقوق المادية والمعنوية العائدة للمدين في تاريخ إشهار الإعسار أو بعده دون أن تشمل الأموال والحقوق العائدة للشخص الطبيعي المستثناة من الحجز بموجب أحكام هذا القانون.\nمركز المصالح الرئيسة : مكان إدارة مصالح المدين وممارسة نشاطاته واعماله بشكل منتظم أو مكان التسجيل أو الموطن إذا كان المدين شخصا اعتباريا.\nتاريخ اشهار الاعسار : تاريخ صدور قرار المحكمة بإشهار الإعسار.\nالدين المحتمل : الدين المعلق على شرط أو أي سبب آخر يجعله غير مستحق في ذمة الإعسار.\nالمنشاة : المكان الذي يمارس فيه المدين نشاطاته الاقتصادية المعتادة بشكل دائم والذي تكون فيه الموارد البشرية أو البضائع أو الخدمات حسب مقتضى الحال.\nالنشاط الاقتصادي : النشاط الذي يمارسه الشخص بقصد تحقيق ربح أو مكسب بما في ذلك النشاط التجاري أو الصناعي أو الزراعي أو المهني أو الخدمي أو الحرفي.\nالاجراءات التحفظية : الإجراءات التي تتخذها المحكمة بموجب أحكام هذا القانون لتفادي هلاك الاموال الداخلة في ذمة الإعسار أو تلفها أو لحماية المصالح المشروعة للدائنين.\nأصحاب الحقوق المضمونة : الدائن صاحب الحق المضمون بحق عيني تبعي على مال منقول أو غير منقول.\nالمحكمة : محكمة البداية التي يقع ضمن اختصاصها المكاني مركز المصالح الرئيسه للمدين.\nالمراقب : مراقب عام الشركات.\nالمحكمة الاجنبية : الجهة المختصة التي تشرف على إجراءات الإعسار الأجنبية.\nالاجراءات الاجنبية : الإجراءات التي تتم في دولة أخرى بموجب التشريعات النافذة في تلك الدولة والتي تصبح بمقتضاها أموال المدين ونشاطاته تحت إشراف محكمة أجنبية أو رقابتها.\nالاجراءات الاجنبية : إجراءات الإعسار التي تتم في دولة أجنبية حيث يكون مركز المصالح الرئيسه للمدين.\nالاجراءات الاجنبية الثانوية : إجراءات الإعسار التي تتم في دولة أخرى يكون للمدين فيها منشأة دون ان يكون له مركز مصالح رئيسة .\nوكيل الاعسار الاجنبي : الشخص المفوض بشكل دائم أو مؤقت بموجب إجراءات أجنبية بإدارة أموال المدين أو نشاطاته أو القيام بدور وكيل الاعسار وفقا لأحكام التشريعات النافذة في دولة أجنبية .","title":"تعريفات قانون الإعسار","memo":"⭐ الإعسار: توقف المدين أو عجزه عن سداد ديونه المستحقة بانتظام أو تجاوز إجمالي التزاماته إجمالي قيمة أمواله\n⭐ الإعسار الوشيك: توقع فقدان القدرة على السداد خلال ستة أشهر رغم القدرة الحالية\n⭐ المحكمة: محكمة البداية التي يقع ضمن اختصاصها مركز المصالح الرئيسة للمدين، والمراقب: مراقب عام الشركات\n⭐ سجل الإعسار ينشأ في وزارة الصناعة والتجارة والتموين، وتاريخ إشهار الإعسار هو تاريخ صدور قرار المحكمة بإشهاره","qs":[{"q":"يُعرَّف الإعسار الوشيك بأنه الحالة التي يتوقع فيها أن يفقد المدين القدرة المستقبلية على سداد ديونه عند استحقاقها خلال:","o":["ستة أشهر رغم قدرته الحالية على سدادها","سنة رغم قدرته الحالية على سدادها","ثلاثة أشهر رغم قدرته الحالية على سدادها","شهرين رغم قدرته الحالية على سدادها"],"a":0},{"q":"المحكمة المختصة بإجراءات الإعسار وفقاً لتعريفات القانون هي:","o":["محكمة البداية التي يقع ضمن اختصاصها المكاني مركز المصالح الرئيسة للمدين","محكمة الصلح التي يقع ضمن اختصاصها موطن الدائن","محكمة الاستئناف التي يقع ضمن اختصاصها مركز المصالح الرئيسة للمدين","محكمة البداية التي يقع ضمن اختصاصها موطن الدائن طالب الإشهار"],"a":0},{"q":"أين ينشأ سجل الإعسار الذي تشهر فيه الإجراءات المتعلقة بالإعسار؟","o":["وزارة الصناعة والتجارة والتموين","دائرة مراقبة الشركات","وزارة العدل","البنك المركزي الأردني"],"a":0},{"q":"يُقصد بـ(تاريخ إشهار الإعسار) وفقاً للقانون:","o":["تاريخ صدور قرار المحكمة بإشهار الإعسار","تاريخ نشر قرار الإشهار في الجريدة الرسمية","تاريخ تقديم طلب إشهار الإعسار","تاريخ تبليغ المدين بقرار الإشهار"],"a":0}]},{"n":"3","chapter":"","notes":[],"source":"أ. تسري أحكام هذا القانون على أي شخص يمارس نشاطا اقتصاديا بما في ذلك:\n1. الأشخاص الاعتباريون بما في ذلك الشركات المدنية والشركات التي تملكها الحكومة.\n2. التجار أصحاب الموسسات الفردية.\n3. أصحاب المهن المسجلون والمرخص لهم بالعمل بموجب أحكام التشريعات النافذة.\nب. لا تسري أحكام هذا القانون على :\n1. البنوك.\n2. شركات التأمين.\n3. الجمعيات والنوادي ما لم يقرر مجلس الوزراء إخضاعها لأحكام هذا القانون.\n4. الأشخاص الطبيعيون الذين يخضعون لأحكام القانون المدني باستثناء ما ورد في البند (3) من الفقرة (أ) من هذه المادة.\n5. الوزارات والدوائر الحكوميه والمؤسسات الرسمية العامة والموسسات العامة .\n6. البلديات.\nج. لا تسري أحكام هذا القانون على إجراءات التصفية التي تتم وفقا لأحكام قانون الشركات لأسباب لا تتعلق بالاعسار .\nهـ. لا تسري أحكام هذا القانون على إجراءات الإفلاس او التصفية التي بدأت قبل نفاذ احكامه.","title":"نطاق سريان قانون الإعسار","memo":"⭐ يسري على كل من يمارس نشاطاً اقتصادياً: الأشخاص الاعتباريون (ومنها الشركات المدنية والشركات المملوكة للحكومة)، التجار أصحاب المؤسسات الفردية، أصحاب المهن المسجلون والمرخصون\n⭐ لا يسري على: البنوك، شركات التأمين، الجمعيات والنوادي (ما لم يقرر مجلس الوزراء إخضاعها)، الوزارات والمؤسسات العامة، البلديات\n⭐ لا يسري على التصفية وفق قانون الشركات لأسباب لا تتعلق بالإعسار، ولا على الإفلاس أو التصفية التي بدأت قبل نفاذه","qs":[{"q":"أي مما يلي تسري عليه أحكام قانون الإعسار؟","o":["الشركات التي تملكها الحكومة","البنوك","شركات التأمين","البلديات"],"a":0},{"q":"الجهة التي تملك إخضاع الجمعيات والنوادي لأحكام قانون الإعسار هي:","o":["مجلس الوزراء","وزير الصناعة والتجارة والتموين","مراقب عام الشركات","المحكمة"],"a":0},{"q":"جميع الجهات التالية لا تسري عليها أحكام قانون الإعسار باستثناء:","o":["أصحاب المهن المسجلين والمرخص لهم بالعمل","المؤسسات الرسمية العامة","الوزارات والدوائر الحكومية","البنوك"],"a":0},{"q":"شركة بدأت إجراءات تصفيتها قبل نفاذ قانون الإعسار، فإن هذه الإجراءات:","o":["لا تسري عليها أحكام قانون الإعسار","تخضع لأحكام قانون الإعسار بأثر فوري","تخضع لقانون الإعسار بقرار من المحكمة","تخضع لقانون الإعسار بموافقة مجلس الوزراء"],"a":0}]},{"n":"4","chapter":"","notes":[],"source":"لغايات تطبيق أحكام هذا القانون يعتبر كل من الأشخاص التالية ذا صلة بالمدين إذا كان المدين:\nأ. شخصا طبيعيا:\n1. الزوج والأقارب حتى الدرجة الرابعة والأشخاص الذين تقتضي طبيعة عملهم الاطلاع على الوضع المالى للمدين بمن في ذلك المدير المالي والمدقق الداخلي والمدقق الخارجي.\n2. لغايات هذا القانون تعتبر الرابطة الزوجية قائمة ولو تم الزواج بعد إتمام التصرف أو انتهت الرابطة الزوجية خلال السنة السابقة لذلك التصرف.\nب. شخصا اعتباريا:\n1. حليف الشخص الاعتباري الذي يسيطر على شخص اعتباري آخر أو المسيطر عليه من قبل ذلك الشخص أو يسيطر عليهما معا شخص اعتباري ثالث.\n2. أعضاء مجلس الإدارة والإدارة التنفيذية العليا للشخص الاعتباري.\n3. أعضاء مجلس الإدارة أو هيئة المديرين والإدارة التنفيذية العليا لحليف الشخص الاعتباري.\n4. أي شخص يمتلك نسبة (%5) أو أكثر من أسهم الشركة المساهمه العامة أو أيا من الشركات الحليفة\n5. أقارب وشركاء الجهات المشار إليها في البنود (1) و(2) و(3) و(4) .\n6. صناديق الادخار للعاملين لدى الشخص الاعتباري.\n7. المشاريع والمنشآت المشتركة والائتلافات للشخص الاعتباري مع أي جهة أخرى.\n8. الشركات التي تكون لأعضاء مجلس الإدارة أو هيئة المديرين أو الإدارة التنفيذية العليا وأقاربهم القدرة المباشرة أو غير المباشرة على ممارسة تاثير فعال على أعمالها وقراراتها.\n9. الشخص الذي يطلع على المعلومات الداخلية المتعلقة بالوضع المالي للمدين بحكم منصبه أو وظيفته بمن في ذلك رئيس وأعضاء مجلس الادارة والمدير العام والمدير المالي والمدقق الداخلي والمدقق الخارجي وممثل الشخص الاعتباري، وأقرباء الجهات المشار إليها حتى الدرجه الثالثة.\n10. أي شخص طبيعي يكون مسؤولا في امواله الخاصة عن التزامات المدين.","title":"الأشخاص ذوو الصلة بالمدين","memo":"⭐ المدين الطبيعي: الزوج والأقارب حتى الدرجة الرابعة ومن يطلع بحكم عمله على وضعه المالي (المدير المالي والمدقق الداخلي والخارجي)\n⭐ تعتبر الرابطة الزوجية قائمة ولو تم الزواج بعد التصرف أو انتهت خلال السنة السابقة للتصرف\n⭐ المدين الاعتباري: من يمتلك (5%) أو أكثر من أسهم الشركة المساهمة العامة أو الشركات الحليفة، وأقرباء المطلعين على المعلومات الداخلية حتى الدرجة الثالثة","qs":[{"q":"إذا كان المدين شخصاً طبيعياً، يعتبر من ذوي الصلة به أقاربه حتى الدرجة:","o":["الرابعة","الثالثة","الثانية","الخامسة"],"a":0},{"q":"يعتبر ذا صلة بالمدين الشخص الاعتباري كل من يمتلك من أسهم الشركة المساهمة العامة نسبة:","o":["(5%) أو أكثر","(10%) أو أكثر","(20%) أو أكثر","(25%) أو أكثر"],"a":0},{"q":"لغايات تحديد ذوي الصلة بالمدين الطبيعي، تعتبر الرابطة الزوجية قائمة إذا انتهت خلال:","o":["السنة السابقة للتصرف","الستة أشهر السابقة للتصرف","السنتين السابقتين للتصرف","الشهرين السابقين للتصرف"],"a":0},{"q":"أي مما يلي لا يعتبر من ذوي الصلة بالمدين الشخص الاعتباري وفقاً لنص المادة؟","o":["عميل يتعامل مع المدين دون أن يطلع على معلوماته الداخلية","صناديق الادخار للعاملين لدى الشخص الاعتباري","أعضاء مجلس الإدارة والإدارة التنفيذية العليا","أي شخص طبيعي مسؤول في أمواله الخاصة عن التزامات المدين"],"a":0}]},{"n":"5","chapter":"","notes":[],"source":"مع مراعاة الأحكام المنصوص عليها في الفصل السابع من هذا القانون، تقسم إجراءات الإعسار الى المراحل التاليه:\nأ. المرحلة التمهيدية وتبدأ من تاريخ صدور قرار المحكمة بإشهار الإعسار وتخصص لحصر ذمة الإعسار ودائني المدين وجمع المعلومات المتعلقة بأعماله وتبويبها وتحليلها للتوصل لاسباب الإعسار ومدى قابلية أعماله للاستمرار.\nب. مرحلة إعادة التنظيم وهي المرحلة التي تلي المرحلة التمهيدية مباشرة ، ويتم خلالها التوصل لاتفاق بين المدين ودائنيه على خطة إعادة التنظيم ما لم يقدم طلب تصفية قبل البدء في هذه المرحلة .\nج. مرحلة التصفية وتخصص لتصفية أموال المدين وتبدأ عند تعذر اعادة التنظيم لعدم إمكانية استمرار أعمال المدين، أو تعذر الموافقة على خطة إعادة التنظيم أو تعذر تنفيذها بعد الموافقة عليها.","title":"مراحل إجراءات الإعسار","memo":"⭐ مراحل الإعسار ثلاث: التمهيدية، إعادة التنظيم، التصفية\n⭐ المرحلة التمهيدية تبدأ من تاريخ صدور قرار المحكمة بإشهار الإعسار وتخصص لحصر ذمة الإعسار والدائنين وتحليل أسباب الإعسار\n⭐ إعادة التنظيم تلي التمهيدية مباشرة ما لم يقدم طلب تصفية قبلها، والتصفية تبدأ عند تعذر إعادة التنظيم أو الموافقة على خطتها أو تنفيذها","qs":[{"q":"تبدأ المرحلة التمهيدية لإجراءات الإعسار من تاريخ:","o":["صدور قرار المحكمة بإشهار الإعسار","تقديم طلب إشهار الإعسار","نشر قرار الإشهار في الجريدة الرسمية","تعيين وكيل الإعسار"],"a":0},{"q":"المرحلة التي يتم خلالها التوصل لاتفاق بين المدين ودائنيه على خطة لاستمرار أعماله هي مرحلة:","o":["إعادة التنظيم","التصفية","التمهيدية","التسوية الودية"],"a":0},{"q":"أي مما يلي لا يعد سبباً لبدء مرحلة التصفية؟","o":["انتهاء المرحلة التمهيدية بقابلية أعمال المدين للاستمرار","تعذر إعادة التنظيم لعدم إمكانية استمرار أعمال المدين","تعذر الموافقة على خطة إعادة التنظيم","تعذر تنفيذ خطة إعادة التنظيم بعد الموافقة عليها"],"a":0}]},{"n":"6","chapter":"الفصل الثاني - إشهار الإعسار - أحكام عامة","notes":[],"source":"أ. للمدين ولأي من دائنيه وللمراقب إذا كان المدين شركة، أن يتقدم للمحكمه بطلب إشهار الإعسار، شريطة مراعاة الاجراءات المنصوص عليها في هذا القانون وتعطى الأولوية للبت في الطلب المقدم من المدين.\nب. يسمع طلب إشهار الإعسار المقدم من المدين في حال الإعسار الفعلى والاعسار الوشيك بينما لا يسمع الطلب المقدم من المراقب ودائني المدين إلا في حال الإعسار الفعلي.","title":"أصحاب الحق في طلب إشهار الإعسار","memo":"⭐ يحق تقديم طلب الإشهار للمدين ولأي من دائنيه وللمراقب إذا كان المدين شركة، والأولوية للطلب المقدم من المدين\n⭐ طلب المدين يسمع في الإعسار الفعلي والوشيك، أما طلب المراقب والدائنين فلا يسمع إلا في الإعسار الفعلي","qs":[{"q":"عند تعدد طلبات إشهار الإعسار، تعطى الأولوية للبت في الطلب المقدم من:","o":["المدين","الدائن صاحب الحق المضمون","المراقب","الدائن الأكبر ديناً"],"a":0},{"q":"يسمع طلب إشهار الإعسار الوشيك إذا كان مقدماً من:","o":["المدين فقط","المدين أو دائنيه","المراقب فقط","المدين أو المراقب أو الدائنين"],"a":0},{"q":"يحق للمراقب التقدم بطلب إشهار الإعسار إذا كان المدين:","o":["شركة","تاجراً فردياً","صاحب مهنة مرخصاً","جمعية أو نادياً"],"a":0}]},{"n":"7","chapter":"الفصل الثاني - إشهار الإعسار - أحكام عامة","notes":[],"source":"أ. على المدين وأي من الأشخاص الذين يتولون إدارته إذا كان شخصا اعتباريا و لو لم يحصل على موافقة الشركاء والمساهمين أن يتقدم بطلب إشهار الاعسار خلال مدة شهرين من تاريخ علمه الفعلي أو المفترض بأنه مسر.\nب. لا تسري المدة المنصوص عليها في الفقرة (أ) من هذه المادة على طلب إشهار الإعسار الوشيك .\nج. يكون الأشخاص الواردون في الفقرة (أ) من هذه المادة مسؤولين شخصيا عن الضرر الناجم عن الإخلال بأحكام هذه المادة و للمحكمة في هذه الحالة أن تصدر قرارا بمنع المخالف من ممارسة أي نشاط اقتصادي لمدة لا تقل عن سنه ولا تزيد على خمس سنوات.","title":"مدة التزام المدين بطلب الإشهار ومسؤوليته","memo":"⭐ يجب على المدين ومن يتولى إدارته (ولو دون موافقة الشركاء) طلب الإشهار خلال شهرين من علمه الفعلي أو المفترض بإعساره\n⭐ لا تسري مدة الشهرين على طلب إشهار الإعسار الوشيك\n⭐ المخالف مسؤول شخصياً عن الضرر، وللمحكمة منعه من ممارسة أي نشاط اقتصادي مدة لا تقل عن سنة ولا تزيد على خمس سنوات","qs":[{"q":"على المدين أن يتقدم بطلب إشهار الإعسار خلال مدة ............ من تاريخ علمه الفعلي أو المفترض بأنه معسر:","o":["شهرين","ثلاثين يوماً","ستة أشهر","خمسة عشر يوماً"],"a":0},{"q":"للمحكمة أن تمنع المدين المخالف لواجب تقديم طلب الإشهار من ممارسة أي نشاط اقتصادي لمدة:","o":["لا تقل عن سنة ولا تزيد على خمس سنوات","لا تقل عن ستة أشهر ولا تزيد على سنتين","لا تقل عن سنتين ولا تزيد على عشر سنوات","لا تقل عن سنة ولا تزيد على ثلاث سنوات"],"a":0},{"q":"مدير شركة علم بإعسارها الفعلي ولم يحصل على موافقة المساهمين على تقديم طلب الإشهار، فإنه:","o":["ملزم بتقديم الطلب خلال المدة المحددة ولو لم يحصل على الموافقة","غير ملزم بتقديم الطلب إلا بعد موافقة المساهمين","يعفى من المسؤولية لعدم حصوله على الموافقة","ملزم بإبلاغ المراقب فقط"],"a":0}]},{"n":"8","chapter":"الفصل الثاني - إشهار الإعسار - أحكام عامة","notes":[],"source":"أ. على المدين تضمين طلب إشهار الإعسار إقرارا منه بأنه دخل في مرحلة الإعسار الوشيك أو الإعسار الفعلي حسب مقتضى الحال.\nب. ترفق بالطلب البينات التالية:\n1. تقرير يتضمن أسباب الإعسار وتحليلا لمستقبل النشاط الإقتصادي.\n2. شهادة صادرة عن جهة تسجيل المدين تبين تاريخ تسجيله وتسلسل أي تغييرات حاصلة عليه.\n3. القيود المالية والمحاسبية للمدين بما في ذلك الميزانية والبيانات المالية أو الدفاتر التجارية للسنوات المالية الثلاث التي تسبق تقديم الطلب.\n4 كشف بالأموال المنقولة وغير المنقولة العائدة للمدين مع بيان قيمة كل منها، وموقعها والمعلومات المتعلقة بها وفقا للسجلات الرسمية وما إذا كانت هذه الأموال خاضعة لإجراءات تنفيذ عليها أو موضوعة تأمينا لدين أو انها موضوع حق امتياز مع بيان قيمة الديون المترتبة عليها.\n5. قائمة بدائني المدين تتضمن اسم كل منهم وعنوانه، إن وجد، ومبلغ دينه وأصل ذلك الدين وتاريخ نشأته واستحقاقه.\n6. قائمة بمديني المدين تتضمن اسم كل منهم وعنوانه، إن وجد، ومبلغ الدين المستحق له وأصل ذلك الدين وتاريخ نشأته واستحقاقه.\n7. كشف بالإجراءات القضائية المقامة من المدين أو عليه.\n8. أي بينات أخرى متعلقة بالطلب.","title":"مرفقات طلب الإشهار المقدم من المدين","memo":"⭐ يتضمن طلب المدين إقراراً بدخوله مرحلة الإعسار الوشيك أو الفعلي\n⭐ يرفق تقرير بأسباب الإعسار وتحليل مستقبل النشاط، وشهادة من جهة التسجيل\n⭐ يرفق القيود المالية والمحاسبية (الميزانية والبيانات المالية أو الدفاتر) للسنوات المالية الثلاث السابقة للطلب، وقوائم الدائنين والمدينين وكشف الأموال والإجراءات القضائية","qs":[{"q":"يجب أن يرفق المدين بطلب إشهار الإعسار القيود المالية والمحاسبية للسنوات المالية:","o":["الثلاث التي تسبق تقديم الطلب","الخمس التي تسبق تقديم الطلب","السنتين اللتين تسبقان تقديم الطلب","السنة التي تسبق تقديم الطلب"],"a":0},{"q":"أي مما يلي ليس من البينات التي نص القانون على إرفاقها بطلب المدين؟","o":["موافقة الهيئة العامة للدائنين على الطلب","قائمة بدائني المدين ومبالغ ديونهم","كشف بالإجراءات القضائية المقامة من المدين أو عليه","تقرير يتضمن أسباب الإعسار وتحليلاً لمستقبل النشاط الاقتصادي"],"a":0},{"q":"الشهادة التي تبين تاريخ تسجيل المدين وتسلسل التغييرات الحاصلة عليه تصدر عن:","o":["جهة تسجيل المدين","المحكمة المختصة","وكيل الإعسار","مدقق حسابات المدين"],"a":0}]},{"n":"9","chapter":"الفصل الثاني - إشهار الإعسار - أحكام عامة","notes":[],"source":"أ . إذا وجدت المحكمة ان الطلب موافق للشروط المنصوص عليها في المواد (6/و(7) و (8) من هذا القانون وثبت لها وفقا للبينات المرفقه به أن المستدعي معسر فتصدر قرارا باشهار إعسار المدين خلال مدة ثلاثين يوما من تاريخ تقديم الطلب دون الحاجة لاتخاذ أي إجراءات أخرى.\nب. إذا وجدت المحكمة أن البينات المقدمة من المدين في الطلب مخالفة لأحكام المادة (8) من هذا القانون فتمنح المدين مهلة خمسة عشر يوما لاستكمالها وإذا لم يمتثل المدين لأمرها فتقرر رد الطلب.","title":"البت في طلب الإشهار المقدم من المدين","memo":"⭐ إذا استوفى الطلب شروط المواد (6) و(7) و(8) وثبت الإعسار تصدر المحكمة قرار الإشهار خلال ثلاثين يوماً من تاريخ تقديم الطلب\n⭐ إذا كانت البينات مخالفة للمادة (8) تمنح المحكمة المدين مهلة خمسة عشر يوماً لاستكمالها وإلا ترد الطلب","qs":[{"q":"تصدر المحكمة قرارها بإشهار إعسار المدين بناء على طلبه المستوفي للشروط خلال مدة:","o":["ثلاثين يوماً من تاريخ تقديم الطلب","خمسة عشر يوماً من تاريخ تقديم الطلب","عشرة أيام من تاريخ تقديم الطلب","ستين يوماً من تاريخ تقديم الطلب"],"a":0},{"q":"قدم مدين طلب إشهار إعسار ووجدت المحكمة أن البينات المرفقة ناقصة، فإن المحكمة:","o":["تمنحه مهلة خمسة عشر يوماً لاستكمالها","ترد الطلب فوراً","تمنحه مهلة ثلاثين يوماً لاستكمالها","تحيل الطلب إلى المراقب لاستكماله"],"a":0},{"q":"إذا لم يمتثل المدين لأمر المحكمة باستكمال البينات خلال المهلة الممنوحة، فإن المحكمة:","o":["تقرر رد الطلب","تصدر قرار الإشهار استناداً إلى البينات المتوفرة","تعين خبيراً لاستكمال البينات","تمدد المهلة مدة مماثلة"],"a":0}]},{"n":"10","chapter":"الفصل الثاني - إشهار الإعسار - أحكام عامة","notes":[],"source":"أ . على أي دائن يتقدم بطلب إشهار الإعسار في مواجهة مدين أن يرفق بطلبه بينه على وجود دين له في ذمه المدين معين المقدار ومستحق الأداء وغير معلق على شرط.\nب. إذا كان الطلب مقدما من دائن المدين أو من المراقب فعلى المستدعي أن يثبت أن المدين في حالة إعسار فعلي .\nج. يعتبر دليلا على الاعسار الفعلي ما يلي:\n1. اذا باشر الدائن المستدعي أو أي من دائني المدين اجراءات التنفيذ على المدين بموجب آحكام قانون التنفيذ ولم يتمكن من تحصيل حقوقه من المدين.\n2. القاء الحجز التنفيذي على كامل أموال المدين.\n3. إذا هرب المدين أمواله أو باعها بغبن فاحش.\n4. اذا كان المدين شخصا طبيعيا وأصبح مجهول مكان الإقامة أو أنه أغلق مركز المصالح الرئيسة له إذا كان شخصا اعتباريا.\n5. صدور قرار من المحكمة يقضي بالاعتراف بإجراءات إعسار أجنبية رئيسة.\nد. للمدين دحض أي من الحالات المنصوص عليها في الفقرة (ج) من هذه المادة وإثبات قدرته على السداد وأن ذمته غير مشغولة للدائن المستدعي بدين مستحق الأداء.","title":"شروط طلب الدائن وأدلة الإعسار الفعلي","memo":"⭐ على الدائن طالب الإشهار إرفاق بينة على دين معين المقدار ومستحق الأداء وغير معلق على شرط\n⭐ على الدائن أو المراقب إثبات الإعسار الفعلي\n⭐ من أدلة الإعسار الفعلي: تعذر التحصيل بالتنفيذ، الحجز التنفيذي على كامل الأموال، تهريب الأموال أو بيعها بغبن فاحش، جهالة الإقامة أو إغلاق مركز المصالح، الاعتراف بإجراءات إعسار أجنبية رئيسة\n⭐ للمدين دحض هذه الحالات وإثبات قدرته على السداد","qs":[{"q":"يشترط في الدين الذي يستند إليه الدائن في طلب إشهار الإعسار أن يكون:","o":["معين المقدار ومستحق الأداء وغير معلق على شرط","مضموناً بحق عيني تبعي","ثابتاً بحكم قضائي قطعي","لا يقل عن (20%) من إجمالي ديون المدين"],"a":0},{"q":"أي مما يلي لا يعد دليلاً على الإعسار الفعلي وفقاً للمادة؟","o":["تأخر المدين في سداد دين واحد قبل مباشرة أي إجراءات تنفيذ","إلقاء الحجز التنفيذي على كامل أموال المدين","بيع المدين أمواله بغبن فاحش","صدور قرار بالاعتراف بإجراءات إعسار أجنبية رئيسة"],"a":0},{"q":"إذا قدم المراقب طلب إشهار الإعسار، فإن عليه إثبات أن المدين في حالة:","o":["إعسار فعلي","إعسار وشيك","إعسار وشيك أو فعلي","تعثر مؤقت في السداد"],"a":0}]},{"n":"11","chapter":"الفصل الثاني - إشهار الإعسار - أحكام عامة","notes":[],"source":"أ. اذا وجدت المحكمة أن طلب إشهار الإعسار المقدم من الدائنين او المراقب موافقا للشروط المنصوص عليها في المادة (10) من هذا القانون فتتولى تبليغه للمدين مع حافظة المستندات المرفقة به خلال مدة خمسة أيام من تاريخ تقديمه.\nب. للمدين أن يعترض على الطلب خلال مدة عشرة أيام من اليوم التالي لتاريخ تبلغه على أن يرفق باعتراضه البينات اللازمه لإثبات دفوعه وإذا لم يعترض المدين ورأت المحكمة أن الشروط المنصوص عليها في هذا القانون متحققة فتصدر قرارا بإشهار الإعسار خلال مدة خمسة عشر يوما من انتهاء المدة المنصوص عليها في هذه الفقرة.","title":"تبليغ طلب الدائنين واعتراض المدين","memo":"⭐ تبلغ المحكمة طلب الدائنين أو المراقب للمدين مع المستندات خلال خمسة أيام من تاريخ تقديمه\n⭐ للمدين الاعتراض خلال عشرة أيام من اليوم التالي لتاريخ تبلغه مع إرفاق البينات\n⭐ إذا لم يعترض وتحققت الشروط تصدر المحكمة قرار الإشهار خلال خمسة عشر يوماً من انتهاء مدة الاعتراض","qs":[{"q":"تتولى المحكمة تبليغ طلب الإشهار المقدم من الدائنين للمدين خلال مدة:","o":["خمسة أيام من تاريخ تقديمه","عشرة أيام من تاريخ تقديمه","ثلاثة أيام من تاريخ تقديمه","خمسة عشر يوماً من تاريخ تقديمه"],"a":0},{"q":"للمدين أن يعترض على طلب الإشهار المقدم من دائنيه خلال مدة:","o":["عشرة أيام من اليوم التالي لتاريخ تبلغه","خمسة أيام من تاريخ تبلغه","خمسة عشر يوماً من تاريخ تبلغه","ثلاثين يوماً من تاريخ تقديم الطلب"],"a":0},{"q":"إذا لم يعترض المدين على طلب الدائن وتحققت الشروط، تصدر المحكمة قرار الإشهار خلال:","o":["خمسة عشر يوماً من انتهاء مدة الاعتراض","ثلاثين يوماً من انتهاء مدة الاعتراض","عشرة أيام من تاريخ التبليغ","خمسة أيام من انتهاء مدة الاعتراض"],"a":0}]},{"n":"12","chapter":"الفصل الثاني - إشهار الإعسار - أحكام عامة","notes":[],"source":"أ. على المحكمة وخلال مدة خمسة أيام من تاريخ تقديم الاعتراض المنصوص عليه في الفقرة (ب) من المادة (11) من هذا القانون أن تقرر ما يلي:\n1. تعيين موعد للنظر في الطلب والاعتراض على أن لا يتجاوز مدة خمسه عشر يوما من تاريخ تقديم الاعتراض على الطلب .\n2. دعوة المدين والدائنين الذين قدموا طلب إشهار الإعسار للمحاكمة وللمحكمة أن تستمع لأقوال أي من الخصوم دون حضور الخصم الآخر، إذا رأت ذلك مناسبا.\n3. للمحكمة من تلقاء ذاتها او بناء على طلب أحد الخصوم أن تعين خبيرا أو أكثر لبيان رأيه في مدى تحقق أسباب إشهار الاعسار.\n4. للمحكمة من تلقاء ذاتها او بناء على طلب أي من الدائنين اتخاذ إجراءات تحفظية للمحافظة على قيمه أموال الإعسار وحماية حقوق الأطراف جميعهم أو أن تحد من صلاحيات المدين في ممارسة نشاطه الاقتصادي.\nب. تصدر المحكمة قرارها في الطلب بصفة الاستعجال وفي الأحوال جميعها خلال مدة عشرة أيام من تاريخ آخر جلسه وخلال مدة خمسة عشر يوما من تاريخ تقديم الاعتراض من المدين في حال عدم تعيين جلسات.","title":"إجراءات النظر في اعتراض المدين","memo":"⭐ خلال خمسة أيام من تقديم الاعتراض تعين المحكمة موعداً للنظر لا يتجاوز خمسة عشر يوماً من تقديم الاعتراض\n⭐ للمحكمة تعيين خبير أو أكثر واتخاذ إجراءات تحفظية من تلقاء ذاتها أو بطلب\n⭐ يصدر القرار بصفة الاستعجال خلال عشرة أيام من آخر جلسة، أو خلال خمسة عشر يوماً من تقديم الاعتراض في حال عدم تعيين جلسات","qs":[{"q":"يجب ألا يتجاوز الموعد الذي تعينه المحكمة للنظر في الطلب والاعتراض مدة:","o":["خمسة عشر يوماً من تاريخ تقديم الاعتراض","عشرة أيام من تاريخ تقديم الاعتراض","ثلاثين يوماً من تاريخ تقديم الاعتراض","خمسة أيام من تاريخ تقديم الاعتراض"],"a":0},{"q":"تصدر المحكمة قرارها في طلب الإشهار المعترض عليه، في حال عقد جلسات، خلال مدة:","o":["عشرة أيام من تاريخ آخر جلسة","خمسة عشر يوماً من تاريخ آخر جلسة","خمسة أيام من تاريخ آخر جلسة","ثلاثين يوماً من تاريخ آخر جلسة"],"a":0},{"q":"يحق للمحكمة اتخاذ إجراءات تحفظية للمحافظة على قيمة أموال الإعسار أثناء النظر في الاعتراض:","o":["من تلقاء ذاتها أو بناء على طلب أي من الدائنين","بناء على طلب المراقب فقط","بناء على طلب المدين فقط","بعد موافقة الهيئة العامة للدائنين"],"a":0}]},{"n":"13","chapter":"الفصل الثاني - إشهار الإعسار - أحكام عامة","notes":[],"source":"تنظر المحكمة في طلب إشهار الإعسار تدقيقا وإذا توافرت الشروط المنصوص عليها في المواد السابقة كافة تصدر المحكمة قرارا باشهار الاعسار علي أن يتضمن القرار ما يلي:\nأ. المعلومات الشخصية والتجاريه الخاصة بأطراف الطلب بما في ذلك موطن كل منهم.\nب. اذا كان الطلب مقدما من دائني المدين أو المراقب فيجب أن يتضمن القرار الزام المدين بتقديم الوثائق المنصوص عليها في المادة (8) من هذا القانون خلال مدة عشرة أيام من تاريخ صدور قرار إشهار الإعسار.\nج. تحديد صلاحيات المدين في إدارة أمواله والتصرف فيها وإذا قررت المحكمة فرض قيود على المدين في إدارة ذمة الاعسار أو التصرف فيها فيشتمل القرار على أمر لمديني المدين بسداد أي التزامات مستحقة للمدين لوكيل الإعسار.\nد. تعيين وكيل الإعسار مع بيان اسمه ورقمه الوطني ورقم رخصة المزاولة، وعنوانه للاتصال والتبليغ وتحديد صلاحياته في إدارة ذمة الإعسار والتصرف فيها.\nهـ. أي إجراءات تحفظية تتخذها المحكمة لحماية ذمة الإعسار الى حين تولي وكيل الإعسار مهامه.\nو. دعوة دائني المدين للتقدم بمطالباتهم لوكيل الاعسار خلال مدة ثلاثين يوما من تاريخ نشر قرار إشهار الإعسار في الجريدة الرسمية وفقا لأحكام هذا القانون.","title":"مضمون قرار إشهار الإعسار","memo":"⭐ تنظر المحكمة في الطلب تدقيقاً\n⭐ إذا قدم الطلب من الدائنين أو المراقب يلزم القرار المدين بتقديم وثائق المادة (8) خلال عشرة أيام من صدور قرار الإشهار\n⭐ يتضمن القرار تعيين وكيل الإعسار وتحديد صلاحياته وصلاحيات المدين، ودعوة الدائنين لتقديم مطالباتهم خلال ثلاثين يوماً من نشر القرار في الجريدة الرسمية","qs":[{"q":"تنظر المحكمة في طلب إشهار الإعسار:","o":["تدقيقاً","مرافعةً في جميع الأحوال","بحضور الهيئة العامة للدائنين","بعد سماع رأي المراقب"],"a":0},{"q":"إذا كان طلب الإشهار مقدماً من الدائنين، يلزم قرار الإشهار المدين بتقديم الوثائق المنصوص عليها في المادة (8) خلال:","o":["عشرة أيام من تاريخ صدور قرار الإشهار","ثلاثين يوماً من تاريخ صدور قرار الإشهار","خمسة أيام من تاريخ صدور قرار الإشهار","خمسة عشر يوماً من تاريخ نشر القرار"],"a":0},{"q":"يتضمن قرار الإشهار دعوة دائني المدين للتقدم بمطالباتهم لوكيل الإعسار خلال مدة:","o":["ثلاثين يوماً من تاريخ نشر قرار الإشهار في الجريدة الرسمية","ثلاثين يوماً من تاريخ صدور قرار الإشهار","ستين يوماً من تاريخ نشر قرار الإشهار في الجريدة الرسمية","خمسة عشر يوماً من تاريخ صدور قرار الإشهار"],"a":0},{"q":"إذا قررت المحكمة فرض قيود على المدين في إدارة ذمة الإعسار، يشتمل القرار على أمر لمديني المدين بسداد التزاماتهم المستحقة إلى:","o":["وكيل الإعسار","المدين نفسه","صندوق المحكمة","لجنة الدائنين"],"a":0}]},{"n":"14","chapter":"الفصل الثاني - إشهار الإعسار - أحكام عامة","notes":[],"source":"أ . يتولى وكيل الإعسار خلال مدة لا تتجاوز خمسة ايام من تاريخ صدور قرار إشهار الإعسار تبليغ الدائنين المسجلين في قيود وسجلات المدين و دعوتهم للتقدم بمطالباتهم وفقا للإجراءات المنصوص عليها في هذا القانون.\nب. يتولى وكيل الإعسار تبليغ قرار إشهار الإعسار لدائرة ضريبة الدخل والمبيعات والمؤسسة العامة للضمان الاجتماعي وللجهة المسجل لديها المدين ولممثل العمال إن وجد .","title":"تبليغ الدائنين والجهات الرسمية بالإشهار","memo":"⭐ يبلغ وكيل الإعسار الدائنين المسجلين في قيود المدين خلال مدة لا تتجاوز خمسة أيام من صدور قرار الإشهار\n⭐ يبلغ وكيل الإعسار القرار لدائرة ضريبة الدخل والمبيعات والمؤسسة العامة للضمان الاجتماعي وجهة تسجيل المدين وممثل العمال إن وجد","qs":[{"q":"يتولى وكيل الإعسار تبليغ الدائنين المسجلين في قيود المدين خلال مدة لا تتجاوز:","o":["خمسة أيام من تاريخ صدور قرار الإشهار","عشرة أيام من تاريخ صدور قرار الإشهار","خمسة عشر يوماً من تاريخ صدور قرار الإشهار","ثلاثين يوماً من تاريخ نشر قرار الإشهار"],"a":0},{"q":"أي من الجهات التالية لم يرد ذكرها ضمن الجهات التي يبلغها وكيل الإعسار بقرار الإشهار؟","o":["البنك المركزي الأردني","دائرة ضريبة الدخل والمبيعات","المؤسسة العامة للضمان الاجتماعي","ممثل العمال إن وجد"],"a":0}]},{"n":"15","chapter":"الفصل الثاني - إشهار الإعسار - أحكام عامة","notes":[],"source":"أ. يكون القرار الصادر عن المحكمة بإشهار الإعسار قابلا للاستئناف لدى محكمة الاستئناف المختصة خلال مدة عشرة أيام من تاريخ صدوره أو تبليغه حسب مقتضى الحال.\nب. لا يوقف استئناف قرار إشهار الإعسار إجراءات الإعسار ولمحكمة الاستئناف اتخاذ أي من الإجراءات التحفظية التي تراها مناسبة.","title":"استئناف قرار إشهار الإعسار","memo":"⭐ يستأنف قرار الإشهار لدى محكمة الاستئناف المختصة خلال عشرة أيام من تاريخ صدوره أو تبليغه\n⭐ لا يوقف الاستئناف إجراءات الإعسار، ولمحكمة الاستئناف اتخاذ إجراءات تحفظية","qs":[{"q":"مدة استئناف قرار إشهار الإعسار هي:","o":["عشرة أيام من تاريخ صدوره أو تبليغه","خمسة عشر يوماً من تاريخ صدوره أو تبليغه","ثلاثون يوماً من تاريخ صدوره أو تبليغه","خمسة أيام من تاريخ صدوره أو تبليغه"],"a":0},{"q":"يترتب على استئناف قرار إشهار الإعسار:","o":["عدم وقف إجراءات الإعسار","وقف إجراءات الإعسار حكماً","وقف إجراءات الإعسار بقرار من المحكمة التي أصدرته","وقف المرحلة التمهيدية فقط"],"a":0}]},{"n":"16","chapter":"الفصل الثاني - إشهار الإعسار - أحكام عامة","notes":[],"source":"أ.1. ينشر قرار إشهار الإعسار في الجريدة الرسمية مع بيانات المدين والقيود الواردة على صلاحياته في إدارة أمواله والتصرف فيها، وتحديد اسم وكيل الإعسار مع الطلب من الدائنين التقدم بمطالباتهم ويعتبر قرار الإشهار نافذا من تاريخ هذا النشر .\n2. تلزم المحكمة المدين أو وكيل الإعسار بالإعلان عن قرار إشهار الإعسار عن طريق نشر إعلان في صحيفة يومية محليه أو صحيفه صادرة في أي دوله اخرى يكون للمدين فيها نشاط اقتصادي و بأي طريقة أخرى تراها المحكمة مناسبة.\nب. يسجل قرار إشهار الإعسار في سجل الشركات لدى دائرة مراقبة الشركات وفي سجل الإعسار وفي أي سجل خاص بأموال المدين.\nج. ينشر قرار إشهار الإعسار على الموقع الإلكتروني للمدين، إن وجد.","title":"نشر قرار الإشهار وتسجيله","memo":"⭐ ينشر قرار الإشهار في الجريدة الرسمية ويعتبر نافذاً من تاريخ هذا النشر\n⭐ تلزم المحكمة المدين أو وكيل الإعسار بنشر إعلان في صحيفة يومية محلية أو صحيفة في دولة أخرى للمدين فيها نشاط\n⭐ يسجل القرار في سجل الشركات لدى دائرة مراقبة الشركات وسجل الإعسار وأي سجل خاص بأموال المدين، وينشر على الموقع الإلكتروني للمدين إن وجد","qs":[{"q":"يعتبر قرار إشهار الإعسار نافذاً من تاريخ:","o":["نشره في الجريدة الرسمية","صدوره عن المحكمة","تبليغه للمدين","اكتسابه الدرجة القطعية"],"a":0},{"q":"أي مما يلي ليس من السجلات التي يسجل فيها قرار إشهار الإعسار وفقاً للمادة؟","o":["سجل الأحوال المدنية","سجل الشركات لدى دائرة مراقبة الشركات","سجل الإعسار","أي سجل خاص بأموال المدين"],"a":0},{"q":"تلزم المحكمة بالإعلان عن قرار الإشهار في صحيفة يومية محلية:","o":["المدين أو وكيل الإعسار","المراقب","الدائن طالب الإشهار","لجنة الدائنين"],"a":0}]},{"n":"17","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"أ. اذا كان طلب إشهار الإعسار مقدما من المدين يحتفظ بصلاحية إدارة اعماله المعتادة تحت إشراف وكيل الإعسار.\nب. اذا كان الطلب مقدما من الدائنين أو المراقب فتعلق صلاحيات المدين في إدارة أموال ذمة الاعسار والتصرف فيها، ويقوم وكيل الاعسار بممارسة هذه الصلاحيات في حدود تسيير الأعمال المعتادة.\nج. لدائني المدين ولوكيل الإعسار، في أي وقت بعد إشهار الاعسار ولأسباب مبررة، أن يطلبوا من المحكمة أن تقرر وقف صلاحيه المدين في إدارة ذمة الاعسار والتصرف فيها، أو أن تبقيها في يده إذا ثبت أن ذلك يحقق مصلحة النشاط الاقتصادي ويحمى دائني الإعسار.\nد. للمدين الذي احتفظ بحق إدارة أمواله متابعة أي إجراءات قضائية منظورة كمدع أو مدعى عليه بعد إشهار الإعسار على أنه لا يحق له إسقاط تلك الاجراءات بشكل اختياري أو الإقرار أو الموافقة على نتيجتها إلا بموافقة وكيل الإعسار.\nهـ. إذا صدر قرار بتجريد المدين من صلاحية إدارة ذمة الإعسار والتصرف فيها فيحل وكيل الإعسار محل المدين سواء بصفته مدعيا أو مدعى عليه في أي إجراءات قضائية مقامة قبل إشهار الإعسار.\nو. إذا تولى وكيل الإعسار إدارة أعمال المدين فيكون مسؤولا عن القيام بالإجراءات اللازمة لضمان استمرار الاعمال المعتادة للمدين.\nز. للمحكمة بناء على طلب المدين أو وكيل الاعسار أن تقرر تعليق النشاط الاقتصادي كليا أو جزئيا بناء على مبررات موضوعية وبعد الاستماع لأقوال المدين ووكيل الإعسار وممثلي العاملين لدى المدين .\nح. لا تحول أحكام هذه المادة دون حق المدين في توكيل محام للحفاظ على حقوقه المقررة وفقا لاحكام هذا القانون .","title":"صلاحيات المدين في الإدارة بعد الإشهار","memo":"⭐ إذا كان الطلب من المدين يحتفظ بإدارة أعماله المعتادة تحت إشراف وكيل الإعسار\n⭐ إذا كان الطلب من الدائنين أو المراقب تعلق صلاحيات المدين ويمارسها وكيل الإعسار في حدود تسيير الأعمال المعتادة\n⭐ المدين المحتفظ بالإدارة لا يسقط الإجراءات القضائية أو يقر بها إلا بموافقة وكيل الإعسار\n⭐ للمحكمة بطلب المدين أو وكيل الإعسار تعليق النشاط كلياً أو جزئياً بعد سماع المدين والوكيل وممثلي العاملين","qs":[{"q":"إذا كان طلب إشهار الإعسار مقدماً من المدين، فإن صلاحية إدارة أعماله المعتادة:","o":["يحتفظ بها المدين تحت إشراف وكيل الإعسار","تنتقل إلى وكيل الإعسار","تعلق إلى حين انتهاء المرحلة التمهيدية","تنتقل إلى لجنة الدائنين"],"a":0},{"q":"أشهر إعسار شركة بناء على طلب أحد دائنيها، فإن صلاحيات الشركة في إدارة أموال ذمة الإعسار:","o":["تعلق ويمارسها وكيل الإعسار في حدود تسيير الأعمال المعتادة","تبقى بيد الشركة تحت إشراف المراقب","تنتقل إلى الدائن طالب الإشهار","تبقى بيد الشركة دون قيود"],"a":0},{"q":"لا يحق للمدين الذي احتفظ بحق إدارة أمواله إسقاط إجراءات قضائية منظورة بشكل اختياري إلا بموافقة:","o":["وكيل الإعسار","المحكمة","لجنة الدائنين","الهيئة العامة للدائنين"],"a":0},{"q":"تقرر المحكمة تعليق النشاط الاقتصادي للمدين كلياً أو جزئياً بناء على طلب:","o":["المدين أو وكيل الإعسار","لجنة الدائنين فقط","المراقب فقط","أي دائن من دائني الإعسار"],"a":0}]},{"n":"18","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"أ. للمحكمة بناء على طلب وكيل الإعسار، أن تقرر عدم نفاذ أي تصرف قام به المدين خلافا لأحكام المادة (17) من هذا القانون، على أنه يجوز لوكيل الإعسار إجازة أي تصرف ادى لزيادة فعلية في قيمة ذمة الإعسار أو أثر إيجابيا على الدائنين.\nب. يخضع طلب عدم نفاذ التصرفات المنصوص عليه في الفقرة (أ) من هذه المادة لإجراءات الدعاوى المستعجلة المنصوص عليها في قانون أصول المحاكمات المدنية.","title":"عدم نفاذ تصرفات المدين المخالفة","memo":"⭐ للمحكمة بطلب وكيل الإعسار تقرير عدم نفاذ تصرف المدين المخالف للمادة (17)\n⭐ لوكيل الإعسار إجازة التصرف الذي أدى لزيادة فعلية في ذمة الإعسار أو أثّر إيجابياً على الدائنين\n⭐ يخضع طلب عدم النفاذ لإجراءات الدعاوى المستعجلة في قانون أصول المحاكمات المدنية","qs":[{"q":"تقرر المحكمة عدم نفاذ تصرف المدين المخالف لأحكام المادة (17) بناء على طلب:","o":["وكيل الإعسار","المراقب","لجنة الدائنين","أي دائن مضمون"],"a":0},{"q":"يجوز لوكيل الإعسار إجازة تصرف المدين المخالف إذا:","o":["أدى لزيادة فعلية في قيمة ذمة الإعسار أو أثر إيجابياً على الدائنين","وافق عليه أغلبية الدائنين المضمونين","تم قبل نشر قرار الإشهار بثلاثين يوماً","كانت قيمته لا تتجاوز (20%) من ذمة الإعسار"],"a":0},{"q":"يخضع طلب عدم نفاذ تصرفات المدين المخالفة لأحكام المادة (17) لإجراءات:","o":["الدعاوى المستعجلة المنصوص عليها في قانون أصول المحاكمات المدنية","التحكيم","الدعاوى العادية أمام محكمة الصلح","التدقيق دون مرافعة لدى محكمة الاستئناف"],"a":0}]},{"n":"19","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"لا يجوز للمدين أو وكيل الإعسار بيع أموال ذمة الإعسار أو التصرف فيها خلال المرحلة التمهيديه، ويستثنى من ذلك ما يلي:\nأ. التصرفات الجارية ضمن العمل المعتاد.\nب. بيع الأموال التي تعتبر ضرورية لاستمرار النشاط الاقتصادي أو للحصول على السيولة اللازمة لاستمراره في حال تعذر الحصول على الائتمان.\nج. بيع الأموال التي لا تعتبر ضرورية لاستمرار النشاط الاقتصادي إذا جرى بيعها بسعر السوق وإذا كانت أموالا غير منقولة يجب أن لا يقل ثمن بيعها عن (%90) من ثمن المثل .\nد. يجوز بيع جزء من النشاط الاقتصادي في أي وقت خلال المرحله التمهيدية شريطة مراعاة ما يلي:\n1. أن يكون من غير المحتمل أن يؤثر البيع سلبا على فرص إعادة تنظيم باقي النشاطات وهيكلة النشاط الاقتصادي بشكل جوهري.\n2. أن يكون السعر المعروض مساويا لسعر السوق.\nهـ. باستثناء ما ورد في الفقرة (أ) من هذه المادة يجب الحصول على موافقه مسبقه من المحكمة على إجراء التصرفات المنصوص عليها في هذه المادة وللمحكمة أن تستمع لأقوال لجنة الدائنين وممثلي العاملين لدى المدين.","title":"حظر التصرف خلال المرحلة التمهيدية","memo":"⭐ الأصل: لا يجوز للمدين أو وكيل الإعسار بيع أموال ذمة الإعسار أو التصرف فيها خلال المرحلة التمهيدية\n⭐ الاستثناءات: التصرفات الجارية، بيع الأموال الضرورية لاستمرار النشاط أو للسيولة، بيع غير الضرورية بسعر السوق (وغير المنقولة بما لا يقل عن (90%) من ثمن المثل)، بيع جزء من النشاط بسعر السوق\n⭐ عدا التصرفات الجارية يجب الحصول على موافقة مسبقة من المحكمة","qs":[{"q":"خلال المرحلة التمهيدية، يجب ألا يقل ثمن بيع الأموال غير المنقولة غير الضرورية لاستمرار النشاط عن:","o":["(90%) من ثمن المثل","(80%) من ثمن المثل","(75%) من ثمن المثل","(100%) من ثمن المثل"],"a":0},{"q":"أي من التصرفات التالية لا يحتاج إلى موافقة مسبقة من المحكمة خلال المرحلة التمهيدية؟","o":["التصرفات الجارية ضمن العمل المعتاد","بيع الأموال الضرورية لاستمرار النشاط الاقتصادي","بيع جزء من النشاط الاقتصادي","بيع الأموال غير الضرورية لاستمرار النشاط بسعر السوق"],"a":0},{"q":"يشترط لبيع جزء من النشاط الاقتصادي للمدين خلال المرحلة التمهيدية أن يكون السعر المعروض:","o":["مساوياً لسعر السوق","لا يقل عن (90%) من ثمن المثل","معتمداً من لجنة الدائنين","أعلى من القيمة الدفترية"],"a":0}]},{"n":"20","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"على المدين أو أي شخص يتولى إدارته، إذا كان شخصا اعتباريا، التعاون في أي شأن لازم لسير إجراءات الاعسار بما في ذلك تزويد المحكمه ووكيل الإعسار بالمعلومات والإيضاحات التي يطلبونها.","title":"واجب المدين في التعاون","memo":"⭐ على المدين أو من يتولى إدارته (إذا كان شخصاً اعتبارياً) التعاون في كل ما يلزم لسير إجراءات الإعسار، ومنه تزويد المحكمة ووكيل الإعسار بالمعلومات والإيضاحات","qs":[{"q":"يلتزم المدين أو من يتولى إدارته بتزويد ............ بالمعلومات والإيضاحات التي يطلبونها لسير إجراءات الإعسار:","o":["المحكمة ووكيل الإعسار","المراقب ولجنة الدائنين","الهيئة العامة للدائنين فقط","دائرة ضريبة الدخل والمبيعات"],"a":0},{"q":"إذا كان المدين شخصاً اعتبارياً، فإن واجب التعاون في إجراءات الإعسار يقع على:","o":["المدين أو أي شخص يتولى إدارته","الشركاء والمساهمين فقط","وكيل الإعسار وحده","المراقب"],"a":0}]},{"n":"21","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"أ. لا تسمع أي دعوى ضد المدين بعد إشهار الإعسار وعلى أي شخص يدعي وجود دين له على المدين أن يسجل مطالبته وفقا للإجراءات المنصوص عليها في هذا القانون.\nب. تستمر المحاكم وهيئات التحكيم المختصة بالنظر في الدعاوى المقامة على المدين إلي حين صدور أحكام فيها.\nج. على الرغم مما ورد في الفقرة (ب) من هذه المادة، لوكيل الاعسار أن يطلب من المحكمة إحاله أي دعوى منظورة لدى محكمة اخرى سواء أكان المدين مدعيا أم مدعى عليه اليها إذا كانت قيمة المطالبة في تلك الدعوى أو طبيعتها تؤثر بشكل جوهري على سير إجراءات الإعسار وفي الأحوال جميعها إذا كانت قيمة الدعوى تتجاوز (%20) من إجمالي ديون المدين.","title":"الدعاوى ضد المدين بعد الإشهار","memo":"⭐ لا تسمع أي دعوى ضد المدين بعد الإشهار، وعلى مدعي الدين تسجيل مطالبته وفق إجراءات القانون\n⭐ تستمر المحاكم وهيئات التحكيم في نظر الدعاوى المقامة قبل الإشهار حتى صدور أحكام فيها\n⭐ لوكيل الإعسار طلب إحالة الدعوى المنظورة إلى محكمة الإعسار إذا أثرت جوهرياً، وفي جميع الأحوال إذا تجاوزت قيمتها (20%) من إجمالي ديون المدين","qs":[{"q":"دائن يرغب بإقامة دعوى مطالبة ضد المدين بعد إشهار إعساره، فإن عليه:","o":["تسجيل مطالبته وفقاً للإجراءات المنصوص عليها في قانون الإعسار","إقامة الدعوى أمام محكمة البداية بصورة عادية","إقامة الدعوى بعد الحصول على إذن وكيل الإعسار","اللجوء إلى التحكيم حصراً"],"a":0},{"q":"لوكيل الإعسار في جميع الأحوال طلب إحالة الدعوى المنظورة لدى محكمة أخرى إلى المحكمة إذا تجاوزت قيمتها:","o":["(20%) من إجمالي ديون المدين","(10%) من إجمالي ديون المدين","(5%) من إجمالي ديون المدين","(50%) من إجمالي ديون المدين"],"a":0},{"q":"الدعاوى المقامة على المدين أمام المحاكم وهيئات التحكيم قبل الإشهار:","o":["تستمر في نظرها إلى حين صدور أحكام فيها","توقف حكماً بمجرد الإشهار","تشطب وتسجل كمطالبات","تحال جميعها إلى محكمة الإعسار"],"a":0}]},{"n":"22","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"أ. لا يجوز التنفيذ على أموال المدين بعد إشهار الإعسار وتوقف إجراءات التنفيذ التي بدأت قبل إشهار الإعسار وعلى المحكوم له أن يسجل مطالبته من خلال إجراءات الإعسار ويلتزم وكيل الإعسار بإدراج الدين تلقائيا في قائمة الدائنين دون أن يعد ذلك تنازلا عن حقه في استئناف قرار الحكم وفقا لأحكام التشريعات النافذة.\nب. لا يجوز إلقاء الحجز على أي من أموال المدين أو حبسها لاستيفاء أي دين عليه مهما كان أصله وطبيعته بما في ذلك الديون المستحقة للخزينة بعد إشهار الإعسار.\nج. على الرغم مما ورد في الفقرتين (أ) و(ب) من هذه المادة لأصحاب الحقوق المضمونة التنفيذ على ضماناتهم التي لا يؤثر التنفيذ عليها في استمرار النشاط الاقتصادي للمدين على أن يتم تسليم حصيلة التنفيذ الى وكيل الإعسار ليتم توزيعها وفقا لأحكام هذا القانون .\nد. يسري حظر التنفيذ والحجز المنصوص عليه في هذه المادة لمدة ستة أشهر من تاريخ إشهار الإعسار أو الى حين الموافقة على خطة إعادة التنظيم أيهما أسبق.","title":"وقف التنفيذ والحجز بعد الإشهار","memo":"⭐ لا يجوز التنفيذ على أموال المدين بعد الإشهار وتوقف إجراءات التنفيذ السابقة، ويدرج وكيل الإعسار دين المحكوم له تلقائياً\n⭐ لا يجوز الحجز على أموال المدين لأي دين بما في ذلك ديون الخزينة\n⭐ لأصحاب الحقوق المضمونة التنفيذ على ضمانات لا تؤثر في استمرار النشاط على أن تسلم الحصيلة لوكيل الإعسار\n⭐ يسري الحظر ستة أشهر من الإشهار أو حتى الموافقة على خطة إعادة التنظيم أيهما أسبق","qs":[{"q":"يسري حظر التنفيذ والحجز على أموال المدين لمدة:","o":["ستة أشهر من تاريخ الإشهار أو إلى حين الموافقة على خطة إعادة التنظيم أيهما أسبق","سنة من تاريخ الإشهار أو إلى حين الموافقة على خطة إعادة التنظيم أيهما أسبق","ستة أشهر من تاريخ الإشهار أو إلى حين الموافقة على خطة إعادة التنظيم أيهما أبعد","طوال مدة إجراءات الإعسار"],"a":0},{"q":"بعد إشهار الإعسار، فإن الديون المستحقة للخزينة على المدين:","o":["لا يجوز إلقاء الحجز على أموال المدين لاستيفائها","يجوز الحجز لاستيفائها لأنها ديون عامة","تستوفى بالتنفيذ المباشر دون المرور بإجراءات الإعسار","يجوز الحجز لاستيفائها بقرار من وزير المالية"],"a":0},{"q":"إذا نفذ صاحب الحق المضمون على ضمانته التي لا يؤثر التنفيذ عليها في استمرار نشاط المدين، فإن حصيلة التنفيذ:","o":["تسلم إلى وكيل الإعسار ليتم توزيعها وفقاً لأحكام القانون","يحتفظ بها صاحب الحق المضمون كاملة","تودع في صندوق المحكمة لحين انتهاء التصفية","توزع على الدائنين الممتازين مباشرة"],"a":0}]},{"n":"23","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"لا يؤثر إشهار الإعسار على اتفاقيات الوساطة والتحكيم التي يكون المدين طرفا فيها على أنه يحق للمحكمة تعليق سريان هذه الاتفاقيات إذا وجدت أنها تؤسر سلبا على سير إجراءات الإعسار.","title":"أثر الإشهار على اتفاقيات الوساطة والتحكيم","memo":"⭐ لا يؤثر الإشهار على اتفاقيات الوساطة والتحكيم التي يكون المدين طرفاً فيها\n⭐ للمحكمة تعليق سريانها إذا أثرت سلباً على سير إجراءات الإعسار","qs":[{"q":"ما أثر إشهار الإعسار على اتفاقيات التحكيم التي يكون المدين طرفاً فيها؟","o":["لا يؤثر عليها، وللمحكمة تعليق سريانها إذا أثرت سلباً على إجراءات الإعسار","تنقضي حكماً بمجرد الإشهار","تعتبر باطلة بطلاناً مطلقاً","يجوز لوكيل الإعسار إلغاؤها دون الرجوع للمحكمة"],"a":0},{"q":"الجهة التي يحق لها تعليق سريان اتفاقيات الوساطة والتحكيم التي يكون المدين طرفاً فيها إذا أثرت سلباً على سير إجراءات الإعسار هي:","o":["المحكمة","وكيل الإعسار","لجنة الدائنين","المراقب"],"a":0}]},{"n":"24","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"لا يؤثر إشهار الإعسار على حق دائن المدين في إجراء التقاص بين الديون المستحقة عليه والديون التي كانت مستحقة له لدى المدين قبل تاريخ إشهار الإعسار.","title":"التقاص بعد الإشهار","memo":"⭐ لا يؤثر الإشهار على حق الدائن في التقاص بين ما عليه للمدين وما كان مستحقاً له لدى المدين قبل تاريخ إشهار الإعسار","qs":[{"q":"دائن للمدين كان له دين مستحق قبل إشهار الإعسار، وعليه دين للمدين، فإن إشهار الإعسار:","o":["لا يؤثر على حقه في إجراء التقاص بين الدينين","يمنعه من إجراء التقاص","يجيز له التقاص بموافقة لجنة الدائنين فقط","يجيز التقاص بعد انتهاء المرحلة التمهيدية فقط"],"a":0},{"q":"يشترط لإجراء الدائن التقاص بعد إشهار الإعسار أن تكون الديون المستحقة له لدى المدين مستحقة:","o":["قبل تاريخ إشهار الإعسار","بعد تاريخ إشهار الإعسار","خلال المرحلة التمهيدية","بعد الموافقة على خطة إعادة التنظيم"],"a":0}]},{"n":"25","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"أ. يتوقف احتساب الفوائد وغرامات التأخير على ديون الإعسار من تاريخ إشهار الإعسار.\nب. لا تسري أحكام الفقرة (أ) من هذه المادة على الفوائد المستحقة على أجور العاملين بحيث تتحقق عليها فائدة على أساس معدل أعلى فائدة تدفعها البنوك على الودائع بتاريخ إشهار الإعسار.","title":"وقف الفوائد وغرامات التأخير","memo":"⭐ يتوقف احتساب الفوائد وغرامات التأخير على ديون الإعسار من تاريخ الإشهار\n⭐ يستثنى: الفوائد على أجور العاملين، وتحتسب على أساس أعلى فائدة تدفعها البنوك على الودائع بتاريخ الإشهار","qs":[{"q":"يتوقف احتساب الفوائد وغرامات التأخير على ديون الإعسار من تاريخ:","o":["إشهار الإعسار","تقديم طلب الإشهار","الموافقة على خطة إعادة التنظيم","بدء مرحلة التصفية"],"a":0},{"q":"تستثنى من وقف احتساب الفوائد بعد إشهار الإعسار الفوائد المستحقة على:","o":["أجور العاملين","الديون المضمونة","ديون الخزينة","التسهيلات المصرفية"],"a":0},{"q":"تحتسب الفائدة على أجور العاملين بعد إشهار الإعسار على أساس:","o":["أعلى فائدة تدفعها البنوك على الودائع بتاريخ الإشهار","متوسط الفائدة على القروض بتاريخ الإشهار","الفائدة القانونية المحددة في القانون المدني","الفائدة المتفق عليها في عقد العمل"],"a":0}]},{"n":"26","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"يترتب على إشهار الإعسار وقف مرور الزمن المانع من سماع الدعاوى للمطالبة بحقوق دائني المدين ولا يسري حكم هذه المادة على الدعاوى في مواجهة كفلاء المدين والمدينين الملتزمين بالتكافل والتضامن معه.","title":"وقف مرور الزمن","memo":"⭐ يترتب على الإشهار وقف مرور الزمن المانع من سماع دعاوى دائني المدين\n⭐ لا يسري ذلك على الدعاوى في مواجهة كفلاء المدين والمدينين المتكافلين والمتضامنين معه","qs":[{"q":"يترتب على إشهار الإعسار بالنسبة لمرور الزمن المانع من سماع دعاوى دائني المدين:","o":["وقف مرور الزمن","قطع مرور الزمن وبدء مدة جديدة","سقوط الحق في المطالبة","مضاعفة مدة مرور الزمن"],"a":0},{"q":"لا يسري حكم وقف مرور الزمن بسبب الإشهار على الدعاوى المقامة في مواجهة:","o":["كفلاء المدين والمدينين المتكافلين والمتضامنين معه","المدين نفسه","وكيل الإعسار","مديني المدين"],"a":0}]},{"n":"27","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"أ. لا يؤثر إشهار الإعسار على استمرار العقود الجاري تنفيذها ولغايات هذا القانون تعني عبارة العقد الجاري تنفيذه بأنه العقد الذي لم يستكمل المدين ولا الطرف الآخر تنفيذه بتاريخ اشهار الإعسار.\nب.1. لوكيل الإعسار أو للمدين بإشراف وكيل الإعسار حسب مقتضى الحال ان يستمر في تنفيذ العقد الجاري تنفيذه وأن يطالب الطرف الاخر بتنفيد التزاماته بالكامل.\n2. للطرف الآخر أن يطلب من وكيل الإعسار أو من المدين باشراف وكيل الإعسار أن يتخذ قرارا يتعلق برغبته في الاستمرار في تنفيذ العقد خلال مدة خمسة أيام من تاريخ تبلغ الطلب وإلا سقط الحق في ذلك .\nج. لوكيل الإعسار أو للمدين بإشراف وكيل الإعسار حسب مقتضى الحال أن يطلب إنهاء العقد الجاري تنفيذه إذا كان ذلك يحقق مصلحة لإجراءات الإعسار وفي هذه الحالة يسقط التزام الطرفين بتنفيذ باقي الالتزامات بموجبه وللطرف الآخر المطالبة بالضرر الناشئ عن ذلك وفق شروط العقد وتعتبر المطالبة بالضرر دين إعسار غير مضمون.","title":"العقود الجاري تنفيذها","memo":"⭐ لا يؤثر الإشهار على العقود الجاري تنفيذها، وهي العقود التي لم يستكمل المدين ولا الطرف الآخر تنفيذها بتاريخ الإشهار\n⭐ للطرف الآخر مطالبة وكيل الإعسار باتخاذ قرار بالاستمرار خلال خمسة أيام من تبلغ الطلب وإلا سقط الحق\n⭐ عند إنهاء العقد يسقط التزام الطرفين، وتعتبر مطالبة الطرف الآخر بالضرر دين إعسار غير مضمون","qs":[{"q":"يُقصد بالعقد الجاري تنفيذه وفقاً لقانون الإعسار:","o":["العقد الذي لم يستكمل المدين ولا الطرف الآخر تنفيذه بتاريخ إشهار الإعسار","العقد الذي نفذه المدين كاملاً ولم ينفذه الطرف الآخر","كل عقد أبرمه المدين خلال السنة السابقة للإشهار","العقد الذي أبرمه وكيل الإعسار بعد الإشهار"],"a":0},{"q":"يجب على وكيل الإعسار اتخاذ قرار بشأن الاستمرار في تنفيذ العقد بناء على طلب الطرف الآخر خلال:","o":["خمسة أيام من تاريخ تبلغ الطلب","عشرة أيام من تاريخ تبلغ الطلب","خمسة عشر يوماً من تاريخ تبلغ الطلب","ثلاثين يوماً من تاريخ تبلغ الطلب"],"a":0},{"q":"إذا أنهى وكيل الإعسار عقداً جارياً تنفيذه، فإن مطالبة الطرف الآخر بالضرر الناشئ عن ذلك تعتبر:","o":["دين إعسار غير مضمون","ديناً في مواجهة إجراءات الإعسار","ديناً ممتازاً","ديناً أدنى في مرتبة الأولوية"],"a":0}]},{"n":"28","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"يقع باطلا كل شرط في عقد يكون المدين طرفا فيه إذا منح الطرف الاخر حق إنهاء ذلك العقد أو نص على انهائه تلقائيا في حال إشهار إعسار المدين أو ما يماثله من إجراءات.","title":"بطلان شرط الإنهاء بسبب الإعسار","memo":"⭐ يقع باطلاً كل شرط يمنح الطرف الآخر حق إنهاء العقد أو ينص على إنهائه تلقائياً عند إشهار إعسار المدين أو ما يماثله","qs":[{"q":"نص عقد توريد على حق المورد في إنهاء العقد تلقائياً عند إشهار إعسار المدين، فإن هذا الشرط:","o":["يقع باطلاً","صحيح ونافذ","موقوف على موافقة وكيل الإعسار","صحيح إذا وافقت عليه المحكمة"],"a":0},{"q":"أي من الشروط التعاقدية التالية يقع باطلاً وفقاً لقانون الإعسار؟","o":["شرط ينص على انتهاء العقد تلقائياً في حال إشهار إعسار المدين","شرط جزائي عند تأخر المدين في التنفيذ","شرط يحدد مدة العقد بسنة واحدة","شرط التحكيم في المنازعات الناشئة عن العقد"],"a":0}]},{"n":"29","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"أ. لوكيل الإعسار أو للمدين بإشراف وكيل الإعسار أن يطلب فسخ عقد البيع الذي أبرمه قبل إشهار الإعسار شريطة أن لا يكون قد تم تسليم المبيع أو تسديد الثمن.\nب. للبائع الذي لم يقبض الثمن المتفق عليه أن يمتنع عن تسليم المبيع الى حين قيام المدين بسداد الثمن أو الالتزام بأحكام العقد المبرم معه .\nج. إذا قبض البائع جزءا من ثمن المبيع فلا يحق له الاحتفاظ بالبضائع التي لم يستوف ثمنها أو استرداد تلك البضائع دون غيرها .","title":"فسخ عقد البيع وحقوق البائع","memo":"⭐ لوكيل الإعسار أو المدين بإشرافه طلب فسخ عقد البيع المبرم قبل الإشهار بشرط عدم تسليم المبيع أو تسديد الثمن\n⭐ للبائع الذي لم يقبض الثمن الامتناع عن التسليم حتى السداد\n⭐ إذا قبض البائع جزءاً من الثمن فلا يحق له الاحتفاظ بالبضائع غير المستوفى ثمنها أو استردادها دون غيرها","qs":[{"q":"يشترط لطلب وكيل الإعسار فسخ عقد البيع الذي أبرمه المدين قبل الإشهار:","o":["ألا يكون قد تم تسليم المبيع أو تسديد الثمن","أن يكون قد تم تسليم المبيع كاملاً","موافقة الهيئة العامة للدائنين","أن تقل قيمة البيع عن (20%) من ذمة الإعسار"],"a":0},{"q":"بائع لم يقبض الثمن المتفق عليه من المدين المعسر، يحق له:","o":["الامتناع عن تسليم المبيع إلى حين سداد الثمن أو الالتزام بأحكام العقد","التنفيذ على أموال المدين الأخرى","اعتبار دينه ديناً ممتازاً","فسخ العقد تلقائياً بسبب الإشهار"],"a":0},{"q":"إذا قبض البائع جزءاً من ثمن المبيع، فإنه:","o":["لا يحق له الاحتفاظ بالبضائع التي لم يستوف ثمنها أو استردادها دون غيرها","يحق له استرداد البضائع التي لم يستوف ثمنها","يحق له الاحتفاظ بجميع البضائع","يعتبر دينه ديناً مضموناً"],"a":0}]},{"n":"30","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"أ. على الرغم مما ورد في أي تشريع آخر ومع مراعاة أحكام الفقرة (د) من هذه المادة لا يحق لأي مؤجر إنهاء عقد إيجار الموقع الذي يشغله المدين نتيجة لإشهار الإعسار ولوكيل الإعسار أو للمدين بإشراف وكيل الإعسار إنهاء أي عقد ايجار قبل انتهاء مدته إذا كان ذلك يحقق مصلحة لإجراءات الإعسار وفي هذه الحالة يترتب على المدين آداء الأجور المستحقة حتى تاريخ إخلاء المأجور.\nب. على وكيل الإعسار أو المدين بإشراف وكيل الإعسار مقتضى الحال أن يبلغ المؤجر برغبته إما في إنهاء عقد الإيجار أو الاستمرار في تنفيذه لمدة محددة وإذا استمر تنفيذ عقد الإيجار فتعتبر بدلات الإجارة المستحقة بعد الاستمرار ديونا في مواجهة إجراءات الإعسار وتسدد عند استحقاقها بموجب أحكام هذا القانون أما المبالغ المستحقة قبل إشهار الإعسار فتعتبر ديونا في مواجهة ذمة الإعسار.\nج. تسري أحكام المادة (22) من هذا القانون على أي إجراءات قام بها المؤجر للتنفيذ على أموال المدين لتحصيل بدلات الإجارة التي استحقت قبل إشهار الإعسار بما في ذلك الإجراءات التي تمت على عين المأجور.\nد. تطبق احكام هذه المادة على الحالات التي تكون فيها الأموال المنقولة وغير المنقولة المستأجرة لازمة لاستمرار العمل أو للسير بإجراءات الإعسار وبخلاف ذلك فللمؤجر إنهاء العقد ما لم يحصل على ضمانات كافية لاستيفاء بدلات الإيجار.","title":"عقود الإيجار بعد الإشهار","memo":"⭐ لا يحق للمؤجر إنهاء إيجار الموقع الذي يشغله المدين نتيجة الإشهار (إذا كان المأجور لازماً لاستمرار العمل أو للإجراءات)\n⭐ لوكيل الإعسار إنهاء الإيجار قبل انتهاء مدته إذا حقق مصلحة الإجراءات، مع أداء الأجور حتى تاريخ الإخلاء\n⭐ الأجور بعد الاستمرار ديون في مواجهة إجراءات الإعسار، والمستحقة قبل الإشهار ديون في مواجهة ذمة الإعسار\n⭐ إذا لم يكن المأجور لازماً فللمؤجر إنهاء العقد ما لم يحصل على ضمانات كافية","qs":[{"q":"إذا استمر تنفيذ عقد الإيجار بعد الإشهار، فإن بدلات الإجارة المستحقة بعد الاستمرار تعتبر:","o":["ديوناً في مواجهة إجراءات الإعسار","ديوناً في مواجهة ذمة الإعسار","ديوناً أدنى في مرتبة الأولوية","ديوناً ممتازة"],"a":0},{"q":"بدلات الإجارة المستحقة على المدين قبل إشهار الإعسار تعتبر:","o":["ديوناً في مواجهة ذمة الإعسار","ديوناً في مواجهة إجراءات الإعسار","ديوناً ذات أولوية مطلقة","ديوناً مضمونة على عين المأجور"],"a":0},{"q":"إذا أنهى وكيل الإعسار عقد إيجار قبل انتهاء مدته لمصلحة الإجراءات، فإن المدين يلتزم بأداء الأجور المستحقة:","o":["حتى تاريخ إخلاء المأجور","حتى نهاية مدة العقد","عن ثلاثة أشهر إضافية","حتى تاريخ إشهار الإعسار فقط"],"a":0},{"q":"يحق للمؤجر إنهاء عقد إيجار المدين المعسر إذا:","o":["لم يكن المأجور لازماً لاستمرار العمل أو للسير بإجراءات الإعسار ولم يحصل على ضمانات كافية","صدر قرار بإشهار إعسار المدين فقط","تأخر وكيل الإعسار في الرد خلال خمسة أيام","طلب ذلك أي من دائني الإعسار"],"a":0}]},{"n":"31","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"أ. لا يؤثر إشهار الإعسار على عقود العمل السارية المفعول.\nب. على الرغم مما ورد في أي تشريع آخر لوكيل الإعسار أو للمدين بإشراف وكيل الإعسار أن يطلب من المحكمة تعديل عقود العمل أو إنهاءها على أن تقرر المحكمة تعديل تلك العقود أو إنهاءها بعد الاستماع لرأي العمال او ممثليهم.","title":"عقود العمل بعد الإشهار","memo":"⭐ لا يؤثر الإشهار على عقود العمل السارية\n⭐ لوكيل الإعسار أو المدين بإشرافه طلب تعديل عقود العمل أو إنهائها من المحكمة، وتقرر المحكمة ذلك بعد الاستماع لرأي العمال أو ممثليهم","qs":[{"q":"الجهة التي تقرر تعديل عقود العمل أو إنهاءها بعد إشهار الإعسار هي:","o":["المحكمة بعد الاستماع لرأي العمال أو ممثليهم","وكيل الإعسار منفرداً","وزارة العمل","لجنة الدائنين"],"a":0},{"q":"ما أثر إشهار الإعسار على عقود العمل السارية المفعول؟","o":["لا يؤثر عليها","تنتهي حكماً","توقف إلى حين انتهاء المرحلة التمهيدية","تتحول إلى عقود مؤقتة"],"a":0}]},{"n":"32","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"أ. مع مراعاة أحكام التشريعات النافذة لا يرتب إشهار الإعسار انتهاء العقود الإدارية أو الرخص أو حقوق الامتياز بشكل تلقائي إلا أنه يحق للإدارة المتعاقدة مع المدين إنهاء العقد أو حق الامتياز أو إلغاء الرخصة بناء على أسباب موضوعية تدعو للاعتقاد بأن هناك مخاطر تتعلق بعدم تنفيذ العقد ولا يعتبر مجرد إشهار الإعسار سببا كافيا لإنهاء العقد طالما استمر النشاط الاقتصادي للمدين.\nب. إذا تعلق العقد بإدارة مرفق عام أو تقديم خدمة عامة أساسية فللادارة اتخاذ أي إجراءات ضرورية لضمان استمرار أداء الخدمة.","title":"العقود الإدارية والرخص وحقوق الامتياز","memo":"⭐ لا يرتب الإشهار انتهاء العقود الإدارية أو الرخص أو حقوق الامتياز تلقائياً\n⭐ للإدارة الإنهاء بناء على أسباب موضوعية تتعلق بمخاطر عدم التنفيذ، ولا يعد مجرد الإشهار سبباً كافياً طالما استمر النشاط\n⭐ إذا تعلق العقد بمرفق عام أو خدمة عامة أساسية فللإدارة اتخاذ الإجراءات الضرورية لاستمرار الخدمة","qs":[{"q":"ما أثر إشهار الإعسار على الرخص الممنوحة للمدين؟","o":["لا يرتب انتهاءها تلقائياً","يرتب إلغاءها حكماً","يوقفها لمدة ستة أشهر","يرتب انتهاءها بعد ثلاثين يوماً"],"a":0},{"q":"يحق للإدارة المتعاقدة مع المدين إنهاء العقد الإداري:","o":["بناء على أسباب موضوعية تدعو للاعتقاد بوجود مخاطر تتعلق بعدم تنفيذ العقد","بمجرد إشهار الإعسار","بموافقة وكيل الإعسار فقط","إذا طلب ذلك أي دائن"],"a":0},{"q":"إذا تعلق العقد الإداري بإدارة مرفق عام أو تقديم خدمة عامة أساسية، فإن للإدارة:","o":["اتخاذ أي إجراءات ضرورية لضمان استمرار أداء الخدمة","فسخ العقد تلقائياً دون أسباب","طلب تصفية المدين فوراً","الحلول محل وكيل الإعسار"],"a":0}]},{"n":"33","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"أ. تكون التصرفات التي يبرمها المدين خلال السنة السابقة لتاريخ إشهار الإعسار غير نافذة إذا ألحقت ضررا بذمة الاعسار أو منحت معاملة تفضيلية غير مبررة لأي من دائني المدين ولوكيل الإعسار المطالبة بعدم نفاذها.\nب.1. يعتبر الضرر بذمة الإعسار متحققا إذا أبرم المدين تصرفا يحقق له عائدا أقل بكثير من البدل الذي تحقق للطرف الآخر.\n2. يعتبر تصرف المدين تفضيليا غير مبرر إذا قام المدين بعمل من شأنه أن يجعل احد الدائنين في وضع أفضل من غيره من الدائنين في إجراءات الإعسار.\nج. على وكيل الإعسار أن يثبت وقوع الضرر بذمة الإعسار من المدين وتعتبر الحالات التاليه ضررا واقعا على ذمة الاعسار:\n1. الهبة أو أي تصرف بدون عوض.\n2. سداد التزام غير مضمون وغير مستحق الأداء قبل تاريخ إشهار الإعسار.\n3. إبرام تصرفات لصالح أحد الأشخاص ذوي الصلة به.\n4. منح ضمانات لدين سابق أو دين جديد حل محل دين سابق إذا كان الدين السابق غير مضمون أو مضمون بضمانة أقل قيمة من الضمانات الممنوحة.\n5. سداد دين مضمون غير مستحق الأداء قبل إشهار الإعسار.\nد. تعتبر الحالات الواردة في البندين (1) و(2) من الفقرة (ج) من هذه المادة غير قابله لإثبات العكس، على أن للمدين إثبات أن التصرفات المنصوص عليها في البنود (3) و(4) و(5) من الفقرة (ج) من هذه المادة لم تلحق ضررا بذمة الاعسار.\nهـ. على الرغم مما ورد في أحكام الفقرة (أ) من هذه المادة لا يجوز الحكم بعدم نفاذ التصرفات التالية :\n1. التصرفات التي يبرمها المدين بحسن نية، بعد إجراء تسوية للديون مع دائنيه جميعهم لغايات تسيير أعماله مع وجود ما يدفع للاعتقاد بأن التصرف سيعود بالنفع على أعمال المدين.\n2. التصرفات التي يبرمها المدين في سياق أعماله المعتادة.\n3. الكفالات وحقوق الضمان الخاضعة للحماية بموجب القواعد الخاصة التي تسري على العقود المالية.","title":"التصرفات الضارة بذمة الإعسار (فترة الريبة)","memo":"⭐ تكون غير نافذة تصرفات المدين خلال السنة السابقة للإشهار إذا أضرت بذمة الإعسار أو منحت معاملة تفضيلية غير مبررة\n⭐ حالات الضرر: الهبة والتصرف بدون عوض، سداد التزام غير مضمون وغير مستحق، تصرفات لذوي الصلة، منح ضمانات لدين سابق، سداد دين مضمون غير مستحق\n⭐ الحالتان (1) و(2) لا تقبلان إثبات العكس، وللمدين إثبات عدم الضرر في الحالات (3) و(4) و(5)\n⭐ لا يحكم بعدم نفاذ: التصرف بحسن نية بعد تسوية مع جميع الدائنين، التصرفات المعتادة، الكفالات وحقوق الضمان المحمية بقواعد العقود المالية","qs":[{"q":"تكون تصرفات المدين الضارة بذمة الإعسار غير نافذة إذا أبرمت خلال:","o":["السنة السابقة لتاريخ إشهار الإعسار","الستة أشهر السابقة لتاريخ إشهار الإعسار","السنتين السابقتين لتاريخ إشهار الإعسار","الثلاثة أشهر السابقة لتاريخ إشهار الإعسار"],"a":0},{"q":"أي من حالات الضرر بذمة الإعسار التالية لا تقبل إثبات العكس؟","o":["الهبة أو أي تصرف بدون عوض","إبرام تصرفات لصالح أحد الأشخاص ذوي الصلة","منح ضمانات لدين سابق غير مضمون","سداد دين مضمون غير مستحق الأداء قبل الإشهار"],"a":0},{"q":"أي من التصرفات التالية لا يجوز الحكم بعدم نفاذها رغم إبرامها خلال المدة المحددة؟","o":["التصرفات التي يبرمها المدين في سياق أعماله المعتادة","سداد التزام غير مضمون وغير مستحق الأداء","الهبة","إبرام تصرف لصالح أحد ذوي الصلة"],"a":0},{"q":"قبل إشهار إعساره بثمانية أشهر سدد المدين ديناً غير مضمون لأحد الدائنين قبل موعد استحقاقه، فإن هذا التصرف:","o":["يعتبر ضرراً واقعاً على ذمة الإعسار ولا يقبل إثبات العكس","صحيح ونافذ لأنه سداد لدين حقيقي","يعتبر ضرراً يقبل إثبات العكس من المدين","لا يخضع للطعن لمرور أكثر من ستة أشهر عليه"],"a":0}]},{"n":"34","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"أ. يتولى وكيل الإعسار حق إقامة دعوى عدم نفاذ التصرف خلال إجراءات الإعسار.\nب. على الرغم مما ورد في الفقرة (أ) من هذه المادة، للدائنين إشعار وكيل الإعسار بوجود تصرف من التصرفات المنصوص عليها في المادة (33) من هذا القانون فإذا لم يقم دعوى عدم نفاذ التصرف خلال مدة شهرين من تاريخ إشعاره فللدائن إقامة الدعوى على نفقته ومسؤوليته.\nج. تقام دعوى عدم نفاذ التصرف على المدين و أطراف التصرف وإذا انتقل المال للغير أو أصبح تحت حيازته فيتوجب اختصامه.\nد. تختص المحكمة بالنظر في دعاوى عدم نفاذ التصرف وتخضع هذه الدعاوى للإجراءات المستعجلة المنصوص عليها في قانون أصول المحاكمات المدنية وعلى المحكمة البت فيها خلال مدة لا تتجاوز ستة اشهر.","title":"دعوى عدم نفاذ التصرف","memo":"⭐ يتولى وكيل الإعسار إقامة دعوى عدم نفاذ التصرف\n⭐ إذا أشعره الدائن ولم يقمها خلال شهرين من الإشعار فللدائن إقامتها على نفقته ومسؤوليته\n⭐ تقام على المدين وأطراف التصرف ويختصم الغير إذا انتقل إليه المال\n⭐ تخضع للإجراءات المستعجلة وتبت فيها المحكمة خلال مدة لا تتجاوز ستة أشهر","qs":[{"q":"إذا أشعر الدائن وكيل الإعسار بوجود تصرف ضار ولم يقم الوكيل الدعوى، فللدائن إقامتها على نفقته بعد مرور:","o":["شهرين من تاريخ إشعاره","شهر من تاريخ إشعاره","ستة أشهر من تاريخ إشعاره","ثلاثين يوماً من تاريخ إشهار الإعسار"],"a":0},{"q":"على المحكمة البت في دعاوى عدم نفاذ التصرف خلال مدة لا تتجاوز:","o":["ستة أشهر","ثلاثة أشهر","سنة","شهرين"],"a":0},{"q":"إذا انتقل المال محل التصرف إلى الغير، فإن دعوى عدم نفاذ التصرف:","o":["يتوجب فيها اختصام الغير","تسقط حكماً","تقام على المدين وحده","تقام على وكيل الإعسار"],"a":0}]},{"n":"35","chapter":"الفصل الثالث - آثار إشهار الإعسار","notes":[],"source":"أ. يتضمن القرار الصادر عن المحكمة بعدم نفاذ التصرف اتخاذ الإجراءات اللازمة لاعادة ذمة الإعسار وإعادة الحال إلى ما كانت عليه قبل التصرف.\nب. إذا نتج عن التصرف الذي صدر القرار بعدم نفاذه انتقال حق أو مال لطرف آخر حسن النية فتحكم المحكمة على ذلك الطرف بدفع قيمة الحق أو المال مقدرا بتاريخ إجراء التصرف إضافة الى الفائدة التي تحددها المحكمة.\nج. يعتبر حق الطرف الآخر في استرداد ما دفعه للمدين دينا في مواجهة إجراءات الإعسار ما لم يكن ذلك الطرف قد تصرف بسوء نيه وفي هذه الحالة يعتبر دينه من الديون الأدنى في مرتبة الأولويه.\nد. يكون القرار الصادر بعدم نفاذ أي تصرف قابلا للاستئناف لدى محكمة الاستئناف المختصة خلال مدة خمسة عشر يوما من تاريخ صدوره أو من تاريخ تبلغه حسب مقتضى الحال ويكون قرار محكمة الاستئناف قطعيا على أن لا يترتب على ذلك تعليق إجراءات الإعسار.","title":"آثار قرار عدم نفاذ التصرف واستئنافه","memo":"⭐ يتضمن القرار إعادة ذمة الإعسار وإعادة الحال إلى ما كانت عليه قبل التصرف\n⭐ الطرف حسن النية الذي انتقل إليه المال يحكم عليه بدفع قيمته بتاريخ التصرف مضافاً إليها فائدة تحددها المحكمة\n⭐ حق الطرف الآخر في استرداد ما دفعه دين في مواجهة إجراءات الإعسار، أما سيء النية فدينه من الديون الأدنى في مرتبة الأولوية\n⭐ يستأنف القرار خلال خمسة عشر يوماً، وقرار الاستئناف قطعي ولا يعلق الإجراءات","qs":[{"q":"يستأنف القرار الصادر بعدم نفاذ التصرف لدى محكمة الاستئناف المختصة خلال مدة:","o":["خمسة عشر يوماً من تاريخ صدوره أو تبلغه","عشرة أيام من تاريخ صدوره أو تبلغه","ثلاثين يوماً من تاريخ صدوره أو تبلغه","خمسة أيام من تاريخ صدوره أو تبلغه"],"a":0},{"q":"إذا كان الطرف الآخر في التصرف غير النافذ سيء النية، فإن حقه في استرداد ما دفعه للمدين يعتبر:","o":["من الديون الأدنى في مرتبة الأولوية","ديناً في مواجهة إجراءات الإعسار","ديناً ممتازاً","دين إعسار غير مضمون"],"a":0},{"q":"الطرف حسن النية الذي انتقل إليه مال بموجب تصرف قضي بعدم نفاذه، تحكم عليه المحكمة بدفع قيمة المال مقدراً بتاريخ:","o":["إجراء التصرف إضافة إلى الفائدة التي تحددها المحكمة","صدور قرار عدم النفاذ","إشهار الإعسار","تقديم دعوى عدم النفاذ"],"a":0}]},{"n":"36","chapter":"الفصل الرابع - الدائنون في إجراءات الإعسار","notes":[],"source":"يقسم الدائنون لغايات هذا القانون إلى:\nأ. دائني الإعسار وهم الدائنون الذين نشأت ديونهم في ذمة المدين قبل تاريخ إشهار الإعسار وتم تضمينها في قائمة الدائنين .\nب. دائنين في مواجهة إجراءات الاعسار وهم الدائنون الذين نشأت ديونهم بعد تاريخ إشهار الإعسار.","title":"تقسيم الدائنين","memo":"⭐ دائنو الإعسار: نشأت ديونهم قبل تاريخ الإشهار وتم تضمينها في قائمة الدائنين\n⭐ الدائنون في مواجهة إجراءات الإعسار: نشأت ديونهم بعد تاريخ الإشهار","qs":[{"q":"الدائنون الذين نشأت ديونهم بعد تاريخ إشهار الإعسار يسمون:","o":["دائنين في مواجهة إجراءات الإعسار","دائني الإعسار","الدائنين الأدنى في مرتبة الأولوية","الدائنين أصحاب الديون الممتازة"],"a":0},{"q":"يشترط لاعتبار الدائن من دائني الإعسار أن يكون دينه قد نشأ قبل تاريخ الإشهار وأن:","o":["يتم تضمينه في قائمة الدائنين","يكون مضموناً بحق عيني","يكون ثابتاً بحكم قضائي","توافق عليه لجنة الدائنين"],"a":0}]},{"n":"37","chapter":"الفصل الرابع - الدائنون في إجراءات الإعسار","notes":[],"source":"يقسم دائنو الإعسار إلى الفئات التالية:\nأ. الدائنون أصحاب الحقوق المضمونة .\nب. الدائنون أصحاب الديون الممتازة .\nج. الدائنون بديون غير مضمونة .\nد. الدائنون الأدنى في مرتبة الأولوية.","title":"فئات دائني الإعسار","memo":"⭐ فئات دائني الإعسار أربع: أصحاب الحقوق المضمونة، أصحاب الديون الممتازة، الدائنون بديون غير مضمونة، الدائنون الأدنى في مرتبة الأولوية","qs":[{"q":"أي مما يلي ليس من فئات دائني الإعسار؟","o":["الدائنون في مواجهة إجراءات الإعسار","الدائنون أصحاب الحقوق المضمونة","الدائنون أصحاب الديون الممتازة","الدائنون الأدنى في مرتبة الأولوية"],"a":0},{"q":"الدائن الذي يتمتع برهن على عقار للمدين يصنف ضمن فئة:","o":["الدائنين أصحاب الحقوق المضمونة","الدائنين أصحاب الديون الممتازة","الدائنين بديون غير مضمونة","الدائنين الأدنى في مرتبة الأولوية"],"a":0}]},{"n":"38","chapter":"الفصل الرابع - الدائنون في إجراءات الإعسار","notes":[],"source":"أ. لا تخضع ديون الدائنين في مواجهة إجراءات الاعسار للاجراءات المنصوص عليها في هذا القانون وتعطى الأولوية المطلقة لسداد ديونهم من ذمه الإعسار عند استحقاقها ولا يقدم عليها إلا الديون المضمونة في حدود حصيلة بيع الضمانة.\nب. تعتبر المطالبات التالية ديونا في مواجهة إجراءات الإعسار:\n1. نفقات إجراءات الإعسار، بما في ذلك الرسوم والمصاريف القضائية وأتعاب وكيل الإعسار والنفقات التي وافقت عليها لجنة الدائنين وأتعاب محامي ذمة الاعسار.\n2. النفقات الناجمة عن تنفيذ واجبات وكيل الإعسار وفقا لأحكام هذا القانون.\n3. نفقة الزوجه والأولاد والوالدين والأقارب المستحقة على المدين من الأشخاص الطبيعيين بعد إشهار الاعسار.\n4. التسهيلات المالية والتجاريه الممنوحة للمدين بعد إشهار الإعسار بموافقة وكيل الإعسار بموجب أحكام هذا القانون.\n5. المبالغ المستحقة على المدين بموجب العقود الجاري تنفيذها والتي أبرمها أو وافق عليها وكيل الإعسار بعد تاريخ إشهار الإعسار.\n6. الالتزامات الأخرى التي تنشأ بعد إشهار الإعسار في سياق استمرار النشاط الاقتصادي والمنصوص عليها في الفقرتين (و) و(ز) من المادة (17) والمادة (19) من هذا القانون .","title":"الديون في مواجهة إجراءات الإعسار","memo":"⭐ لا تخضع لإجراءات القانون ولها الأولوية المطلقة في السداد عند استحقاقها، ولا يتقدم عليها إلا الديون المضمونة في حدود حصيلة بيع الضمانة\n⭐ منها: نفقات الإجراءات وأتعاب وكيل الإعسار ومحامي ذمة الإعسار، نفقة الأسرة المستحقة بعد الإشهار، التسهيلات الممنوحة بعد الإشهار بموافقة وكيل الإعسار، مبالغ العقود التي أبرمها أو وافق عليها الوكيل بعد الإشهار","qs":[{"q":"لا يتقدم على الديون في مواجهة إجراءات الإعسار إلا:","o":["الديون المضمونة في حدود حصيلة بيع الضمانة","أجور العاملين لثلاثة أشهر","ديون الخزينة","نفقة الزوجة والأولاد المستحقة قبل الإشهار"],"a":0},{"q":"أي مما يلي يعتبر ديناً في مواجهة إجراءات الإعسار؟","o":["أتعاب وكيل الإعسار","المطالبات بالتعويض عن فعل ضار سببه المدين قبل الإشهار","فوائد الديون المستحقة قبل الإشهار","قرض منحه أحد ذوي الصلة للمدين قبل الإشهار"],"a":0},{"q":"نفقة الزوجة والأولاد المستحقة على المدين الشخص الطبيعي بعد إشهار الإعسار تعتبر:","o":["ديناً في مواجهة إجراءات الإعسار","ديناً ممتازاً","ديناً غير مضمون","ديناً أدنى في مرتبة الأولوية"],"a":0},{"q":"التسهيلات المالية الممنوحة للمدين بعد إشهار الإعسار تعتبر ديناً في مواجهة إجراءات الإعسار إذا منحت بموافقة:","o":["وكيل الإعسار","المراقب","الهيئة العامة للدائنين","البنك المركزي"],"a":0}]},{"n":"39","chapter":"الفصل الرابع - الدائنون في إجراءات الإعسار","notes":[],"source":"يعتبر صاحب الحق المضمون كل دائن له حق عيني تبعي نافذ في مواجهة الغير على أموال المدين التي تدخل ضمن ذمة الإعسار ويشمل ذلك رهن الأموال المنقولة وغير المنقولة وأي نوع آخر من الضمانات العينية بموجب التشريعات النافذة .","title":"تعريف صاحب الحق المضمون","memo":"⭐ صاحب الحق المضمون: كل دائن له حق عيني تبعي نافذ في مواجهة الغير على أموال المدين الداخلة في ذمة الإعسار، ويشمل رهن المنقول وغير المنقول وأي ضمان عيني آخر","qs":[{"q":"يعتبر صاحب حق مضمون الدائن الذي له على أموال المدين الداخلة في ذمة الإعسار:","o":["حق عيني تبعي نافذ في مواجهة الغير","حق شخصي ثابت بسند تنفيذي","كفالة شخصية من الغير","دين ممتاز بموجب القانون"],"a":0},{"q":"أي مما يلي يجعل الدائن صاحب حق مضمون وفقاً لقانون الإعسار؟","o":["رهن على مال منقول للمدين نافذ في مواجهة الغير","كفالة شخصية من أحد الشركاء","حكم قضائي قطعي بالدين","اتفاق على اعتبار الدين ديناً أدنى في الأولوية"],"a":0}]},{"n":"40","chapter":"الفصل الرابع - الدائنون في إجراءات الإعسار","notes":[],"source":"أ. مع مراعاة أحكام الفقرة (أ) من المادة (38) من هذا القانون تعتبر الديون التالية ديونا ممتازة لغايات احكام هذا القانون حسب الترتيب التالي :\n1. أجور العاملين لدى المدين ومستحقاتهم الناشئة عن إنهاء عقود العمل وبحد أعلى أجور ثلاثه أشهر.\n2. نفقة الزوجة والأولاد والوالدين والأقارب المستحقة على المدين من الأشخاص الطبيعيين قبل إشهار الإعسار.\n3. المطالبات بالتعويض الناشئ عن الفعل الضار الذي تسبب به المدين قبل إشهار الإعسار.\nب. على الرغم مما ورد في أي تشريع آخر لا تعتبر أي ديون خلاف الديون المبينه في هذه المادة ديونا ممتازة.","title":"الديون الممتازة وترتيبها","memo":"⭐ مع مراعاة المادة (38/أ) الديون الممتازة بالترتيب: (1) أجور العاملين ومستحقات إنهاء عقودهم بحد أعلى أجور ثلاثة أشهر، (2) نفقة الأسرة المستحقة قبل الإشهار، (3) التعويض عن الفعل الضار قبل الإشهار\n⭐ على الرغم من أي تشريع آخر لا تعتبر أي ديون أخرى ديوناً ممتازة","qs":[{"q":"تعتبر أجور العاملين لدى المدين ومستحقاتهم ديوناً ممتازة بحد أعلى:","o":["أجور ثلاثة أشهر","أجور ستة أشهر","أجور شهرين","أجور سنة"],"a":0},{"q":"أي من الديون التالية يأتي في المرتبة الأولى بين الديون الممتازة؟","o":["أجور العاملين لدى المدين ومستحقاتهم الناشئة عن إنهاء عقود العمل","نفقة الزوجة والأولاد المستحقة قبل الإشهار","المطالبات بالتعويض عن الفعل الضار","ديون الخزينة العامة"],"a":0},{"q":"أي من الديون التالية لا يعتبر ديناً ممتازاً وفقاً لقانون الإعسار؟","o":["ضريبة الدخل المستحقة على المدين","نفقة الوالدين المستحقة على المدين قبل الإشهار","التعويض عن فعل ضار تسبب به المدين قبل الإشهار","أجور العاملين لدى المدين عن شهرين"],"a":0}]},{"n":"41","chapter":"الفصل الرابع - الدائنون في إجراءات الإعسار","notes":[],"source":"تعتبر الديون التالية الأدنى في مرتبة الأولوية من أي ديون أخرى:\nأ. دفعات القروض أو التسهيلات الممنوحة للمدين من أحد الأشخاص ذوي الصلة .\nب. فوائد وغرامات التأخير المستحقة على الديون قبل تاريخ اشهار الاعسار .\nج. الغرامات المتحققة على المدين بموجب التشريعات النافذة.\nد. الديون التي اتفق المدين مع الدائن على اعتبارها ديونا أدنى في مرتبة الأولويه.","title":"الديون الأدنى في مرتبة الأولوية","memo":"⭐ الديون الأدنى في الأولوية: قروض أو تسهيلات من ذوي الصلة، فوائد وغرامات التأخير المستحقة قبل الإشهار، الغرامات المتحققة بموجب التشريعات، الديون المتفق على اعتبارها أدنى","qs":[{"q":"قرض منحه شقيق المدين له قبل الإشهار يعتبر في إجراءات الإعسار:","o":["ديناً أدنى في مرتبة الأولوية","ديناً ممتازاً","ديناً في مواجهة إجراءات الإعسار","ديناً غير مضمون عادياً"],"a":0},{"q":"فوائد وغرامات التأخير المستحقة على الديون قبل تاريخ إشهار الإعسار تعتبر:","o":["من الديون الأدنى في مرتبة الأولوية","من الديون الممتازة","ديوناً في مواجهة إجراءات الإعسار","ديوناً مضمونة"],"a":0},{"q":"أي مما يلي لا يعتبر من الديون الأدنى في مرتبة الأولوية؟","o":["المطالبات بالتعويض الناشئ عن الفعل الضار قبل الإشهار","الغرامات المتحققة على المدين بموجب التشريعات النافذة","الديون التي اتفق المدين مع الدائن على اعتبارها أدنى في الأولوية","دفعات التسهيلات الممنوحة من أحد ذوي الصلة"],"a":0}]},{"n":"42","chapter":"الفصل الرابع - الدائنون في إجراءات الإعسار","notes":[],"source":"أ. لمالك أي مال منقول في حيازة المدين بشكل قانوني أن يطلب فصل ذلك المال عن ذمة الإعسار ويسري هذا الحكم على الأوراق التجارية والأوراق المالية وسندات الدين المظهرة للمدين بصفته وكيل تحصيل لتلك الأوراق أو عوائدها أو استخدام تلك الأوراق التجارية أو الأوراق المالية أو سندات الدين للوفاء بأي التزام قائم بتاريخ اشهار الاعسار.\nب. تسري أحكام الفقرة (أ) من هذه المادة على المبالغ النقدية التي تكون في حوزة المدين بصفته حافظا أمينا أو التي قبضها المدين أو اقتطعها نيابة عن الخزينة أو أي مؤسسة عامة وإذا اختلطت هذه المبالغ بمبالغ أخرى فتعتبر ديونا في مواجهة إجراءات الاعسار.\nج. يقدم مالك المال المطلوب فصله الطلب المنصوص عليه في الفقرة (أ) من هذه المادة خطيا الى وكيل الإعسار مباشرة مقابل إشعار بالتسلم كما يجوز له تقديمه للمحكمة وعلى كل منهما الفصل في الطلب خلال مدة خمسة ايام من تاريخ تقديمه.\nد. إذا قرر وكيل الإعسار أو المحكمة حسب مقتضى الحال، قبول الطلب فيتولى وكيل الإعسار إعادة المال أو الحق موضوع الطلب الى مالكه خلال مدة خمسة عشر يوما من تاريخ تسلم الطلب أو من تاريخ صدور قرار المحكمة.\nهـ. اذا تم رفض الطلب يبلغ المستدعي خلال مدة خمسة ايام من تاريخ صدور القرار وله حق الاعتراض عليه أمام المحكمة اذا صدر القرار عن وكيل الاعسار أو استئنافه لدى محكمة الاستئناف المختصة خلال مدة خمسة ايام من تاريخ تبلغه القرار ويجب البت فيه خلال مدة خمسة عشر يوما من تاريخ وروده لأي منهما ويكون قرار محكمة الاستئناف في هذا الشأن قطعيا.","title":"فصل أموال الغير عن ذمة الإعسار","memo":"⭐ لمالك المال المنقول في حيازة المدين قانوناً طلب فصله عن ذمة الإعسار، ويشمل الأوراق المظهرة للمدين كوكيل تحصيل والمبالغ التي بحوزته كحافظ أمين أو المقتطعة لصالح الخزينة (وإذا اختلطت تعتبر ديوناً في مواجهة الإجراءات)\n⭐ يقدم الطلب خطياً لوكيل الإعسار أو للمحكمة، ويفصل فيه خلال خمسة أيام\n⭐ عند القبول يعاد المال خلال خمسة عشر يوماً، وعند الرفض يبلغ المستدعي خلال خمسة أيام وله الاعتراض أو الاستئناف خلال خمسة أيام، ويبت خلال خمسة عشر يوماً، وقرار الاستئناف قطعي","qs":[{"q":"على وكيل الإعسار أو المحكمة الفصل في طلب فصل المال عن ذمة الإعسار خلال مدة:","o":["خمسة أيام من تاريخ تقديمه","عشرة أيام من تاريخ تقديمه","خمسة عشر يوماً من تاريخ تقديمه","ثلاثين يوماً من تاريخ تقديمه"],"a":0},{"q":"إذا قبل طلب فصل المال، يتولى وكيل الإعسار إعادته إلى مالكه خلال مدة:","o":["خمسة عشر يوماً من تاريخ تسلم الطلب أو صدور قرار المحكمة","خمسة أيام من تاريخ تسلم الطلب","ثلاثين يوماً من تاريخ تسلم الطلب","عشرة أيام من تاريخ صدور قرار المحكمة"],"a":0},{"q":"مبالغ اقتطعها المدين نيابة عن الخزينة واختلطت بأمواله الأخرى، فإنها تعتبر:","o":["ديوناً في مواجهة إجراءات الإعسار","أموالاً تفصل عن ذمة الإعسار عيناً","ديوناً ممتازة","ديوناً أدنى في مرتبة الأولوية"],"a":0},{"q":"قرار محكمة الاستئناف في الطعن برفض طلب فصل المال عن ذمة الإعسار يكون:","o":["قطعياً","قابلاً للتمييز خلال ثلاثين يوماً","قابلاً للاعتراض أمام المحكمة","قابلاً للطعن أمام الهيئة العامة للدائنين"],"a":0}]},{"n":"43","chapter":"الفصل الرابع - الدائنون في إجراءات الإعسار","notes":[],"source":"تشكل هيئتان لتمثيل الدائنين أثناء إجراءات الإعسار وهما:\nأ. الهيئة العامة للدائنين وتتكون من دائني الإعسار الذين تضمنتهم قائمة الدائنين المعدة من وكيل الإعسار بموجب أحكام هذا القانون.\nب. لجنه الدائنين و تتكون من عدد من الدائنين لا يقل عن ثلاثة ولا يزيد على خمسة ممن لهم حق التصويت ويكون لكل عضو في اللجنة صوت واحد بغض النظر عن مبلغ مديونيته وتشكل في حالات محددة ما لم تقرر المحكمة خلاف ذلك .","title":"هيئات تمثيل الدائنين","memo":"⭐ تشكل هيئتان: الهيئة العامة للدائنين (من دائني الإعسار في قائمة الدائنين المعدة من وكيل الإعسار) ولجنة الدائنين\n⭐ لجنة الدائنين: لا يقل عددها عن ثلاثة ولا يزيد على خمسة ممن لهم حق التصويت، ولكل عضو صوت واحد بغض النظر عن مبلغ مديونيته","qs":[{"q":"يتراوح عدد أعضاء لجنة الدائنين بين:","o":["ثلاثة وخمسة دائنين","خمسة وسبعة دائنين","ثلاثة وسبعة دائنين","اثنين وخمسة دائنين"],"a":0},{"q":"يكون التصويت في لجنة الدائنين على أساس:","o":["صوت واحد لكل عضو بغض النظر عن مبلغ مديونيته","نسبة دين كل عضو إلى إجمالي الديون","صوتين للدائن المضمون وصوت لغيره","الأغلبية المطلقة للديون"],"a":0},{"q":"تتكون الهيئة العامة للدائنين من:","o":["دائني الإعسار الذين تضمنتهم قائمة الدائنين المعدة من وكيل الإعسار","جميع الدائنين بمن فيهم الدائنون في مواجهة إجراءات الإعسار","الدائنين أصحاب الحقوق المضمونة فقط","الدائنين الذين تتجاوز ديونهم (20%) من إجمالي الديون"],"a":0}]},{"n":"44","chapter":"الفصل الرابع - الدائنون في إجراءات الإعسار","notes":[],"source":"أ. تجتمع الهيئة العامة للدائنين بناء على دعوة وكيل الإعسار إما من تلقاء نفسه أو بناء على طلب لجنة الدائنين أو دائنين يمثلون (%20) على الاقل من إجمالي الديون.\nب. لوكيل الإعسار أن يدعو لاجتماع الهيئة العامة للدائنين إذا استدعت ضرورة السير في إجراءات الإعسار ذلك وفي الأحوال جميعها يجب دعوتها لغايات مناقشة خطة اعادة التنظيم والتصويت عليها.","title":"دعوة الهيئة العامة للدائنين","memo":"⭐ تجتمع الهيئة العامة بدعوة من وكيل الإعسار من تلقاء نفسه أو بطلب لجنة الدائنين أو دائنين يمثلون (20%) على الأقل من إجمالي الديون\n⭐ يجب دعوتها في جميع الأحوال لمناقشة خطة إعادة التنظيم والتصويت عليها","qs":[{"q":"تجتمع الهيئة العامة للدائنين بناء على دعوة وكيل الإعسار بطلب من دائنين يمثلون على الأقل:","o":["(20%) من إجمالي الديون","(10%) من إجمالي الديون","(25%) من إجمالي الديون","(50%) من إجمالي الديون"],"a":0},{"q":"يجب في جميع الأحوال دعوة الهيئة العامة للدائنين لغايات:","o":["مناقشة خطة إعادة التنظيم والتصويت عليها","تعيين وكيل الإعسار","إشهار الإعسار","تحديد أتعاب أعضاء لجنة الدائنين"],"a":0},{"q":"الجهة التي توجه الدعوة لاجتماع الهيئة العامة للدائنين هي:","o":["وكيل الإعسار","المراقب","المدين","رئيس لجنة الدائنين"],"a":0}]},{"n":"45","chapter":"الفصل الرابع - الدائنون في إجراءات الإعسار","notes":[],"source":"أ. تتولى المحكمة من تلقاء ذاتها أو بناء على طلب وكيل الإعسار الإعلان عن تاريخ اجتماع الهيئة العامة للدائنين ووقته ومكانه وجدول أعماله قبل أسبوع على الأقل من موعد انعقاده وفقا لأحكام المادة (139) من هذا القانون .\nب. يترأس اجتماع الهيئة العامة للدائنين وكيل الإعسار ما لم يقرر قاضي المحكمة ترؤس الاجتماع بنفسه.\nج. يكون نصاب اجتماع الهيئة العامة للدائنين قانونيا بحضور دائنين يمثلون أصالة أو وكالة (%50) على الأقل من إجمالي الديون واذا لم يكتمل هذا النصاب خلال ساعة من الوقت المحدد لبدء الاجتماع فيؤجل الاجتماع الى موعد آخر يعقد خلال مدة خمسة ايام من التاريخ المحدد للاجتماع الاول ويعاد تبليغ الدائنين الذين لم يحضروا.\nد. يكون النصاب في الاجتماع الثاني قانونيا بحضور دائنين يمثلون أصالة أو وكالة (%35) على الأقل من إجمالي الديون على ألا يقل عدد الدائنين الحاضرين عن ثلاثه دائنين.","title":"إعلان اجتماع الهيئة العامة ونصابه","memo":"⭐ تعلن المحكمة عن موعد الاجتماع وجدول أعماله قبل أسبوع على الأقل\n⭐ يترأس الاجتماع وكيل الإعسار ما لم يقرر قاضي المحكمة ترؤسه\n⭐ النصاب الأول: (50%) على الأقل من إجمالي الديون أصالة أو وكالة، وإلا يؤجل بعد ساعة إلى موعد خلال خمسة أيام\n⭐ النصاب الثاني: (35%) على الأقل من إجمالي الديون وبما لا يقل عن ثلاثة دائنين","qs":[{"q":"يكون نصاب الاجتماع الأول للهيئة العامة للدائنين قانونياً بحضور دائنين يمثلون على الأقل:","o":["(50%) من إجمالي الديون","(35%) من إجمالي الديون","(20%) من إجمالي الديون","(75%) من إجمالي الديون"],"a":0},{"q":"يكون النصاب في الاجتماع الثاني للهيئة العامة للدائنين قانونياً بحضور دائنين يمثلون:","o":["(35%) على الأقل من إجمالي الديون وبما لا يقل عن ثلاثة دائنين","(25%) على الأقل من إجمالي الديون وبما لا يقل عن خمسة دائنين","(50%) على الأقل من إجمالي الديون","أي عدد من الدائنين الحاضرين"],"a":0},{"q":"يعلن عن تاريخ اجتماع الهيئة العامة للدائنين ومكانه وجدول أعماله قبل موعد انعقاده بمدة:","o":["أسبوع على الأقل","ثلاثة أيام على الأقل","خمسة عشر يوماً على الأقل","شهر على الأقل"],"a":0},{"q":"إذا لم يكتمل نصاب الاجتماع الأول خلال ساعة من الوقت المحدد، يؤجل الاجتماع إلى موعد يعقد خلال:","o":["خمسة أيام من التاريخ المحدد للاجتماع الأول","أسبوع من التاريخ المحدد للاجتماع الأول","عشرة أيام من التاريخ المحدد للاجتماع الأول","خمسة عشر يوماً من التاريخ المحدد للاجتماع الأول"],"a":0}]},{"n":"46","chapter":"الفصل الرابع - الدائنون في إجراءات الإعسار","notes":[],"source":"أ. يتم التصويت في اجتماع الهيئة العامة للدائنين بناء على البيانات الواردة في قائمة الدائنين على أنه إذا انعقد الاجتماع قبل أن تصبح قائمة الدائنين نهائية يتم التصويت فيه بناء على قائمة الديون المقدمة من دائني الإعسار والتي لم ينازع فيها وكيل الاعسار أو أي دائن يتمتع بحق التصويت وفي الأحوال جميعها لا يحق للدائنين الأدنى في مرتبة الأولويه أو الشركاء في المدين إذا كان شخصا اعتباريا التصويت.\nب. لا يحق للدائنين ذوي الديون المتنازع عليها التصويت إلا ضمن الحدود التي تقررها المحكمة بعد الاستماع لوكيل الاعسار.\nج. إذا تجاوز عدد الدائنين المائة فللمحكمة من تلقاء ذاتها أو بناء على طلب من وكيل الإعسار أن تقرر الاستعاضة عن اجتماع الدائنين الفعلي بالتصويت خطيا على القرارات.","title":"التصويت في الهيئة العامة للدائنين","memo":"⭐ يتم التصويت بناء على قائمة الدائنين، أو قبل نهائيتها بناء على الديون غير المنازع فيها\n⭐ لا يحق التصويت للدائنين الأدنى في مرتبة الأولوية ولا للشركاء في المدين الاعتباري\n⭐ أصحاب الديون المتنازع عليها يصوتون ضمن الحدود التي تقررها المحكمة بعد الاستماع لوكيل الإعسار\n⭐ إذا تجاوز عدد الدائنين المائة فللمحكمة الاستعاضة عن الاجتماع بالتصويت الخطي","qs":[{"q":"أي من الفئات التالية لا يحق لها التصويت في اجتماع الهيئة العامة للدائنين؟","o":["الدائنون الأدنى في مرتبة الأولوية","الدائنون أصحاب الديون الممتازة","الدائنون بديون غير مضمونة","الدائنون أصحاب الحقوق المضمونة"],"a":0},{"q":"للمحكمة أن تقرر الاستعاضة عن اجتماع الدائنين الفعلي بالتصويت الخطي إذا تجاوز عدد الدائنين:","o":["المائة","الخمسين","المائتين","الخمسمائة"],"a":0},{"q":"الدائنون ذوو الديون المتنازع عليها يحق لهم التصويت:","o":["ضمن الحدود التي تقررها المحكمة بعد الاستماع لوكيل الإعسار","بكامل قيمة ديونهم المطالب بها","بنصف قيمة ديونهم","بعد موافقة لجنة الدائنين"],"a":0}]},{"n":"47","chapter":"الفصل الرابع - الدائنون في إجراءات الإعسار","notes":[],"source":"تصدر قرارات الهيئة العامة للدائنين بالأغلبية المطلقة لديون دائني الإعسار الذين لهم حق التصويت أصالة أو وكالة.","title":"أغلبية قرارات الهيئة العامة للدائنين","memo":"⭐ تصدر قرارات الهيئة العامة للدائنين بالأغلبية المطلقة لديون دائني الإعسار الذين لهم حق التصويت أصالة أو وكالة","qs":[{"q":"تصدر قرارات الهيئة العامة للدائنين بـ:","o":["الأغلبية المطلقة لديون دائني الإعسار الذين لهم حق التصويت","أغلبية ثلثي الدائنين الحاضرين","الأغلبية النسبية لعدد الدائنين الحاضرين","إجماع أعضاء لجنة الدائنين"],"a":0}]},{"n":"48","chapter":"الفصل الرابع - الدائنون في إجراءات الإعسار","notes":[],"source":"أ. تشكل لجنة الدائنين من فئات دائني الإعسار كافة وعلى النحو التالي:\n1. دائن واحد على الأقل من الدائنين أصحاب الديون الممتازة.\n2. دائن واحد على الأقل من أصحاب الديون غير المضمونة.\n3. يجوز تعيين أصحاب الحقوق المضمونة في لجنة الدائنين شريطة أن لا يشكلوا أغلبية الأصوات فيها.\n4. أحد العاملين لدى المدين اذا تجاوز عددهم العشرين شريطة عدم احقيته في التصويت على المسائل التي تناقشها اللجنة.\nب. تتولى لجنة الدائنين المهام التالية:\n1. الرقابة على عمل وكيل الإعسار ومراقبة سير إجراءات الاعسار.\n2. تقديم المشورة الى وكيل الإعسار بخصوص المسائل المتعلقة بإجراءات الإعسار من تلقاء ذاتها أو بطلب من وكيل الاعسار.\n3. اقامة الدعاوى واتخاذ الاجراءات التحفظية لضمان حسن إدارة أموال الإعسار والتصرف فيها أثناء إجراءات الاعسار.\n4. مراجعة المحكمة بخصوص أي مسألة تتعلق بعمل وكيل الإعسار.\n5. تقديم أي اعتراض او استئناف نيابة عن الدائنين.\nج. على وكيل الإعسار أن يسمح للجنة الدائنين بالاطلاع على الوثائق اللازمة وأن يزودها بالإيضاحات الكافية لتمكينها من أداء مهامها.\nد. للمحكمة بتنسيب من وكيل الاعسار تعويض أعضاء لجنة الدائنين عن النفقات التي تكبدوها .","title":"تشكيل لجنة الدائنين ومهامها","memo":"⭐ تضم اللجنة دائناً واحداً على الأقل من أصحاب الديون الممتازة ودائناً واحداً على الأقل من غير المضمونة\n⭐ يجوز تعيين أصحاب الحقوق المضمونة بشرط ألا يشكلوا أغلبية الأصوات، ويعين أحد العاملين إذا تجاوز عددهم العشرين دون حق التصويت\n⭐ مهامها: الرقابة على وكيل الإعسار، المشورة، إقامة الدعاوى والإجراءات التحفظية، مراجعة المحكمة، الاعتراض والاستئناف نيابة عن الدائنين\n⭐ للمحكمة بتنسيب من وكيل الإعسار تعويض أعضاء اللجنة عن نفقاتهم","qs":[{"q":"يعين أحد العاملين لدى المدين في لجنة الدائنين إذا تجاوز عدد العاملين:","o":["العشرين","العشرة","الخمسين","المائة"],"a":0},{"q":"يجوز تعيين أصحاب الحقوق المضمونة في لجنة الدائنين شريطة:","o":["ألا يشكلوا أغلبية الأصوات فيها","ألا يزيد عددهم على اثنين","موافقة المدين","ألا تتجاوز ديونهم (20%) من إجمالي الديون"],"a":0},{"q":"ممثل العاملين المعين في لجنة الدائنين:","o":["لا يحق له التصويت على المسائل التي تناقشها اللجنة","يكون له صوتان","يترأس اللجنة حكماً","يحق له التصويت على المسائل المتعلقة بالأجور فقط"],"a":0},{"q":"تعويض أعضاء لجنة الدائنين عن النفقات التي تكبدوها يتم من قبل:","o":["المحكمة بتنسيب من وكيل الإعسار","وكيل الإعسار بموافقة المدين","الهيئة العامة للدائنين","المراقب"],"a":0}]},{"n":"49","chapter":"الفصل الخامس - وكلاء الإعسار","notes":[],"source":"أ. يشترط لترخيص وكيل الاعسار إذا كان شخصا طبيعيا، وممثله، إذا كان شخصا اعتباريا ما يلي:\n1. أن يكون حاصلا على شهادة جامعية في الاقتصاد أو إدارة الأعمال أو القانون أو المحاسبة أو الهندسة ولديه خبرة عملية لا تقل عن خمس سنوات في مجال عمله وأن يكون مرخصا لممارسة مهنه وكلاء الاعسار وفقا لأحكام النظام الصادر لهذه الغاية.\n2. أن لا يكون من ذوي الصلة بالمدين أو تربطه به علاقة عمل او أي علاقة أخرى تؤثر حياده.\n3. ان لا يكون محترما عليه بجناية او بجنحة مخلة بالشرف أو الإخلال بالآداب والأخلاق العامة.\nب. تحدد شروط و إجراءات ترخيص وكلاء الإعسار وإعداد قائمة المرشحين لتولي مهام وكيل الإعسار بموجب نظام يصدر لهذه الغاية على أن تتضمن القائمة مستويات مختلفة من المهنيين بناء على درجة الخبرة والوسائل المتاحة لكل منهم لغايات ممارسه المهنة.","title":"شروط ترخيص وكيل الإعسار","memo":"⭐ شهادة جامعية (اقتصاد، إدارة أعمال، قانون، محاسبة، هندسة) + خبرة عملية لا تقل عن 5 سنوات + ترخيص لممارسة المهنة\n⭐ ألا يكون من ذوي الصلة بالمدين ولا تربطه به علاقة تؤثر في حياده، وألا يكون محكوما بجناية أو جنحة مخلة بالشرف\n⭐ شروط وإجراءات الترخيص وقائمة المرشحين (بمستويات مختلفة) تحدد بموجب نظام","qs":[{"q":"ما الحد الأدنى للخبرة العملية المشترطة لترخيص وكيل الإعسار؟","o":["خمس سنوات","ثلاث سنوات","عشر سنوات","سنتان"],"a":0},{"q":"أي من التخصصات الجامعية التالية لم يرد ضمن التخصصات المشترطة لترخيص وكيل الإعسار؟","o":["الطب","الهندسة","القانون","الاقتصاد"],"a":0},{"q":"تحدد شروط وإجراءات ترخيص وكلاء الإعسار وإعداد قائمة المرشحين لتولي مهامهم بموجب:","o":["نظام يصدر لهذه الغاية","تعليمات يصدرها وزير الصناعة والتجارة","قرار من المحكمة المختصة","قرار من لجنة الدائنين"],"a":0}]},{"n":"50","chapter":"الفصل الخامس - وكلاء الإعسار","notes":[],"source":"أ.1. تعين المحكمة في قرارها بإشهار الإعسار وكيل إعسار من بين الأشخاص المرخصين وفقا لأحكام هذا القانون .\n2. على المحكمة أن تراعي عند اختيار وكيل الإعسار أن يكون مناسبا لإدارة إجراءات الإعسار وذا خبره في طبيعة النشاط الاقتصادي موضوع الإجراءات وللمحكمة الاستئناس برأي الدائنين أو أي جهة تنظيمية مختصة قبل التعيين.\nب. على وكيل الإعسار إشعار المحكمة بعدم قدرته على تولي مهامه أو عن أي سبب يحول دون ذلك سواء أكان السبب ناشئا قبل صدور قرار المحكمة بتعيينه أم في أي وقت بعد ذلك خلال مدة لا تزيد على عشرة أيام من تاريخ علمه بالسبب تحت طائلة المسؤولية القانونية وحرمانه من تولي مهام وكيل إعسار في أي إجراءات إعسار مستقبليه.","title":"تعيين وكيل الإعسار","memo":"⭐ تعين المحكمة وكيل الإعسار في قرار إشهار الإعسار من بين الأشخاص المرخصين، ولها الاستئناس برأي الدائنين أو أي جهة تنظيمية مختصة\n⭐ على وكيل الإعسار إشعار المحكمة بعدم قدرته على تولي مهامه خلال مدة لا تزيد على 10 أيام من تاريخ علمه بالسبب\n⭐ الجزاء: المسؤولية القانونية والحرمان من تولي مهام وكيل إعسار في أي إجراءات مستقبلية","qs":[{"q":"متى تعين المحكمة وكيل الإعسار؟","o":["في قرارها بإشهار الإعسار","بعد انتهاء المرحلة التمهيدية","عند بدء مرحلة إعادة التنظيم","بعد تشكيل لجنة الدائنين"],"a":0},{"q":"ما المدة التي يجب أن يشعر خلالها وكيل الإعسار المحكمة بوجود سبب يحول دون توليه مهامه؟","o":["مدة لا تزيد على عشرة أيام من تاريخ علمه بالسبب","مدة لا تزيد على خمسة أيام من تاريخ تعيينه","مدة لا تزيد على ثلاثين يوما من تاريخ علمه بالسبب","مدة لا تزيد على خمسة عشر يوما من تاريخ تعيينه"],"a":0},{"q":"ما الأثر المترتب على عدم إشعار وكيل الإعسار المحكمة بعدم قدرته على تولي مهامه خلال المدة القانونية؟","o":["المسؤولية القانونية وحرمانه من تولي مهام وكيل إعسار في أي إجراءات إعسار مستقبلية","بطلان قرار إشهار الإعسار","غرامة لا تتجاوز مجموع أتعابه فقط","إلغاء ترخيصه حكما دون أي مسؤولية أخرى"],"a":0}]},{"n":"51","chapter":"الفصل الخامس - وكلاء الإعسار","notes":[],"source":"أ. على وكيل الإعسار أن يؤدي واجباته بالدقة والأمانة المطلوبة وأن يلتزم الحياد مع جميع الجهات التي تتأثر بإجراءات الاعسار.\nب. لوكيل الإعسار الاستعانة بخبراء يختارهم لتنفيذ مهامه على أن يبقى مسؤولا عن تنفيذ تلك المهام ويتحمل أتعاب الخبراء ما لم تقرر المحكمة غير ذلك.\nج. يحظر على وكيل الإعسار تفويض مهامه للغير إلا في ظروف استثنائية على أن يكون التفويض محددا من حيث المدة والمهام وبموافقة المحكمة وفي هذه الحالة يكون المفوض ووكيل الإعسار مسؤولين بالتكافل والتضامن عن أعمال المفوض.","title":"واجبات وكيل الإعسار والاستعانة بالخبراء","memo":"⭐ يلتزم وكيل الإعسار الدقة والأمانة والحياد مع جميع الجهات المتأثرة بالإجراءات\n⭐ له الاستعانة بخبراء يختارهم ويبقى مسؤولا ويتحمل أتعابهم ما لم تقرر المحكمة غير ذلك\n⭐ يحظر تفويض مهامه للغير إلا في ظروف استثنائية: تفويض محدد المدة والمهام وبموافقة المحكمة، ويكون المفوض والوكيل مسؤولين بالتكافل والتضامن","qs":[{"q":"من يتحمل أتعاب الخبراء الذين يستعين بهم وكيل الإعسار، كأصل عام؟","o":["وكيل الإعسار ما لم تقرر المحكمة غير ذلك","ذمة الإعسار في جميع الأحوال","لجنة الدائنين","المدين"],"a":0},{"q":"أي مما يلي لا يعد من شروط تفويض وكيل الإعسار مهامه للغير؟","o":["موافقة لجنة الدائنين","أن يكون في ظروف استثنائية","أن يكون التفويض محددا من حيث المدة والمهام","موافقة المحكمة"],"a":0},{"q":"فوّض وكيل إعسار بموافقة المحكمة بعض مهامه لشخص آخر فارتكب المفوض خطأ أضر بذمة الإعسار، فإن المسؤولية عن أعمال المفوض تقع على:","o":["المفوض ووكيل الإعسار بالتكافل والتضامن","المفوض وحده","وكيل الإعسار وحده","المحكمة التي وافقت على التفويض"],"a":0}]},{"n":"52","chapter":"الفصل الخامس - وكلاء الإعسار","notes":[],"source":"أ. يخضع عمل وكيل الإعسار لإشراف المحكمة ورقابة الدائنين أو من يمثلهم في الحدود المبينة في هذا القانون.\nب. للمحكمة وللجنة الدائنين، من وقت لآخر أن تكلف وكيل الاعسار بتزويدها بمعلومات محددة أو بتقديم تقرير عن سير إجراءات الاعسار وإدارة ذمة الإعسار.","title":"الإشراف والرقابة على وكيل الإعسار","memo":"⭐ يخضع عمل وكيل الإعسار لإشراف المحكمة ورقابة الدائنين أو من يمثلهم\n⭐ للمحكمة وللجنة الدائنين تكليفه من وقت لآخر بتزويدها بمعلومات محددة أو تقرير عن سير الإجراءات وإدارة ذمة الإعسار","qs":[{"q":"يخضع عمل وكيل الإعسار وفقا لقانون الإعسار إلى:","o":["إشراف المحكمة ورقابة الدائنين أو من يمثلهم","إشراف وزارة الصناعة والتجارة","رقابة المدين","إشراف هيئة الأوراق المالية"],"a":0},{"q":"من يملك تكليف وكيل الإعسار بتقديم تقرير عن سير إجراءات الإعسار وإدارة ذمة الإعسار؟","o":["المحكمة ولجنة الدائنين","المدين وحده","أي دائن منفرد","مراقب عام الشركات"],"a":0}]},{"n":"53","chapter":"الفصل الخامس - وكلاء الإعسار","notes":[],"source":"أ. تحدد أسس تقدير أتعاب وكلاء الإعسار بموجب نظام يصدر لهذه الغاية على أن يؤخذ بالاعتبار ما يلي حدا أدنى:\n1. قيمة ذمة الإعسار.\n2. مدى صعوبة الحالة وتعقيدها، بما في ذلك استمرار النشاط الاقتصادي وعدد الدائنين وتعدد وحدات النشاط الاقتصادي وعدد العمال.\n3. ربط استحقاق جزء من الأتعاب بتحقيق نتيجة.\nب. يجب أن يتضمن النظام منح الدائنين الحق في الاشتراك في تحديد أتعاب وكيل الإعسار.\nج. تحدد المحكمة أتعاب وكيل الإعسار عند تعيينه .\nد. لوكيل الاعسار ولأي من دائني الإعسار الاعتراض على قرار المحكمة بتحديد أتعاب وكيل الاعسار خلال مدة خمسه ايام من تاريخ صدوره وعلى المحكمة البت فيه خلال مدة خمسة أيام من تاريخ تقديمه .\nهـ. إذا لم تكف ذمة الإعسار لدفع أتعاب وكيل الإعسار فيتقاضى مبلغا مقطوعا وفقا لأحكام المادة (112) من هذا القانون.","title":"أتعاب وكيل الإعسار","memo":"⭐ أسس تقدير الأتعاب بنظام، وتراعى حدا أدنى: قيمة ذمة الإعسار، صعوبة الحالة وتعقيدها، ربط جزء من الأتعاب بتحقيق نتيجة\n⭐ يتضمن النظام حق الدائنين في الاشتراك في تحديد الأتعاب، وتحدد المحكمة الأتعاب عند تعيينه\n⭐ الاعتراض على قرار تحديد الأتعاب خلال 5 أيام من صدوره، وتبت المحكمة خلال 5 أيام من تقديمه\n⭐ إذا لم تكف ذمة الإعسار يتقاضى مبلغا مقطوعا وفق المادة (112)","qs":[{"q":"متى تحدد المحكمة أتعاب وكيل الإعسار؟","o":["عند تعيينه","عند انتهاء المرحلة التمهيدية","بعد اعتماد تقرير المحاسبة النهائي","عند الموافقة على خطة إعادة التنظيم"],"a":0},{"q":"ما مدة الاعتراض على قرار المحكمة بتحديد أتعاب وكيل الإعسار؟","o":["خمسة أيام من تاريخ صدوره","عشرة أيام من تاريخ صدوره","خمسة عشر يوما من تاريخ تبلغه","ثلاثون يوما من تاريخ صدوره"],"a":0},{"q":"أي مما يلي لم يرد ضمن الأمور التي تؤخذ بالاعتبار حدا أدنى عند تقدير أتعاب وكيل الإعسار؟","o":["عدد سنوات خبرة وكيل الإعسار","قيمة ذمة الإعسار","مدى صعوبة الحالة وتعقيدها","ربط استحقاق جزء من الأتعاب بتحقيق نتيجة"],"a":0},{"q":"إذا لم تكف ذمة الإعسار لدفع أتعاب وكيل الإعسار، فإنه:","o":["يتقاضى مبلغا مقطوعا وفقا لأحكام المادة (112)","يتحمل المدين الأتعاب من أمواله الخاصة","يتحمل الدائنون الأتعاب بنسبة ديونهم","يفقد حقه في الأتعاب"],"a":0}]},{"n":"54","chapter":"الفصل الخامس - وكلاء الإعسار","notes":[],"source":"أ. للمحكمة من تلقاء ذاتها أو بناء على طلب من لجنة الدائنين أو ائنين يمثلون ما نسبته (%10) على الأقل من إجمالي الديون أو بناء على طلب المدين، أن تعزل وكيل الإعسار إذا قصر في أداء واجباته.\nب. تستمع المحكمة لأقوال وكيل الإعسار ولأقوال لجنة الدائنين إذا كان الطلب مقدما من المدين قبل إصدار قرار العزل.\nج. لوكيل الإعسار أن يستقيل لأسباب مبررة أو إذا كان بقاؤه لا يحقق مصلحة الدائنين و إذا كانت الاستقالة غير مبررة فيترتب على وكيل الإعسار غرامة أو تبعات أخرى حسب ما ينص عليه النظام الذي يصدر بمقتضى أحكام هذا القانون.\nد. إذا تم عزل وكيل الإعسار او استقال تعين المحكمة فورا وكيل إعسار جديدا وفي هذه الحالة يستمر وكيل الاعسار الذي انتهى تعيينه بأداء واجباته الى حين تولي وكيل الإعسار الجديد مهامه ما لم تقرر المحكمه خلاف ذلك.","title":"عزل وكيل الإعسار واستقالته","memo":"⭐ للمحكمة عزل وكيل الإعسار إذا قصر: من تلقاء ذاتها أو بطلب لجنة الدائنين أو دائنين يمثلون 10% على الأقل من إجمالي الديون أو بطلب المدين\n⭐ إذا كان الطلب من المدين تستمع المحكمة لأقوال الوكيل ولجنة الدائنين قبل العزل\n⭐ الاستقالة لأسباب مبررة أو إذا كان بقاؤه لا يحقق مصلحة الدائنين، وغير المبررة يترتب عليها غرامة أو تبعات حسب النظام\n⭐ عند العزل أو الاستقالة تعين المحكمة فورا وكيلا جديدا ويستمر القديم بواجباته حتى تولي الجديد ما لم تقرر المحكمة خلاف ذلك","qs":[{"q":"ما الحد الأدنى لنسبة الديون التي يجب أن يمثلها الدائنون لطلب عزل وكيل الإعسار؟","o":["(10%) من إجمالي الديون","(25%) من إجمالي الديون","(20%) من إجمالي الديون","(50%) من إجمالي الديون"],"a":0},{"q":"أي من الجهات التالية لا يملك طلب عزل وكيل الإعسار وفقا للمادة (54)؟","o":["أي دائن منفرد بغض النظر عن نسبة دينه","لجنة الدائنين","المدين","دائنون يمثلون (10%) على الأقل من إجمالي الديون"],"a":0},{"q":"استقال وكيل إعسار وعينت المحكمة وكيلا جديدا لم يتسلم مهامه بعد، فما حكم الوكيل المستقيل؟","o":["يستمر في أداء واجباته إلى حين تولي الوكيل الجديد مهامه ما لم تقرر المحكمة خلاف ذلك","تنتهي مهامه فور تقديم الاستقالة","تتولى لجنة الدائنين مهامه مؤقتا","يتولى المدين إدارة ذمة الإعسار مؤقتا"],"a":0}]},{"n":"55","chapter":"الفصل الخامس - وكلاء الإعسار","notes":[],"source":"أ. على وكيل الإعسار أن يقدم تقريرا ماليا وإداريا بما استكمل من أعمال تنفيذا لمهامه في نهاية المرحلة التمهيدية ضمن التقرير المعد منه وفقا لأحكام هذا القانون.\nب. يقدم وكيل الإعسار تقرير المحاسبة النهائي للجنة الدائنين والتي تقوم بدورها بابداء ملاحظاتها عليه خلال مدة عشرة أيام من تاريخ تسلمه .\nج. يودع تقرير المحاسبة النهائي مع ملاحظات لجنة الدائنين إن وجدت لدى المحكمة ويتم تبليغه للمدين ودائنيه ويتم نشر واقعة الإيداع في سجل الإعسار.\nد. للمدين ودائنيه الاعتراض على تقرير المحاسبة النهائي خلال مدة عشرة أيام من تاريخ إيداعه لدى المحكمة وإذا لم يقدم أي اعتراض خلال المدة المذكورة تعتمده المحكمة دون حاجه لاتخاذ أي إجراءات أخرى.\nهـ. إذا تم الاعتراض على تقرير المحاسبة النهائي فتبلغ لائحة الاعتراض والبينات المعززة له لوكيل الإعسار وعلى وكيل الإعسار أن يجيب خطيا على اللائحة خلال مدة عشرة أيام من تاريخ تبلغه.\nو. تعين المحكمة موعدا للنظر في الاعتراض لا يتجاوز مدة عشرة أيام من تاريخ تقديم جواب وكيل الإعسار أو انتهاء المدة القانونيه له، ويبلغ الموعد لوكيل الإعسار والخصم.","title":"تقارير وكيل الإعسار وتقرير المحاسبة النهائي","memo":"⭐ يقدم الوكيل تقريرا ماليا وإداريا في نهاية المرحلة التمهيدية\n⭐ تبدي لجنة الدائنين ملاحظاتها على تقرير المحاسبة النهائي خلال 10 أيام من تسلمه، ثم يودع لدى المحكمة وينشر الإيداع في سجل الإعسار\n⭐ اعتراض المدين ودائنيه خلال 10 أيام من الإيداع، وإلا تعتمده المحكمة دون إجراءات أخرى\n⭐ جواب الوكيل على الاعتراض خطيا خلال 10 أيام من تبلغه، وموعد النظر لا يتجاوز 10 أيام من الجواب","qs":[{"q":"ما المدة التي تبدي فيها لجنة الدائنين ملاحظاتها على تقرير المحاسبة النهائي؟","o":["عشرة أيام من تاريخ تسلمه","خمسة أيام من تاريخ تسلمه","خمسة عشر يوما من تاريخ تسلمه","ثلاثون يوما من تاريخ تسلمه"],"a":0},{"q":"إذا لم يقدم أي اعتراض على تقرير المحاسبة النهائي خلال المدة القانونية، فإن:","o":["المحكمة تعتمده دون حاجة لاتخاذ أي إجراءات أخرى","لجنة الدائنين تصوت على اعتماده","وكيل الإعسار يعيد تقديمه للمحكمة","المحكمة تعين خبيرا لتدقيقه"],"a":0},{"q":"يقدم وكيل الإعسار تقرير المحاسبة النهائي ابتداء إلى:","o":["لجنة الدائنين","المدين","محكمة الاستئناف","سجل الإعسار"],"a":0}]},{"n":"56","chapter":"الفصل الخامس - وكلاء الإعسار","notes":[],"source":"أ. يكون وكيل الإعسار مسؤولا عن أي ضرر يلحق بذمة الإعسار أو بالأشخاص الذين اشتركوا في إجراءات الإعسار نشأ عن إهماله أو إهمال ممثليه أو تابعيه في أداء مهامهم أو إخلالهم بالواجبات المنوطة بهم.\nب. يسقط حق المطالبة بالتعويض المنصوص عليه في الفقرة (أ) من هذه المادة بمرور ثلاث سنوات على تاريخ علم المضرور بالضرر وبالشخص المسؤول عنه أو بمرور ثلاث سنوات على تاريخ استكمال إجراءات الإعسار أيهما يقع لاحقا.\nج. على وكيل الإعسار تقديم ضمانات كافية أو استصدار بوليصة تأمين ضد المسؤولية المهنية وفقا للشروط التي ينص عليها النظام الذي يصدر بموجب أحكام هذا القانون.","title":"مسؤولية وكيل الإعسار عن الضرر","memo":"⭐ يسأل الوكيل عن أي ضرر يلحق بذمة الإعسار أو المشتركين في الإجراءات نشأ عن إهماله أو إهمال ممثليه أو تابعيه\n⭐ يسقط حق المطالبة بالتعويض بمرور 3 سنوات على علم المضرور بالضرر وبالمسؤول أو 3 سنوات على استكمال الإجراءات أيهما لاحقا\n⭐ عليه تقديم ضمانات كافية أو بوليصة تأمين ضد المسؤولية المهنية وفق النظام","qs":[{"q":"يسقط حق المطالبة بالتعويض عن الضرر الناشئ عن إهمال وكيل الإعسار بمرور:","o":["ثلاث سنوات من تاريخ العلم بالضرر وبالمسؤول أو من استكمال الإجراءات أيهما يقع لاحقا","ثلاث سنوات من تاريخ العلم بالضرر أيهما يقع أولا","خمس سنوات من تاريخ استكمال إجراءات الإعسار","سنة واحدة من تاريخ وقوع الضرر"],"a":0},{"q":"لضمان مسؤوليته المهنية يلتزم وكيل الإعسار بـ:","o":["تقديم ضمانات كافية أو استصدار بوليصة تأمين ضد المسؤولية المهنية","إيداع نسبة من أتعابه في صندوق المحكمة","تقديم كفالة شخصية من أحد الدائنين","رهن أحد أمواله لصالح ذمة الإعسار"],"a":0},{"q":"ألحق أحد تابعي وكيل الإعسار ضررا بذمة الإعسار بسبب إهماله، فإن المسؤول عن الضرر وفقا للمادة (56):","o":["وكيل الإعسار","التابع وحده دون وكيل الإعسار","المحكمة","لجنة الدائنين"],"a":0}]},{"n":"57","chapter":"الفصل السادس - حصر الأموال والالتزامات","notes":[],"source":"أ. على وكيل الإعسار أن يعد تقريرا خلال مدة شهرين من تاريخ تعيينه وللمحكمة أن تمدد هذه المدة لظروف استثنائية لمدة شهر واحد فقط.\nب. إذا لم يقدم وكيل الإعسار التقرير خلال المدد المنصوص عليها في الفقرة (أ) من هذه المادة فللمحكمة أن تفرض عليه غرامه مقدارها لا يتجاوز مجموع أتعابه مع مراعاة الظروف ومدة التأخير على ان تقوم باعلام الجهة المسؤولة عن ترخيص وكلاء الإعسار بالواقعة.","title":"مدة إعداد تقرير وكيل الإعسار","memo":"⭐ يعد الوكيل تقريره خلال شهرين من تعيينه، وللمحكمة التمديد لظروف استثنائية لمدة شهر واحد فقط\n⭐ عند التأخير للمحكمة فرض غرامة لا تتجاوز مجموع أتعابه مع إعلام جهة ترخيص وكلاء الإعسار","qs":[{"q":"ما المدة التي يجب على وكيل الإعسار إعداد تقريره خلالها من تاريخ تعيينه؟","o":["شهران","شهر واحد","ثلاثة أشهر","أربعة أشهر"],"a":0},{"q":"ما الحد الأقصى للغرامة التي يجوز للمحكمة فرضها على وكيل الإعسار إذا لم يقدم التقرير خلال المدة؟","o":["مجموع أتعابه","نصف أتعابه","ضعف أتعابه","(10%) من قيمة ذمة الإعسار"],"a":0},{"q":"يجوز للمحكمة تمديد مدة تقديم تقرير وكيل الإعسار لظروف استثنائية لمدة:","o":["شهر واحد فقط","شهرين","خمسة عشر يوما","ثلاثة أشهر"],"a":0}]},{"n":"58","chapter":"الفصل السادس - حصر الأموال والالتزامات","notes":[],"source":"أ. يجب أن يتضمن تقرير وكيل الإعسار المشار إليه في الفقرة (أ) من المادة (55) من هذا القانون ما يلي حدا أدنى:\n1. تحليلا للوثائق التي أرفقها المدين بطلبه أو قدمها بناء على تكليف المحكمة وفقا لأحكام الفقرة (ب) من المادة (13) من هذا القانون، مع بيان أي إخلال من المدين بواجباته المنصوص عليها في هذا القانون ان وجد .\n2. تحليلا لأسباب الإعسار مع تقييم مفصل للأسباب التي استند إليها المدين في طلب اشهار الإعسار وبيان رأي وكيل الإعسار بخصوص أسباب إعسار المدين.\n3. تقييما عاما لإمكانيه استمرار النشاط الاقتصادي.\n4. بيانا بالقرارات والإجراءات التي اتخذها وكيل الإعسار منذ تعيينه.\nب. يجب أن يرفق بتقرير وكيل الاعسار ما يلي:\n1. قائمة بأموال المدين وحقوقه وتقدير قيمة كل منها وفقا للمادة (60) من هذا القانون.\n2. قائمة الدائنين مع التعريف بكل دائن والمبلغ المستحق له وتصنيفه المقترح لغايات إجراءات الإعسار مع التمييز بين دائني إجراءات الاعسار ودائني الإعسار.\n3. كشف بالدعاوى المقامة من المدين أو ضده","title":"محتويات تقرير وكيل الإعسار","memo":"⭐ يتضمن حدا أدنى: تحليل وثائق المدين، تحليل أسباب الإعسار، تقييم إمكانية استمرار النشاط، بيان القرارات والإجراءات المتخذة\n⭐ يرفق به: قائمة أموال المدين وحقوقه وتقدير قيمتها، قائمة الدائنين وتصنيفها، كشف بالدعاوى من المدين أو ضده\n⭐ تميز قائمة الدائنين بين دائني إجراءات الإعسار ودائني الإعسار","qs":[{"q":"أي مما يلي يرفق بتقرير وكيل الإعسار ولا يعد من مضمونه الأساسي؟","o":["كشف بالدعاوى المقامة من المدين أو ضده","تحليل لأسباب الإعسار","تقييم عام لإمكانية استمرار النشاط الاقتصادي","بيان بالقرارات التي اتخذها وكيل الإعسار منذ تعيينه"],"a":0},{"q":"يجب أن تميز قائمة الدائنين المرفقة بتقرير وكيل الإعسار بين:","o":["دائني إجراءات الإعسار ودائني الإعسار","الدائنين الأردنيين والأجانب","الدائنين الأفراد والبنوك","الدائنين الحاضرين والغائبين"],"a":0},{"q":"أي مما يلي لم يرد ضمن ما يجب أن يتضمنه تقرير وكيل الإعسار حدا أدنى؟","o":["خطة إعادة تنظيم بديلة يعدها وكيل الإعسار","تحليل الوثائق التي أرفقها المدين بطلبه","بيان أي إخلال من المدين بواجباته إن وجد","تحليل لأسباب الإعسار ورأي وكيل الإعسار فيها"],"a":0}]},{"n":"59","chapter":"الفصل السادس - حصر الأموال والالتزامات","notes":[],"source":"أ. تتكون ذمة الاعسار من أموال المدين وحقوقه كما هي في تاريخ إشهار الإعسار والأموال والحقوق التي يتملكها المدين إما مباشرة أو من خلال وكيل الإعسار بعد إشهار الإعسار.\nب. تعتبر أموال المدين وحقوقه جزءا لا يتجزأ من ذمة الإعسار ودون حاجة لأي إجراء قانوني ويسري هذا الحكم على الأموال والحقوق التي لا يعلم وكيل الإعسار بوجودها والتي لم يتم إدراجها في قائمة الجرد.\nج. على الرغم مما ورد في الفقرة (ب) من هذه المادة، إذا رأى وكيل الإعسار أن هناك أموالا معرضة للتلف أو النقصان بشكل يضر بذمة الإعسار فله أن يطلب من المحكمة حصرها وختمها من موظف المحكمة أو حمايتها بأي طريقة مناسبة أخرى بما في ذلك بيعها بالطريقة التي تحددها المحكمة.\nد. اذا كان المدين شخصا طبيعيا فلا تعتبر الأموال والحقوق المستثناة من الحجز المنصوص عليها في قانون أصول المحاكمات المدنية وقانون التنفيذ جزءا من ذمة الإعسار.","title":"تكوين ذمة الإعسار","memo":"⭐ تتكون ذمة الإعسار من أموال المدين وحقوقه في تاريخ الإشهار وما يتملكه بعده مباشرة أو عبر وكيل الإعسار\n⭐ تعتبر جزءا منها دون حاجة لأي إجراء، ولو لم يعلم بها الوكيل أو لم تدرج في قائمة الجرد\n⭐ للوكيل طلب حصر وختم الأموال المعرضة للتلف أو حمايتها أو بيعها بالطريقة التي تحددها المحكمة\n⭐ للشخص الطبيعي: الأموال المستثناة من الحجز (أصول المحاكمات المدنية وقانون التنفيذ) ليست من ذمة الإعسار","qs":[{"q":"ما حكم أموال المدين التي لا يعلم وكيل الإعسار بوجودها ولم تدرج في قائمة الجرد؟","o":["تعتبر جزءا لا يتجزأ من ذمة الإعسار دون حاجة لأي إجراء قانوني","لا تعتبر من ذمة الإعسار إلا بعد إدراجها في قائمة الجرد","تعود للمدين بعد انتهاء إجراءات الإعسار","تعتبر من ذمة الإعسار بقرار من لجنة الدائنين"],"a":0},{"q":"إذا كان المدين شخصا طبيعيا، فأي من الأموال التالية لا تعتبر جزءا من ذمة الإعسار؟","o":["الأموال والحقوق المستثناة من الحجز وفقا لقانون أصول المحاكمات المدنية وقانون التنفيذ","الأموال التي تملكها بعد إشهار الإعسار","الأموال التي لم تدرج في قائمة الجرد","الحقوق التي كانت له في تاريخ إشهار الإعسار"],"a":0},{"q":"رأى وكيل الإعسار أن بضاعة للمدين معرضة للتلف، فما الإجراء الذي يملكه وفقا للقانون؟","o":["أن يطلب من المحكمة حصرها وختمها أو حمايتها أو بيعها بالطريقة التي تحددها المحكمة","أن يبيعها مباشرة دون الرجوع للمحكمة","أن يسلمها لأكبر الدائنين","أن يطلب من لجنة الدائنين إتلافها"],"a":0}]},{"n":"60","chapter":"الفصل السادس - حصر الأموال والالتزامات","notes":[],"source":"أ. على وكيل الإعسار إعداد قائمة تتضمن جرد أموال المدين وحقوقه.\nب. تتضمن قائمة الجرد تقدير قيمة الأموال والحقوق كما هي في تاريخ سابق لا يتجاوز عشرة أيام قبل تاريخ تسليم التقرير المعد من وكيل الإعسار.\nج. يتم وصف كل مال أو حق بشكل كاف بما في ذلك مكان وجوده ورقم تسجيله وأي حجز أو حق قائم عليه.\nد. يقدر كل مال أو حق على أساس القيمة السوقية العادلة ويجوز اعتماد التقدير الذي تتضمنه البيانات المالية للمدين ما لم يكن هناك أسباب موضوعية تدعو للاعتقاد بعدم دقتها أو بأن المعلومات قديمة أو أن الظروف قد تغيرت منذ إعدادها وللمحكمة بناء على طلب وكيل الإعسار تعيين خبير لتقدير قيمة أي من هذه الأموال.\nهـ. تستثنى أموال الغير التي في حيازة المدين من قائمة الجرد على أنه إذا كانت الأموال في حيازة المدين لسبب قانوني فيجب تضمين حق الحيازة في تلك القائمة .\nو. تتضمن قائمة الجرد حصرا للديون المترتبة للمدين على الغير مع بيان أسماء المدينين ومبالغ الديون وتاريخ استحقاقها، وعلى وكيل الإعسار ارفاق كشف بالديون والحقوق المتنازع عليها وكشف آخر بالدعاوى المقامة من المدين أو ضده والمرحلة التي وصلت إليها كل منها.","title":"قائمة جرد أموال المدين","memo":"⭐ تقدر قيمة الأموال كما هي في تاريخ سابق لا يتجاوز 10 أيام قبل تسليم تقرير الوكيل\n⭐ التقدير على أساس القيمة السوقية العادلة، ويجوز اعتماد تقدير البيانات المالية ما لم توجد أسباب موضوعية، وللمحكمة بطلب الوكيل تعيين خبير\n⭐ تستثنى أموال الغير في حيازة المدين، ويدرج حق الحيازة إن كانت لسبب قانوني\n⭐ تتضمن حصر ديون المدين على الغير، مع كشف بالديون المتنازع عليها وكشف بالدعاوى","qs":[{"q":"على أي أساس يقدر كل مال أو حق في قائمة الجرد؟","o":["القيمة السوقية العادلة","التكلفة التاريخية","القيمة الدفترية دائما","قيمة التصفية القسرية"],"a":0},{"q":"تتضمن قائمة الجرد تقدير قيمة الأموال كما هي في تاريخ سابق لا يتجاوز ...... قبل تاريخ تسليم تقرير وكيل الإعسار:","o":["عشرة أيام","خمسة أيام","ثلاثين يوما","شهرين"],"a":0},{"q":"كانت في حيازة المدين آلات مستأجرة من الغير بموجب عقد إيجار، فكيف تعامل في قائمة الجرد؟","o":["تستثنى الآلات ويدرج حق الحيازة في القائمة","تدرج الآلات بقيمتها السوقية العادلة","تدرج الآلات بقيمتها الدفترية","تدرج الآلات في قائمة مستقلة لبيعها"],"a":0}]},{"n":"61","chapter":"الفصل السادس - حصر الأموال والالتزامات","notes":[],"source":"أ. يتم تسجيل الديون خطيا عن طريق تقديم طلب تسجيل الدين من الدائن مرفقا به الوثائق المعززة له خلال مدة ثلاثين يوما من نشر قرار الإعسار وفقا لأحكام هذا القانون.\nب. يتضمن طلب التسجيل اسم الدائن وموطنه أو مقره المسجل وأي معلومات لازمة للتعريف به وعنوانه وعنوان بريده الالكتروني للتبليغ ان وجد إضافة للمعلومات المتعلقة بدينه خصوصا أصله ومقداره وتاريخ نشوئه وتاريخ استحقاقه وطبيعته اضافة الى تصنيفه وفقا لقواعد الإعسار حسب رأى الدائن واذا كان الدين مضمونا فيجب أن يتضمن الطلب وصفا للضمانة والبيانات المدرجة في السجل الذي تم تسجيل أو إشهار الحق في الضمانة فيه.\nج. يرفق الطلب بالوثائق المعززة له، وللدائن تقديم صور عن تلك الوثائق على أنه يحق لوكيل الإعسار طلب أصل تلك الوثائق إذا رأى ذلك ضروريا.\nد. تعامل الديون التي لم تحل آجالها على أنها ديون مستحقة لغايات تسجيلها.","title":"تسجيل الديون","memo":"⭐ يسجل الدين خطيا بطلب من الدائن مع الوثائق المعززة خلال 30 يوما من نشر قرار الإعسار\n⭐ يتضمن الطلب بيانات الدائن والدين (أصله ومقداره وتاريخ نشوئه واستحقاقه وطبيعته وتصنيفه)، ووصف الضمانة إن كان مضمونا\n⭐ للدائن تقديم صور الوثائق ولوكيل الإعسار طلب الأصل إذا رأى ضرورة\n⭐ الديون التي لم تحل آجالها تعامل كديون مستحقة لغايات التسجيل","qs":[{"q":"ما مدة تقديم طلب تسجيل الدين من الدائن؟","o":["ثلاثون يوما من نشر قرار الإعسار","عشرة أيام من نشر قرار الإعسار","ستون يوما من تاريخ تعيين وكيل الإعسار","اثنا عشر شهرا من نشر قرار الإعسار"],"a":0},{"q":"كيف تعامل الديون التي لم تحل آجالها لغايات تسجيلها؟","o":["على أنها ديون مستحقة","تؤجل إلى حين حلول أجلها","لا يجوز تسجيلها","تسجل في قائمة مستقلة دون حق التصويت"],"a":0},{"q":"قدم دائن صورا عن الوثائق المعززة لدينه، فما الحكم؟","o":["يقبل ذلك، ولوكيل الإعسار طلب أصل الوثائق إذا رأى ذلك ضروريا","يرفض الطلب لوجوب تقديم الأصول دائما","يقبل ذلك بشرط تصديق الصور من المحكمة","يقبل ذلك بموافقة لجنة الدائنين فقط"],"a":0}]},{"n":"62","chapter":"الفصل السادس - حصر الأموال والالتزامات","notes":[],"source":"أ.1. على وكيل الإعسار مراجعة طلبات تسجيل الديون المقدمة من الدائنين والتأكد من صحتها وتصنيفها ومن ثم إدراجها في قائمة الدائنين و تشمل الديون المدرجة في قائمة الدائنين الديون التي جرى تسجيلها خلال إجراءات الإعسار وتلك المستخلصة من قيود ودفاتر المدين المحاسبية.\n2. يجب أن تتضمن قائمة الدائنين تعريفا بالدائن ومبلغ الدين وتصنيفه كدين مضمون أو دين ممتاز أو دين غير مضمون أو أحد الديون الأدنى في مرتبة الأولوية.\nب. تدرج الديون التي يرى وكيل الإعسار أنها لم تثبت بشكل كاف في فائمة مستقلة مع بيان سبب عدم ادراجها في قائمة الدائنين .\nج. تودع قائمة الدائنين لدى المحكمة معززة بالمطالبات والوثائق المرفقة بها ويتم إشهار واقعة استكمال اعداد القائمة وإيداعها بموجب إشعار في سجل الإعسار وفي الجريدة الرسمية وفي صحيفة يومية إذا رأت المحكمة ضرورة لذلك.","title":"قائمة الدائنين وإيداعها","memo":"⭐ يراجع الوكيل طلبات التسجيل ويدرجها، وتشمل القائمة الديون المسجلة والمستخلصة من دفاتر المدين\n⭐ تصنيف الدين: مضمون، ممتاز، غير مضمون، أو أدنى في مرتبة الأولوية\n⭐ الديون غير الثابتة بشكل كاف تدرج في قائمة مستقلة مع بيان السبب\n⭐ تودع القائمة لدى المحكمة ويشهر الإيداع في سجل الإعسار والجريدة الرسمية وصحيفة يومية إذا رأت المحكمة ضرورة","qs":[{"q":"أي مما يلي لا يعد من تصنيفات الديون في قائمة الدائنين؟","o":["دين احتمالي مؤجل","دين مضمون","دين ممتاز","دين أدنى في مرتبة الأولوية"],"a":0},{"q":"كيف يتعامل وكيل الإعسار مع الديون التي يرى أنها لم تثبت بشكل كاف؟","o":["تدرج في قائمة مستقلة مع بيان سبب عدم إدراجها في قائمة الدائنين","تستبعد نهائيا دون ذكرها","تدرج في قائمة الدائنين كديون غير مضمونة","تحال إلى المحكمة للبت فيها قبل إعداد القائمة"],"a":0},{"q":"يتم إشهار واقعة استكمال إعداد قائمة الدائنين وإيداعها بموجب إشعار في:","o":["سجل الإعسار والجريدة الرسمية، وفي صحيفة يومية إذا رأت المحكمة ضرورة لذلك","سجل الإعسار فقط","صحيفتين يوميتين محليتين","الموقع الإلكتروني لوزارة العدل فقط"],"a":0}]},{"n":"63","chapter":"الفصل السادس - حصر الأموال والالتزامات","notes":[],"source":"أ. تدرج الديون التالية في قائمة الدائنين حكما :\n1. الديون الثابته بموجب حكم قضائي أو قرار تحكيم مكتسب الدرجة القطعية.\n2. ديون الخزينة.\n3. الديون المضمونة بحق عيني مسجل وفق أحكام التشريعات النافذة.\nب. تدرج المطالبات غير المحددة القيمة عن طريق تقدير قيمتها كما هي في تاريخ إشهار الاعسار على أن تستخدم هذه القيمة بشكل حصري لغايات إدراج المطالبات في قائمه الدائنين.","title":"الديون المدرجة حكما","memo":"⭐ تدرج حكما: الديون الثابتة بحكم قضائي أو قرار تحكيم قطعي، ديون الخزينة، الديون المضمونة بحق عيني مسجل\n⭐ المطالبات غير المحددة القيمة تدرج بتقدير قيمتها في تاريخ إشهار الإعسار، لغايات الإدراج حصرا","qs":[{"q":"أي من الديون التالية لا يدرج حكما في قائمة الدائنين؟","o":["الدين الثابت بسند عادي غير مصدق","ديون الخزينة","الدين الثابت بحكم قضائي مكتسب الدرجة القطعية","الدين المضمون بحق عيني مسجل"],"a":0},{"q":"تدرج المطالبات غير المحددة القيمة في قائمة الدائنين عن طريق تقدير قيمتها كما هي في تاريخ:","o":["إشهار الإعسار","تقديم طلب التسجيل","إيداع قائمة الدائنين","نشأة الدين"],"a":0}]},{"n":"64","chapter":"الفصل السادس - حصر الأموال والالتزامات","notes":[],"source":"أ. للمدين ولأي من دائني الإعسار، بما في ذلك الدائنين الذين لم يسجلوا ديونهم، الاعتراض على أي دين مدرج في قائمه الدائنين بما في ذلك إدراج الديون أو استبعادها أو مبلغ الدين المعترف به أو تصنيفه لغايات الإعسار.\nب. يقدم الاعتراض المنصوص عليه في الفقرة (أ) من هذه المادة للمحكمة خطيا خلال مدة عشرة أيام من تاريخ إشهار قائمة الديون بموجب أحكام المادة (62) من هذا القانون ويجب أن ترفق به المستندات التي تثبت الادعاءات الواردة فيه.\nج. لأي شخص ذي مصلحه يرغب في الاعتراض على استحقاق دين تضمنته قائمة الدائنين أن يتقدم بطلب بهذا الخصوص للمحكمة وتبلغ المحكمة الاعتراض لوكيل الإعسار وللدائن صاحب الدين موضوع الاعتراض ولأي منهما الرد عليه خلال مدة عشرة أيام من تاريخ تبلغه.\nد. للمحكمة من تلقاء ذاتها أو بناء على طلب المعترض، أن تعين جلسة لسماع البينة الشخصية للتحقق من الادعاءات الواردة في الاعتراض.\nهـ. تبت المحكمة في الاعتراضات المقدمة بموجب أحكام هذه المادة خلال مدة خمسة عشر يوما من تاريخ استلام رد وكيل الإعسار أو الدائن حسب مقتضى الحال.\nو. لا يوقف تقديم الاعتراضات السير في إجراءات الاعسار، على أنه إذا تجاوزت نسبة المطالبات المعترض عليها (%30) من إجمالي المطالبات، فللمحكمة أن تقرر تعليق كل إجراءات الإعسار أو بعضها لمدة كافية تمكنها من البت في الاعتراضات.","title":"الاعتراض على قائمة الدائنين","memo":"⭐ للمدين وأي دائن إعسار (ولو لم يسجل دينه) الاعتراض خطيا للمحكمة خلال 10 أيام من إشهار قائمة الديون\n⭐ الرد على الاعتراض من الوكيل أو الدائن خلال 10 أيام من التبلغ، وتبت المحكمة خلال 15 يوما من استلام الرد\n⭐ لا يوقف الاعتراض السير في الإجراءات، إلا إذا تجاوزت المطالبات المعترض عليها 30% فللمحكمة تعليقها كليا أو جزئيا","qs":[{"q":"ما مدة تقديم الاعتراض على أي دين مدرج في قائمة الدائنين؟","o":["عشرة أيام من تاريخ إشهار قائمة الديون","خمسة عشر يوما من تاريخ إشهار قائمة الديون","ثلاثون يوما من نشر قرار الإعسار","خمسة أيام من تاريخ إيداع القائمة"],"a":0},{"q":"خلال أي مدة تبت المحكمة في الاعتراضات على قائمة الدائنين؟","o":["خمسة عشر يوما من تاريخ استلام رد وكيل الإعسار أو الدائن","عشرة أيام من تاريخ تقديم الاعتراض","ثلاثون يوما من تاريخ تقديم الاعتراض","خمسة أيام من تاريخ استلام الرد"],"a":0},{"q":"بلغت نسبة المطالبات المعترض عليها (35%) من إجمالي المطالبات، فما الحكم؟","o":["للمحكمة أن تقرر تعليق إجراءات الإعسار كلها أو بعضها لمدة كافية للبت في الاعتراضات","تتوقف إجراءات الإعسار حكما","لا أثر لذلك إذ لا يوقف الاعتراض الإجراءات في جميع الأحوال","تنتقل الإجراءات حكما إلى التصفية"],"a":0},{"q":"أي مما يلي صحيح بشأن حق الاعتراض على قائمة الدائنين؟","o":["يحق للدائنين الذين لم يسجلوا ديونهم الاعتراض على أي دين مدرج","يقتصر حق الاعتراض على الدائنين المسجلين","لا يحق للمدين الاعتراض على القائمة","يقدم الاعتراض شفاهة أمام وكيل الإعسار"],"a":0}]},{"n":"65","chapter":"الفصل السادس - حصر الأموال والالتزامات","notes":[],"source":"أ. لا يقبل أي طلب تسجيل ديون مقدم بعد مرور مدة ثلاثين يوما من تاريخ نشر قرار اشهار الاعسار وفقا لأحكام هذا القانون ولا يعتد بأي ادعاء بعدم علم الدائن بإعسار المدين كمعذرة لقبول طلب التسجيل.\nب. يسقط حق أصحاب الطلبات المنصوص عليها في الفقرة (أ) من هذه المادة في الاشتراك في التصويت على أي قرار أو قبض أي توزيع بموجب إجراءات تمت قبل تاريخ تقديم طلب التسجيل.\nج. لا تقبل أي مطالبة تتم في فترة تقديم المطالبات والتي يعتمد تسجيلها على تحقيق من جهة رسمية إلا إذا قامت الجهة الرسمية المختصة بتقديم مطالبة بدين محتمل.\nد. يتحمل الدائن أي نفقات إضافية ناجمة عن التأخر في تقديم مطالبته.\nهـ. في جميع الاحوال لا ينظر بأي طلبات تسجيل ديون بعد مرور اثني عشر شهرا على تاريخ نشر قرار إشهار الإعسار وفقا لأحكام المادة (16) من هذا القانون.","title":"طلبات التسجيل المتأخرة","memo":"⭐ لا يقبل طلب التسجيل بعد 30 يوما من نشر قرار الإشهار، ولا يعتد بادعاء عدم العلم\n⭐ يسقط حق المتأخرين في التصويت أو قبض التوزيعات عن إجراءات تمت قبل تقديم طلبهم، ويتحمل الدائن النفقات الإضافية للتأخير\n⭐ في جميع الأحوال لا ينظر بأي طلب بعد 12 شهرا من نشر قرار الإشهار وفق المادة (16)","qs":[{"q":"في جميع الأحوال، لا ينظر بأي طلبات تسجيل ديون بعد مرور ...... على تاريخ نشر قرار إشهار الإعسار:","o":["اثني عشر شهرا","ستة أشهر","ثلاثين يوما","أربعة وعشرين شهرا"],"a":0},{"q":"ادعى دائن أنه لم يعلم بإعسار المدين وقدم طلب تسجيل دينه بعد مرور (45) يوما من نشر قرار الإشهار، فما الحكم؟","o":["لا يقبل الطلب ولا يعتد بادعاء عدم العلم كمعذرة","يقبل الطلب إذا أثبت عدم علمه","يقبل الطلب بموافقة لجنة الدائنين","يقبل الطلب مع فرض غرامة على الدائن"],"a":0},{"q":"من يتحمل النفقات الإضافية الناجمة عن التأخر في تقديم المطالبة؟","o":["الدائن","ذمة الإعسار","وكيل الإعسار","المدين"],"a":0}]},{"n":"66","chapter":"الفصل السابع - مراحل إجراءات الاعسار","notes":[],"source":"تنتهي المرحلة التمهيدية في أي من الحالات التالية:\nأ. انتهاء المدة المحددة لاستئناف قرار اعتماد قائمة الجرد أو قائمة الدائنين أو البت في الاعتراضات المقدمة على أي منها.\nب. صدور قرار المحكمة بالانتقال من المرحلة التمهيدية للمراحل التي تليها قبل البت في الاعتراضات المقدمة على قرار اعتماد قائمة الجرد أو قائمة الدائنين بعد اتباع الإجراءات المنصوص عليها في المادة (64) من هذا القانون.","title":"انتهاء المرحلة التمهيدية","memo":"⭐ تنتهي المرحلة التمهيدية بانتهاء مدة استئناف قرار اعتماد قائمة الجرد أو قائمة الدائنين أو البت في الاعتراضات عليها\n⭐ أو بصدور قرار المحكمة بالانتقال للمراحل التالية قبل البت في الاعتراضات بعد اتباع إجراءات المادة (64)","qs":[{"q":"تنتهي المرحلة التمهيدية في إجراءات الإعسار بـ:","o":["انتهاء المدة المحددة لاستئناف قرار اعتماد قائمة الجرد أو قائمة الدائنين أو البت في الاعتراضات عليها","تعيين وكيل الإعسار","انتهاء مدة تسجيل الديون","تشكيل لجنة الدائنين"],"a":0},{"q":"هل يجوز للمحكمة الانتقال من المرحلة التمهيدية قبل البت في الاعتراضات على قائمة الجرد أو قائمة الدائنين؟","o":["نعم بعد اتباع الإجراءات المنصوص عليها في المادة (64)","لا يجوز ذلك في أي حال","نعم بموافقة المدين فقط","نعم بطلب من أي دائن"],"a":0}]},{"n":"67","chapter":"الفصل السابع - مراحل إجراءات الاعسار","notes":[],"source":"أ. تعلن المحكمة انتهاء المرحلة التمهيدية وبدء مرحلة إعادة التنظيم ما لم يطلب المدين السير في إجراءات التصفية.\nب. تطبق الإجراءات المنصوص عليها في الفصل الثامن من هذا القانون على الحالات التي يتم فيها تقديم خطة إعادة تنظيم معدة مسبقا خلال مدة ثلاثين يوما من تاريخ نشر قرار إشهار الاعسار، وبعكس ذلك تخضع مرحلة إعادة التنظيم للأحكام المنصوص عليها في الفصل التاسع من هذا القانون وإذا تمت الموافقة على الخطه تنتهي المرحلة التمهيدية بعد انتهاء مدة الاعتراض على الخطة أو صدور قرار قضائي بشأنها.\nج. على الرغم مما ورد في الفقرة (أ) من هذه المادة، إذا خلص تقرير وكيل الإعسار لنتيجة مفادها أن إعادة التنظيم غير ممكنة أو إذا توقف العمل في النشاط الاقتصادي، فعلى المحكمة إصدار قرار السير في إجراءات التصفية ما لم يقدم المدين طلبا خطيا لوكيل الإعسار خلال مدة عشرة ايام من تقديم وكيل الإعسار لتقريره يتضمن نية المدين التقدم بخطه لإعادة التنظيم موافق عليها من دائنين يمثلون (%25) على الأقل من إجمالي الديون.\nد. يتولى وكيل الإعسار تقديم الطلب للمحكمة وعليها المباشرة في إجراءات إعادة التنظيم عند انتهاء المرحلة التمهيدية.","title":"الانتقال إلى إعادة التنظيم أو التصفية","memo":"⭐ تعلن المحكمة انتهاء المرحلة التمهيدية وبدء إعادة التنظيم ما لم يطلب المدين التصفية\n⭐ الخطة المعدة مسبقا المقدمة خلال 30 يوما من نشر قرار الإشهار تخضع للفصل الثامن، وإلا فللفصل التاسع\n⭐ إذا خلص تقرير الوكيل لعدم إمكانية إعادة التنظيم أو توقف النشاط: تقرر المحكمة التصفية ما لم يقدم المدين خلال 10 أيام طلبا خطيا بخطة موافق عليها من دائنين يمثلون 25% على الأقل","qs":[{"q":"الأصل بعد انتهاء المرحلة التمهيدية أن تعلن المحكمة:","o":["بدء مرحلة إعادة التنظيم ما لم يطلب المدين السير في إجراءات التصفية","بدء مرحلة التصفية ما لم يطلب الدائنون إعادة التنظيم","وقف إجراءات الإعسار","شطب الدعوى"],"a":0},{"q":"خلص تقرير وكيل الإعسار إلى أن إعادة التنظيم غير ممكنة، فما النسبة التي يجب أن يمثلها الدائنون الموافقون على خطة المدين لتفادي قرار التصفية؟","o":["(25%) على الأقل من إجمالي الديون","(10%) على الأقل من إجمالي الديون","(50%) على الأقل من إجمالي الديون","(60%) على الأقل من إجمالي الديون"],"a":0},{"q":"ما المدة التي يجب أن يقدم خلالها المدين طلبه الخطي لوكيل الإعسار بنية التقدم بخطة إعادة تنظيم بعد تقرير يفيد بعدم إمكانيتها؟","o":["عشرة أيام من تقديم وكيل الإعسار لتقريره","ثلاثون يوما من تقديم وكيل الإعسار لتقريره","خمسة أيام من تاريخ قرار المحكمة","خمسة عشر يوما من تاريخ نشر التقرير"],"a":0}]},{"n":"68","chapter":"الفصل السابع - مراحل إجراءات الاعسار","notes":[],"source":"أ. تتم إعادة تنظيم النشاط الاقتصادي من خلال خطة يتفق عليها المدين ودائنوه إما بخطة إعادة تنظيم معدة مسبقا أو باتفاق إعادة تنظيم عادي.\nب. تسري على إعادة التنظيم العادي الأحكام المتعلقة بخطة إعادة التنظيم المعدة مسبقا.","title":"طرق إعادة تنظيم النشاط الاقتصادي","memo":"⭐ تتم إعادة التنظيم بخطة يتفق عليها المدين ودائنوه: خطة إعادة تنظيم معدة مسبقا أو اتفاق إعادة تنظيم عادي\n⭐ تسري على إعادة التنظيم العادي أحكام الخطة المعدة مسبقا","qs":[{"q":"تتم إعادة تنظيم النشاط الاقتصادي وفقا لقانون الإعسار من خلال:","o":["خطة معدة مسبقا أو اتفاق إعادة تنظيم عادي","التصفية الجزئية فقط","قرار إداري من وزارة الصناعة والتجارة","حكم قضائي دون اتفاق مع الدائنين"],"a":0},{"q":"تتم إعادة تنظيم النشاط الاقتصادي من خلال خطة يتفق عليها:","o":["المدين ودائنوه","وكيل الإعسار والمحكمة","المدين ووكيل الإعسار فقط","لجنة الدائنين والمحكمة"],"a":0}]},{"n":"69","chapter":"الفصل الثامن - إعادة التنظيم وفق خطة معدة مسبقا","notes":[],"source":"أ. للمدين تفادي وضع الإعسار الوشيك من خلال اتفاق مع دائنيه يتم التوصل له خارج إجراءات المحكمة أو في المراحل المبكرة لإشهار الإعسار على ان يتم ذلك بموافقة المحكمة.\nب. للمدين أن يتوصل مع دائنيه لتسوية تأخذ شكل خطة إعادة تنظيم معدة مسبقا بهدف ضمان أعلى نسبة سداد لديونهم واستمرار النشاط الاقتصادي بحيث يتم ذلك من خلال :\n1. إرفاق مقترح خطة بطلب إشهار الإعسار مرفقا بموافقة خطيه من دائنين يمثلون ل (%25) على الأقل من إجمالي الديون .\n2. التقدم للمحكمة بمقترح للخطة خلال مدة ثلاثين يوما من تاريخ نشر قرار إشهار الإعسار.","title":"خطة إعادة التنظيم المعدة مسبقا","memo":"⭐ للمدين تفادي الإعسار الوشيك باتفاق مع دائنيه خارج المحكمة أو في المراحل المبكرة بموافقة المحكمة\n⭐ هدف الخطة: ضمان أعلى نسبة سداد واستمرار النشاط الاقتصادي\n⭐ تقدم بإرفاقها بطلب الإشهار مع موافقة خطية من دائنين يمثلون 25% على الأقل، أو خلال 30 يوما من نشر قرار الإشهار","qs":[{"q":"ما النسبة الدنيا من إجمالي الديون التي يجب أن يمثلها الدائنون الموافقون خطيا على مقترح الخطة المعدة مسبقا المرفق بطلب إشهار الإعسار؟","o":["(25%)","(10%)","(50%)","(35%)"],"a":0},{"q":"يجوز للمدين التقدم للمحكمة بمقترح خطة إعادة تنظيم معدة مسبقا خلال:","o":["ثلاثين يوما من تاريخ نشر قرار إشهار الإعسار","عشرة أيام من تاريخ نشر قرار إشهار الإعسار","ستين يوما من بدء مرحلة إعادة التنظيم","شهرين من تاريخ تعيين وكيل الإعسار"],"a":0},{"q":"يهدف الاتفاق في شكل خطة إعادة تنظيم معدة مسبقا إلى:","o":["ضمان أعلى نسبة سداد للديون واستمرار النشاط الاقتصادي","تصفية أموال المدين بسرعة","إعفاء المدين من جميع ديونه","نقل ملكية النشاط للدائنين"],"a":0}]},{"n":"70","chapter":"الفصل الثامن - إعادة التنظيم وفق خطة معدة مسبقا","notes":[],"source":"أ. يعد وكيل الاعسار تقريرا يتضمن تقييما شاملا لمقترح الخطة الذي قدمه المدين على أن يستكمل التقرير ويكون قابلا للمنافشة مع الدائنين خلال مدة ثلاثين يوما من تاريخ تقديم المقترح إذا تم إرفاقه بطلب إشهار الإعسار وخلال مدة عشرة أيام من تاريخ تقديمه للمحكمة إذا تم بعد الطلب.\nب. يجب أن يتضمن التقرير المنصوص عليه في الفقرة (أ) من هذه المادة المسائل المنصوص عليها في المادة (78) من هذا القانون.\nج. لوكيل الإعسار أن يطلب من المدين أو من الدائنين الذين وافقوا على الخطة تزويده بأي معلومات أو إيضاحات يراها مناسبة لغايات إعداد التقرير.\nد. لوكيل الإعسار أن يطلب من المحكمة تعيين خبير لتقييم الخطة على أن يكون طلبه مبررا وأن يحدد بوضوح المسائل الواردة في الخطة المطلوب الخبرة عليها.","title":"تقرير وكيل الإعسار عن الخطة المعدة مسبقا","memo":"⭐ يعد الوكيل تقريرا شاملا عن المقترح خلال 30 يوما إذا أرفق بطلب الإشهار، وخلال 10 أيام إذا قدم للمحكمة بعد الطلب\n⭐ يتضمن التقرير المسائل الواردة في المادة (78)\n⭐ له طلب معلومات من المدين أو الدائنين الموافقين، وطلب تعيين خبير بطلب مبرر يحدد المسائل","qs":[{"q":"قدم المدين مقترح خطة معدة مسبقا للمحكمة بعد تقديم طلب إشهار الإعسار، فما المدة التي يستكمل خلالها وكيل الإعسار تقريره عنها؟","o":["عشرة أيام من تاريخ تقديمه للمحكمة","ثلاثون يوما من تاريخ تقديمه","خمسة عشر يوما من تاريخ تبلغه","شهران من تاريخ تعيينه"],"a":0},{"q":"إذا أرفق مقترح الخطة المعدة مسبقا بطلب إشهار الإعسار، يستكمل وكيل الإعسار تقريره خلال:","o":["ثلاثين يوما من تاريخ تقديم المقترح","عشرة أيام من تاريخ تقديم المقترح","خمسة أيام من تاريخ تعيينه","ستين يوما من تاريخ تقديم المقترح"],"a":0},{"q":"ما الذي يشترط في طلب وكيل الإعسار من المحكمة تعيين خبير لتقييم الخطة المعدة مسبقا؟","o":["أن يكون الطلب مبررا وأن يحدد بوضوح المسائل المطلوب الخبرة عليها","موافقة المدين على الطلب","موافقة لجنة الدائنين بالأغلبية","أن يتحمل وكيل الإعسار أتعاب الخبير"],"a":0}]},{"n":"71","chapter":"الفصل الثامن - إعادة التنظيم وفق خطة معدة مسبقا","notes":[],"source":"أ. للدائنين الاطلاع على خطة إعادة التنظيم المعدة مسبقا في المكان الذي يحدده وكيل الإعسار.\nب. لا يجوز لوكيل الإعسار آن يسمح لأي جهة باستثناء الدائنين المدرجين في قائمة الدائنين و أي شخص يظهر أن له دينا صحيحا على المدين الاطلاع على خطة إعادة التنظيم المعدة مسبقا، وفي الأحوال جميعها يجب التحقق من هوية الشخص المزمع اطلاعه على الخطه وتوقيعه على تعهد بالمحافظة على سريتها .","title":"الاطلاع على الخطة المعدة مسبقا","memo":"⭐ للدائنين الاطلاع على الخطة في المكان الذي يحدده وكيل الإعسار\n⭐ لا يجوز اطلاع غير الدائنين المدرجين ومن يظهر أن له دينا صحيحا، ويجب التحقق من الهوية والتوقيع على تعهد بالسرية","qs":[{"q":"يكون اطلاع الدائنين على خطة إعادة التنظيم المعدة مسبقا في المكان الذي يحدده:","o":["وكيل الإعسار","المحكمة","المدين","لجنة الدائنين"],"a":0},{"q":"ما الشرط الواجب في جميع الأحوال قبل اطلاع أي شخص على خطة إعادة التنظيم المعدة مسبقا؟","o":["التحقق من هويته وتوقيعه على تعهد بالمحافظة على سريتها","دفع رسم اطلاع","الحصول على إذن من المدين","تقديم كفالة مالية"],"a":0}]},{"n":"72","chapter":"الفصل الثامن - إعادة التنظيم وفق خطة معدة مسبقا","notes":[],"source":"أ. للدائنين التصويت على خطة إعادة التنظيم المعدة مسبقا ابتداء من تاريخ انتهاء المدة المحددة للتقدم بمطالباتهم وحتى انتهاء مدة الطعن بقائمة الدائنين.\nب. يتم التصويت بوثيقة خطية تسلم لوكيل الإعسار على عنوانه المحدد أو من خلال المحكمه ويتم التصويت وفقا لأحكام التصويت على خطة اعادة التنظيم العادية المنصوص عليها في الفصل التاسع من هذا القانون.","title":"التصويت على الخطة المعدة مسبقا","memo":"⭐ التصويت من تاريخ انتهاء مدة تقديم المطالبات وحتى انتهاء مدة الطعن بقائمة الدائنين\n⭐ بوثيقة خطية تسلم لوكيل الإعسار على عنوانه أو من خلال المحكمة، وفق أحكام التصويت في الفصل التاسع","qs":[{"q":"متى يبدأ تصويت الدائنين على خطة إعادة التنظيم المعدة مسبقا؟","o":["من تاريخ انتهاء المدة المحددة للتقدم بمطالباتهم","من تاريخ نشر قرار إشهار الإعسار","من تاريخ تعيين وكيل الإعسار","من تاريخ بدء مرحلة إعادة التنظيم"],"a":0},{"q":"كيف يتم التصويت على خطة إعادة التنظيم المعدة مسبقا؟","o":["بوثيقة خطية تسلم لوكيل الإعسار على عنوانه أو من خلال المحكمة","شفاهة في اجتماع الهيئة العامة للدائنين فقط","إلكترونيا عبر سجل الإعسار حصرا","برفع الأيدي أمام قاضي المحكمة"],"a":0}]},{"n":"73","chapter":"الفصل الثامن - إعادة التنظيم وفق خطة معدة مسبقا","notes":[],"source":"أ. تتم الموافقة على خطة إعادة التنظيم المعدة مسبقا بالأغلبية المنصوص عليها في الفصل التاسع من هذا القانون.\nب. يقوم وكيل الإعسار بفرز الأصوات خلال مدة خمسة أيام من انتهاء مدة التصويت على الخطة فاذا تمت الموافقة عليها بالأغلبية المنصوص عليها في هذا القانون، يتولى وكيل الإعسار إشعار المحكمة بذلك وإيداعها لديها.\nج. تطبق شروط وإجراءات الاعتراض على خطة إعادة التنظيم العادية المنصوص عليها في الفصل التاسع من هذا القانون على الاعتراض على خطة إعادة التنظيم المعدة مسبقا.","title":"الموافقة على الخطة المعدة مسبقا وفرز الأصوات","memo":"⭐ الموافقة بالأغلبية المنصوص عليها في الفصل التاسع\n⭐ يفرز الوكيل الأصوات خلال 5 أيام من انتهاء التصويت ويشعر المحكمة ويودع الخطة لديها إذا ووفق عليها\n⭐ يطبق على الاعتراض شروط وإجراءات الاعتراض على الخطة العادية","qs":[{"q":"ما المدة التي يقوم خلالها وكيل الإعسار بفرز الأصوات على خطة إعادة التنظيم المعدة مسبقا؟","o":["خمسة أيام من انتهاء مدة التصويت","عشرة أيام من انتهاء مدة التصويت","ثلاثة أيام من انتهاء مدة التصويت","خمسة عشر يوما من انتهاء مدة التصويت"],"a":0},{"q":"تتم الموافقة على خطة إعادة التنظيم المعدة مسبقا بـ:","o":["الأغلبية المنصوص عليها في الفصل التاسع من القانون","إجماع الدائنين","موافقة دائنين يمثلون (25%) من الديون","موافقة لجنة الدائنين"],"a":0}]},{"n":"74","chapter":"الفصل الثامن - إعادة التنظيم وفق خطة معدة مسبقا","notes":[],"source":"أ. إذا تمت الموافقة على خطة إعادة التنظيم المعدة مسبقا دون اعتراض أو تم رد الاعتراضات المقدمة عليها تعلن المحكمة الموافقة على الخطة وتقرر انتهاء المرحلة التمهيدية وتعليق إجراءات الإعسار.\nب. يكون للموافقة على خطة إعادة التنظيم المعدة مسبقا الآثار ذاتها التي تترتب على الموافقة على خطة إعادة التنظيم العادية.","title":"آثار الموافقة على الخطة المعدة مسبقا","memo":"⭐ إذا ووفق على الخطة دون اعتراض أو ردت الاعتراضات: تعلن المحكمة الموافقة وتقرر انتهاء المرحلة التمهيدية وتعليق إجراءات الإعسار\n⭐ للموافقة عليها الآثار ذاتها للموافقة على الخطة العادية","qs":[{"q":"إذا تمت الموافقة على خطة إعادة التنظيم المعدة مسبقا دون اعتراض، تقرر المحكمة:","o":["انتهاء المرحلة التمهيدية وتعليق إجراءات الإعسار","بدء إجراءات التصفية","بدء إجراءات إعادة التنظيم العادية","عقد اجتماع للهيئة العامة للدائنين"],"a":0},{"q":"يكون للموافقة على خطة إعادة التنظيم المعدة مسبقا:","o":["الآثار ذاتها التي تترتب على الموافقة على خطة إعادة التنظيم العادية","آثار أضعف من الخطة العادية لعدم عقد اجتماع","أثر ملزم للمدين فقط","أثر ملزم للدائنين الموافقين عليها فقط"],"a":0}]},{"n":"75","chapter":"الفصل الثامن - إعادة التنظيم وفق خطة معدة مسبقا","notes":[],"source":"إذا لم تتم الموافقة على خطة إعادة التنظيم المعدة مسبقا بالأغلبية المنصوص عليها في هذا القانون يتولى وكيل الإعسار إشعار المحكمة بذلك و تعلن المحكمة انتهاء المرحلة التمهيدية وبدء إجراءات إعادة التنظيم العادية ما لم يقدم المدين طلبا لبدء التصفية.","title":"عدم الموافقة على الخطة المعدة مسبقا","memo":"⭐ إذا لم تحصل الخطة على الأغلبية: يشعر الوكيل المحكمة، وتعلن انتهاء المرحلة التمهيدية وبدء إعادة التنظيم العادية ما لم يطلب المدين التصفية","qs":[{"q":"إذا لم تتم الموافقة على خطة إعادة التنظيم المعدة مسبقا بالأغلبية المطلوبة، تعلن المحكمة:","o":["انتهاء المرحلة التمهيدية وبدء إجراءات إعادة التنظيم العادية ما لم يطلب المدين بدء التصفية","بدء التصفية حكما","إعادة التصويت على الخطة خلال عشرة أيام","رد طلب إشهار الإعسار"],"a":0},{"q":"من يتولى إشعار المحكمة بعدم الموافقة على خطة إعادة التنظيم المعدة مسبقا؟","o":["وكيل الإعسار","المدين","لجنة الدائنين","أكبر الدائنين"],"a":0}]},{"n":"76","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"لوكيل الإعسار أو للمدين أو لدائنين يمثلون (%10) على الأقل من إجمالي الديون تقديم خطة لإعادة التنظيم للمحكمة خلال مدة ثلاثين يوما من تاريخ بدء مرحلة إعادة التنظيم وللمدين ارفاقها بطلب إشهار الإعسار .","title":"تقديم خطة إعادة التنظيم العادية","memo":"⭐ يقدم الخطة: وكيل الإعسار أو المدين أو دائنون يمثلون 10% على الأقل من إجمالي الديون\n⭐ خلال 30 يوما من بدء مرحلة إعادة التنظيم، وللمدين إرفاقها بطلب الإشهار","qs":[{"q":"أي من الجهات التالية لا يملك تقديم خطة إعادة التنظيم العادية للمحكمة؟","o":["دائنون يمثلون (5%) من إجمالي الديون","وكيل الإعسار","المدين","دائنون يمثلون (10%) من إجمالي الديون"],"a":0},{"q":"تقدم خطة إعادة التنظيم العادية للمحكمة خلال مدة:","o":["ثلاثين يوما من تاريخ بدء مرحلة إعادة التنظيم","عشرة أيام من تاريخ بدء مرحلة إعادة التنظيم","ستين يوما من نشر قرار الإشهار","خمسة عشر يوما من انتهاء المرحلة التمهيدية"],"a":0}]},{"n":"77","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. تسلم خطة إعادة التنظيم للمحكمة ولوكيل الإعسار على عنوانه.\nب. تتولى المحكمة تبليغ الخطة فور استلامها لكل ممن يلي :\n1. لجنة الدائنين\n2. ممثلي العاملين لدى المدين.\n3. المدين إذا كانت الخطة مقدمة من وكيل الإعسار.\n4. وكيل الإعسار إذا كانت الخطة مقدمة من المدين أو الدائنين.\nج. تمنح المحكمة الجهات الواردة في الفقرة (ب) من هذه المادة مهله لا تتجاوز عشرة أيام من تاريخ تبلغهم الخطة لإبداء ملاحظاتهم عليها.","title":"تسليم خطة إعادة التنظيم وتبليغها","memo":"⭐ تسلم الخطة للمحكمة ولوكيل الإعسار على عنوانه\n⭐ تبلغ المحكمة فورا: لجنة الدائنين، ممثلي العاملين، المدين (إن قدمها الوكيل)، الوكيل (إن قدمها المدين أو الدائنون)\n⭐ مهلة الملاحظات لا تتجاوز 10 أيام من التبلغ","qs":[{"q":"ما المهلة التي تمنحها المحكمة للجهات المبلغة بخطة إعادة التنظيم لإبداء ملاحظاتها؟","o":["مهلة لا تتجاوز عشرة أيام من تاريخ تبلغهم الخطة","مهلة لا تتجاوز خمسة أيام","مهلة لا تتجاوز خمسة عشر يوما","مهلة لا تتجاوز ثلاثين يوما"],"a":0},{"q":"قدم المدين خطة لإعادة التنظيم، فأي من الجهات التالية لا يلزم تبليغها الخطة وفقا للمادة (77)؟","o":["المدين","لجنة الدائنين","ممثلو العاملين لدى المدين","وكيل الإعسار"],"a":0},{"q":"أي من الجهات التالية تبلغ خطة إعادة التنظيم في جميع الأحوال أيا كان مقدمها؟","o":["ممثلو العاملين لدى المدين","المدين","وكيل الإعسار","الجهة المسؤولة عن ترخيص وكلاء الإعسار"],"a":0}]},{"n":"78","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. على وكيل الإعسار أن يقدم تقريرا متكاملا للمحكمة حول خطة إعادة التنظيم خلال مدة خمسة عشر يوما من تاريخ تبلغها على أن يتضمن التقرير رأيه حول مدى قابليه النشاط الاقتصادي للاستمرار إذا تم تنفيذ الخطة وإمكانية تنفيذها بشكل فاعل.\nب. مع مراعاة أحكام الفقرة (أ) من هذه المادة، يجب أن يتضمن تقرير وكيل الإعسار ما يلي:\n1. أن الخطة تتضمن المعلومات المنصوص عليها فى هذا القانون و المعلومات اللازمة لتمكين المحكمه والدائنين من اتخاذ القرار المناسب بشأنها.\n2. مدى معقولية الفرضيات التي بنيت عليها خطوات إعادة التنظيم وتوقعات التدفقات النقديه التي تضمنتها الخطة.\n3. رأيه فيما إذا كان مبلغ الديون المتوقع استيفاؤه من الدائنين من خلال الخطة أكبر من المبلغ المتوقع استيفاؤه في حال تصفية أموال المدين.\n4. رأيه فيما إذا كانت الخطة المقدمة تحسن إمكانية استيفاء ادائنين لديونهم.\n5. رأيه فيما إذا كان تنفيذ الخطة لن يؤدي لاستيفاء أي من الدائنين أو فئة منهم مبالغ تقل عن تلك التي سوف يستوفونها في حال تصفية أموال المدين.\n6. رأيه فيما إذا كان يجوز الطعن بأي مبالغ مستحقة للأشخاص ذوي صلة بالمدين.\n7. أثر عدم قدرة المدين على متابعة أي إجراءات قضائية أو إنجاز أي عمل منصوص عليه في الخطة على تنفيذها.","title":"تقرير وكيل الإعسار حول خطة إعادة التنظيم","memo":"⭐ يقدم الوكيل تقريرا متكاملا خلال 15 يوما من تبلغه الخطة، متضمنا رأيه في قابلية النشاط للاستمرار وإمكانية تنفيذ الخطة\n⭐ يتضمن: معقولية الفرضيات والتدفقات النقدية، مقارنة ما يستوفيه الدائنون بالخطة مع التصفية، الطعن بمبالغ ذوي الصلة، أثر عجز المدين عن الإجراءات القضائية","qs":[{"q":"ما المدة التي يقدم خلالها وكيل الإعسار تقريره المتكامل حول خطة إعادة التنظيم العادية؟","o":["خمسة عشر يوما من تاريخ تبلغها","عشرة أيام من تاريخ تبلغها","ثلاثون يوما من تاريخ تبلغها","شهران من تاريخ تبلغها"],"a":0},{"q":"أي مما يلي لم يرد ضمن ما يجب أن يتضمنه تقرير وكيل الإعسار حول خطة إعادة التنظيم؟","o":["رأيه في تعديل أتعابه بناء على الخطة","مدى معقولية الفرضيات وتوقعات التدفقات النقدية","رأيه في ما إذا كان المبلغ المتوقع استيفاؤه بالخطة أكبر منه في حال التصفية","رأيه في ما إذا كان يجوز الطعن بأي مبالغ مستحقة للأشخاص ذوي الصلة بالمدين"],"a":0},{"q":"يقارن وكيل الإعسار في تقريره بين ما يستوفيه الدائنون من خلال الخطة وما يستوفونه في حال:","o":["تصفية أموال المدين","إعادة جدولة الديون","بيع النشاط بصفته عاملا","رفض طلب إشهار الإعسار"],"a":0}]},{"n":"79","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. يجب أن تتضمن خطة إعادة التنظيم اما إعادة هيكلة النشاط الاقتصادي أو اعادة هيكلة الديون مع مذكرة بمبررات اللجوء لأي منهما .\nب. يجب أن يتضمن الجزء المتعلق بإعادة هيكلة الديون في الخطة إما تخفيض الديون أو إعادة جدولتها أو أي طريقة أخرى بما في ذلك رسملة الديون ولا يجوز أن تتجاوز مدة تأجيل الديون عشر سنوات.\nج. يجب أن يتضمن الجزء المتعلق بإعادة هيكلة النشاط الاقتصادي في خطة إعادة التنظيم أي نوع من الإجراءات بما في ذلك الاندماج وتجزئة الأسهم أو غيرها من الإجراءات التي تؤدي لإعادة هيكلة النشاط الاقتصاد وذلك وفقا للأحكام المنصوص عليها في التشريعت النافذة بستثناء الأحكام المتعلقه بحق الدائنين في الاعتراض على هذه الاجراءات بحيث تطبق الاحكام المتعلقه بالتصويت المنصوص عليها في هذا القانون دون غيرها لغايات الموافقة على خطة إعادة التنظيم.\nد. يجوز أن تتضمن خطة إعادة التنظيم بيع وحدات النشاط الاقتصادي بصفتها عاملة ومنتجه أو بيع أي جزء منها أو التصرف بأسهم أو حصص الشركات التابعه.\nهـ. يجوز أن تطرح الخطة بدائل تختارها كل فئة من فئات الدائنين، وفي هذه الحالة يجب أن يحدد المقترح البديل الذي يطبق على الدائنين الذين لم يختاروا أيا من البدائل.\nو. يجب أن تتضمن خطة إعادة التنظيم المعلومات اللازمة لتمكين الدائنين الذين يملكون حق التصويت عليها من ممارسة ذلك الحق، وعلى النحو التالي:\n1. وصفا عاما لأعمال المدين والظروف التي أدت لإعساره.\n2. وصفا مفصلا لإجراءات تنفيذ خطة إعادة التنظيم.\n3. قائمة مفصلة بالدائنين مصنفين حسب فئاتهم.\n4. المبالغ والأموال المنوي استخدامها لغايات سداد ديون كل فئة من الدائنين كليا أو جزئيا و الأموال التي سيتم الاحتفاظ بها لسداد الديون المعترض عليها، وإجراءات تسوية هذه الديون والوقت المتوقع لذلك.\n5. بيان طريقة بيع الأموال إن وجدت إضافة لقائمة الأموال التي سيتم بيعها سواء أكانت مثقلة بحقوق ضمان أم لا، وكيفيه استخدام عوائد البيع.\n6. تاريخ بدء تنفيذ الخطة والمدد المطلوبة لذلك .\n7. بيانا بأن اعتماد الخطة سيؤدي لإعادة تحديد حقوق الدائنين بما في ذلك الحالات التي لن يتم فيها تنفيذ الخطه بشكل كامل أو تعليق تنفيذها والتفاصيل المتعلقة بطريقة إعادة تحديد هذه الحقوق.\n8. قائمة بأسماء أعضاء الهيئة التي تتولى إدارة أعمال المدين والبدلات التي يتقاضاها كل منهم، إن وجدت.\n9. تفصيلا لطريقة سداد الديون بما في ذلك بيع الأموال أو بيع النشاط الاقتصادي كليا أو جزئيا أو الحصول على قروض من الغير أو الاكتتاب برأس المال أو تخفيض الديون أو شطبها أو إعادة جدولتها أو رسملتها أو أي طريقة اخرى تجيزها التشريعات النافذة إضافة للمدة التي يستغرقها هذا السداد .\n10. اسم الشخص المرشح لمراقبة تنفيذ الخطة، إن وجد، ومسؤولياته تجاه الدائنين.\n11. تقريرا حول التوقعات المالية بما في ذلك حساب الأرباح والخسائر والميزانية والتدفقات النقدية خلال فترة تنفيد الخطة.\n12. تقديرا لعوائد بيع الأموال في التصفية والكلفة الإجمالية لهذه التصفية فيما لو تمت التصفية في الوقت الذي تم فيه تقديم الخطه.","title":"مضمون خطة إعادة التنظيم","memo":"⭐ تتضمن الخطة إعادة هيكلة النشاط الاقتصادي أو إعادة هيكلة الديون مع مذكرة بالمبررات\n⭐ هيكلة الديون: تخفيض أو جدولة أو رسملة، ولا يجوز أن تتجاوز مدة تأجيل الديون 10 سنوات\n⭐ يجوز بيع وحدات النشاط بصفتها عاملة، وطرح بدائل لكل فئة مع تحديد البديل لمن لم يختر\n⭐ تتضمن 12 بندا من المعلومات منها: قائمة الدائنين بفئاتهم، التوقعات المالية، تقدير عوائد التصفية وكلفتها","qs":[{"q":"ما الحد الأقصى لمدة تأجيل الديون في خطة إعادة التنظيم؟","o":["عشر سنوات","خمس سنوات","سبع سنوات","خمس عشرة سنة"],"a":0},{"q":"طرحت خطة إعادة التنظيم بدائل تختارها فئات الدائنين، فما الذي يجب أن يحدده المقترح في هذه الحالة؟","o":["البديل الذي يطبق على الدائنين الذين لم يختاروا أيا من البدائل","موافقة المحكمة المسبقة على كل بديل","استبعاد الدائنين الذين لم يختاروا من التصويت","تطبيق التصفية على من لم يختر بديلا"],"a":0},{"q":"بالنسبة لإجراءات إعادة هيكلة النشاط الاقتصادي في الخطة، أي من الأحكام التالية لا يطبق؟","o":["أحكام التشريعات النافذة المتعلقة بحق الدائنين في الاعتراض على هذه الإجراءات","أحكام التصويت المنصوص عليها في قانون الإعسار","أحكام التشريعات النافذة المتعلقة بالاندماج","أحكام التشريعات النافذة المتعلقة بتجزئة الأسهم"],"a":0},{"q":"أي مما يلي يجب أن تتضمنه خطة إعادة التنظيم ضمن المعلومات اللازمة للدائنين؟","o":["تقديرا لعوائد بيع الأموال في التصفية وكلفتها الإجمالية","تقرير مدقق الحسابات الخارجي عن آخر خمس سنوات","رأي لجنة الدائنين في الخطة","موافقة البنك المركزي على الخطة"],"a":0}]},{"n":"80","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. لغايات التصويت على خطة إعادة التنظيم، يقسم الدائنون إلى فئات مختلفة تبعا لمرتبة ديونهم وذلك وفقا لأحكام المادتين (38) و(40) من هذا القانون ويتم تشكيل فئات أخرى ضمن الفئة ذاتها من الدائنين أصحاب الديون الممتازة.\nب. للجهة التي تعد خطة إعادة التنظيم أن تقترح تقسيم الدائنين لفئات ضمن الفئة الواحدة لأسباب أخرى خلاف قيمة الدين خصوصا فيما يتعلق بالدائنين بديون غير مضمونة.","title":"تقسيم الدائنين إلى فئات","memo":"⭐ يقسم الدائنون لغايات التصويت إلى فئات تبعا لمرتبة ديونهم وفق المادتين (38) و(40)، وتشكل فئات أخرى ضمن فئة الديون الممتازة\n⭐ لمعد الخطة اقتراح تقسيم الفئة الواحدة لأسباب خلاف قيمة الدين خصوصا للدائنين بديون غير مضمونة","qs":[{"q":"لغايات التصويت على خطة إعادة التنظيم، يقسم الدائنون إلى فئات تبعا لـ:","o":["مرتبة ديونهم","تاريخ تسجيل ديونهم","جنسيتهم","تاريخ استحقاق ديونهم"],"a":0},{"q":"يجوز للجهة التي تعد خطة إعادة التنظيم أن تقترح تقسيم الدائنين لفئات ضمن الفئة الواحدة لأسباب خلاف قيمة الدين، خصوصا فيما يتعلق بالدائنين:","o":["بديون غير مضمونة","بديون مضمونة","الأدنى في مرتبة الأولوية","بديون الخزينة"],"a":0}]},{"n":"81","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. تتساوى حقوق الأطراف كافة من فئة الدائنين ذاتها ولا يجوز معاملة أي دائن من فئة معينة من الدائنين معاملة مختلفة إلا بموافقة الدائنين من الفئة ذاتها كافة ، وفي هذه الحالة ترفق بخطة إعادة التنظيم وثيقة تثبت موافقة كل دائن من الفئة.\nب. لا يعتد بأي اتفاق بين وكيل الإعسار أو المدين أو أي أشخاص آخرين لمنح مزايا مخالفة لخطة إعادة التنظيم.","title":"المساواة بين دائني الفئة الواحدة","memo":"⭐ تتساوى حقوق دائني الفئة الواحدة، ولا تجوز معاملة مختلفة إلا بموافقة جميع دائني الفئة مع إرفاق وثيقة بموافقة كل دائن\n⭐ لا يعتد بأي اتفاق لمنح مزايا مخالفة للخطة","qs":[{"q":"تجوز معاملة دائن من فئة معينة معاملة مختلفة عن باقي أفراد فئته بشرط:","o":["موافقة الدائنين من الفئة ذاتها كافة","موافقة أغلبية دائني الفئة","موافقة المحكمة","موافقة وكيل الإعسار"],"a":0},{"q":"اتفق المدين مع أحد الدائنين على منحه ميزة مخالفة لخطة إعادة التنظيم، فما حكم هذا الاتفاق؟","o":["لا يعتد به","صحيح إذا وافق عليه وكيل الإعسار","صحيح إذا كان الدائن صاحب دين ممتاز","صحيح بعد إشهاره في سجل الإعسار"],"a":0}]},{"n":"82","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. لا يجوز أن تمس خطة إعادة التنظيم حقوق الدائنين أصحاب الحقوق المضمونة .\nب. اذا تضمنت الخطة أي تغيير أو تقليل من حقوق الدائنين أصحاب الحقوق المضمونة يجب أن توضح طريقه ومقدار تغيير الحقوق أو تقليلها ومدة التأخير الحاصل في تنفيذ تحصيل الديون المضمونة.\nج. لا تعتبر الإجراءات المنصوص عليها في الفقرة (ب) من هذه المادة ملزمة للمدينين أصحاب الحقوق المضمونة مالم يوافقوا عليها جميعهم.\nد. للدائنين أصحاب الحقوق المضمونة التصويت على الخطة اذا كانت تؤثر على حقوقهم وتعتبر الخطة التي صوتوا عليها ملزمة لهم إذا تمت الموافقة عليها.","title":"حقوق الدائنين أصحاب الحقوق المضمونة في الخطة","memo":"⭐ لا يجوز أن تمس الخطة حقوق أصحاب الحقوق المضمونة\n⭐ إذا تضمنت تغييرا أو تقليلا لحقوقهم وجب بيان الطريقة والمقدار ومدة التأخير، ولا تلزمهم إلا بموافقتهم جميعا\n⭐ لهم التصويت إذا أثرت على حقوقهم وتلزمهم الخطة التي صوتوا عليها إذا ووفق عليها","qs":[{"q":"الأصل في خطة إعادة التنظيم بالنسبة لحقوق الدائنين أصحاب الحقوق المضمونة أنها:","o":["لا يجوز أن تمسها","تخفض بنسبة لا تتجاوز (50%)","تؤجل لمدة لا تتجاوز عشر سنوات","تعامل كديون غير مضمونة"],"a":0},{"q":"تضمنت خطة إعادة تنظيم تقليلا لحقوق الدائنين أصحاب الحقوق المضمونة، فمتى يكون ذلك ملزما لهم؟","o":["إذا وافقوا عليها جميعهم","إذا وافقت أغلبيتهم","إذا وافقت المحكمة","إذا وافقت لجنة الدائنين"],"a":0},{"q":"إذا تضمنت الخطة تغييرا في حقوق الدائنين أصحاب الحقوق المضمونة، فأي مما يلي لا يلزم توضيحه في الخطة؟","o":["أسماء الكفلاء الشخصيين للدين","طريقة تغيير الحقوق","مقدار تغيير الحقوق أو تقليلها","مدة التأخير في تحصيل الديون المضمونة"],"a":0}]},{"n":"83","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. على الرغم مما ورد في الفقرة (ب) من هذه المادة تعتبر الإجراءات التي تتضمنها خطة إعادة التنظيم ملزمة للدائنين أصحاب الديون الممتازة إذا وافقوا عليها.\nب. لا تسري خطة إعادة التنظيم على الدائنين أصحاب الديون الممتازة إلا إذا حصلت فئتهم على أغلبية الأصوات وفقا لأحكام المادة (90) من هذا القانون أو إذا قررت المحكمة ذلك وفقا لأحكام المادة (91) من هذا القانون.","title":"سريان الخطة على أصحاب الديون الممتازة","memo":"⭐ تلزم إجراءات الخطة أصحاب الديون الممتازة إذا وافقوا عليها\n⭐ لا تسري عليهم إلا إذا حصلت فئتهم على الأغلبية وفق المادة (90) أو قررت المحكمة ذلك وفق المادة (91)","qs":[{"q":"لا تسري خطة إعادة التنظيم على الدائنين أصحاب الديون الممتازة إلا إذا:","o":["حصلت فئتهم على أغلبية الأصوات وفق المادة (90) أو قررت المحكمة ذلك وفق المادة (91)","وافق عليها كل دائن منهم منفردا","وافقت عليها لجنة الدائنين","أوصى بها وكيل الإعسار"],"a":0},{"q":"تعتبر الإجراءات التي تتضمنها خطة إعادة التنظيم ملزمة للدائنين أصحاب الديون الممتازة:","o":["إذا وافقوا عليها","في جميع الأحوال","إذا لم تتجاوز مدة التأجيل خمس سنوات","إذا وافق عليها الدائنون المضمونون"],"a":0}]},{"n":"84","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"يكون للدائنين أصحاب الحقوق المضمونة إلحق في التصويت وفقا لكامل مبالغ ديونهم التي تضمنتها القائمه النهائيه للدائنين.","title":"تصويت الدائنين أصحاب الحقوق المضمونة","memo":"⭐ يصوت أصحاب الحقوق المضمونة وفقا لكامل مبالغ ديونهم في القائمة النهائية للدائنين","qs":[{"q":"يصوت الدائنون أصحاب الحقوق المضمونة على خطة إعادة التنظيم وفقا لـ:","o":["كامل مبالغ ديونهم التي تضمنتها القائمة النهائية للدائنين","الجزء غير المغطى بالضمان فقط","نصف مبالغ ديونهم","قيمة الضمانة المقدمة"],"a":0}]},{"n":"85","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. لا يحق للدائنين الأدنى في مرتبة الأولوية، والشركاء والمساهمين في المدين ومن في حكمهم إذا كان شخصا اعتباريا التصويت باستثناء الشركاء الدائنين الذين لا يندرجون تحت تعريف الشخص ذي الصلة بالمدين.\nب. إذا تضمنت خطة إعادة التنظيم خصما من ديون الدائنين أصحاب الديون الممتازة أو غير المضمونة فتعتبر الديون الأدنى في مرتبة الأولوية مشطوبة أما إذا تضمنت الخطة تأجيل ديون أصحاب الديون الممتازة أو غير المضمونة فيتم تسديد الديون الأدنى في مرتبة الأولوية بالطريقة التي تضمنتها الخطة بعد سداد الديون الممتازة وغير المضمونة بالكامل.","title":"الدائنون الأدنى في مرتبة الأولوية والشركاء","memo":"⭐ لا يحق التصويت للدائنين الأدنى في مرتبة الأولوية والشركاء والمساهمين، باستثناء الشركاء الدائنين غير ذوي الصلة بالمدين\n⭐ إذا تضمنت الخطة خصما من الديون الممتازة أو غير المضمونة تعتبر الديون الأدنى مشطوبة\n⭐ إذا تضمنت تأجيلها تسدد الديون الأدنى بعد سداد الممتازة وغير المضمونة بالكامل","qs":[{"q":"أي من الأشخاص التالية يحق له التصويت على خطة إعادة التنظيم؟","o":["الشريك الدائن الذي لا يندرج تحت تعريف الشخص ذي الصلة بالمدين","الدائن الأدنى في مرتبة الأولوية","المساهم في الشركة المدينة بصفته مساهما","الشريك ذو الصلة بالمدين"],"a":0},{"q":"تضمنت خطة إعادة التنظيم خصما من ديون الدائنين أصحاب الديون غير المضمونة، فما حكم الديون الأدنى في مرتبة الأولوية؟","o":["تعتبر مشطوبة","تسدد بالكامل قبل غير المضمونة","تخصم بالنسبة ذاتها","تؤجل لمدة عشر سنوات"],"a":0},{"q":"إذا تضمنت الخطة تأجيل ديون أصحاب الديون الممتازة وغير المضمونة، فإن الديون الأدنى في مرتبة الأولوية:","o":["تسدد بالطريقة التي تضمنتها الخطة بعد سداد الديون الممتازة وغير المضمونة بالكامل","تعتبر مشطوبة","تسدد بالتزامن معها","تسدد قبلها"],"a":0}]},{"n":"86","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. يعقد اجتماع الدائنين في اليوم الستين لبدء مرحلة إعادة التنظيم إلا إذا حددت المحكمة في قرار إشهار الإعسار تاريخا آخر لانعقاده لأسباب مبررة على أن لا يتجاوز تاريخ الاجتماع خمسة وسبعين يوما من تاريخ بدء مرحلة إعادة التنظيم.\nب. يتولى وكيل الإعسار اعلان تاريخ الاجتماع ووقته ومكانه وجدول أعماله خلال مدة خمسه عشر يوما من بدء مرحلة إعادة التنظيم و يتم إشهار وقائع الاجتماع في الجريدة الرسمية وسجل الإعسار وبأي طريقه أخرى مناسبة.\nج. يترأس قاضي المحكمة اجتماع الدائنين ويتولى وكيل الإعسار أمانة سر الاجتماع ولقاضي المحكمة أن ينيب عنه وكيل الإعسار في ترؤس الاجتماع وفي هذه الحالة يتولى أمانة السر موظف المحكمة الذي يعينه رئيس الاجتماع .\nد. يكون نصاب اجتماع الهيئة العامة للدائنين قانونيا في أي من الحالتين التاليتين:\n1. حضور دائنين يمثلون أصالة أو وكالة (%50) على الأقل من إجمالي الديون.\n2. حضور دائنين يمثلون أصالة أو وكالة (%50) على الأقل من إجمالي الديون محسوما منها الديون المضمونة والديون الادنى في مرتبة الأولوية.\nهـ. إذا لم يكتمل النصاب خلال ساعة من الوقت المحدد لبدء الاجتماع فيؤجل الاجتماع الى موعد آخر خلال مدة خمسة أيام من التاريخ المحدد للاجتماع الأول ويعاد الإعلان عنه وفقا لأحكام الفقرة (ب) من هذه المادة ويكون النصاب في الاجتماع الثاني قانونيا بحضور دائنين يمثلون أصالة أو وكالة (%35) على الأقل من إجمالي الديون محسوما منها الديون المضمونة والديون الأدنى في مرتبة الأولوية واذا لم يتوافر هذا النصاب يلغى الاجتماع.","title":"اجتماع الدائنين ونصابه","memo":"⭐ يعقد الاجتماع في اليوم 60 لبدء إعادة التنظيم، وللمحكمة تحديد تاريخ آخر لأسباب مبررة لا يتجاوز 75 يوما\n⭐ يعلن الوكيل الاجتماع خلال 15 يوما من بدء المرحلة، وينشر في الجريدة الرسمية وسجل الإعسار\n⭐ يترأسه قاضي المحكمة ويتولى الوكيل أمانة السر (وللقاضي إنابة الوكيل في الرئاسة)\n⭐ النصاب 50% من إجمالي الديون (أو منها محسوما المضمونة والأدنى)، وإلا يؤجل خلال 5 أيام والنصاب الثاني 35% وإلا يلغى","qs":[{"q":"في أي يوم يعقد اجتماع الدائنين كأصل عام؟","o":["اليوم الستين لبدء مرحلة إعادة التنظيم","اليوم الثلاثين لبدء مرحلة إعادة التنظيم","اليوم الخامس والسبعين لبدء مرحلة إعادة التنظيم","اليوم الخامس عشر لبدء مرحلة إعادة التنظيم"],"a":0},{"q":"ما النصاب القانوني للاجتماع الثاني للهيئة العامة للدائنين بعد تأجيل الاجتماع الأول لعدم اكتمال النصاب؟","o":["(35%) على الأقل من إجمالي الديون محسوما منها الديون المضمونة والأدنى في مرتبة الأولوية","(50%) على الأقل من إجمالي الديون","(25%) على الأقل من إجمالي الديون","أي عدد من الحاضرين"],"a":0},{"q":"من يترأس اجتماع الدائنين كأصل عام؟","o":["قاضي المحكمة","وكيل الإعسار","رئيس لجنة الدائنين","أكبر الدائنين قيمة"],"a":0},{"q":"لم يكتمل نصاب اجتماع الدائنين خلال ساعة من الموعد المحدد، فإن الاجتماع:","o":["يؤجل إلى موعد آخر خلال خمسة أيام من التاريخ المحدد للاجتماع الأول","يلغى نهائيا","يعقد بمن حضر","يؤجل إلى موعد آخر خلال خمسة عشر يوما"],"a":0}]},{"n":"87","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. على وكيل الإعسار والمدين حضور الاجتماع، واذا تغيب وكيل الإعسار عن الحضور بدون عذر تقبله المحكمة فلها أن تطبق عليه أحكام المادة (54) من هذا القانون .\nب. يقتصر الحق في حضور الاجتماع والتصويت فيه على الدائنين المدرجين في قائمة الدائنين.\nج. يعد وكيل الإعسار قائمة بالدائنين الذين يحق لهم التصويت في الاجتماع.\nد. للدائنين حضور الاجتماع شخصيا أو تعيين ممثل عنهم سواء من بين الدائنين الآخرين أو من الغير بموجب وكالة عدلية أو خطية أمام الموظف المختص في المحكمة ويحظر على المدين أو الأشخاص ذوي الصلة به تمثيل أي دائن في الاجتماع.\nهـ. يعد أمين سر الاجتماع جدولا بالحضور أصالة أو وكالة ويرفق هذا الجدول بمحضر الاجتماع بعد اتخاذ القرارات.","title":"حضور اجتماع الدائنين","memo":"⭐ على وكيل الإعسار والمدين الحضور، وغياب الوكيل دون عذر تقبله المحكمة يعرضه لأحكام المادة (54) (العزل)\n⭐ يقتصر حق الحضور والتصويت على الدائنين المدرجين في القائمة\n⭐ التمثيل بوكالة عدلية أو خطية أمام موظف المحكمة، ويحظر على المدين أو ذوي الصلة به تمثيل أي دائن","qs":[{"q":"تغيب وكيل الإعسار عن اجتماع الدائنين دون عذر تقبله المحكمة، فما الأثر المترتب؟","o":["للمحكمة أن تطبق عليه أحكام المادة (54) المتعلقة بالعزل","يعتبر الاجتماع باطلا حكما","تفرض عليه غرامة تعادل أتعابه حكما","يؤجل الاجتماع لمدة خمسة أيام"],"a":0},{"q":"أي من الأشخاص التالية يحظر عليه تمثيل أي دائن في اجتماع الدائنين؟","o":["الأشخاص ذوو الصلة بالمدين","دائن آخر مدرج في القائمة","محام بموجب وكالة عدلية","شخص من الغير بموجب وكالة خطية أمام الموظف المختص"],"a":0},{"q":"يقتصر الحق في حضور اجتماع الدائنين والتصويت فيه على:","o":["الدائنين المدرجين في قائمة الدائنين","جميع من قدموا طلبات تسجيل ولو رفضت","أعضاء لجنة الدائنين فقط","الدائنين أصحاب الديون المضمونة"],"a":0}]},{"n":"88","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"للدائنين الحاضرين أو لممثليهم الاستيضاح وطلب معلومات حول تقرير وكيل الإعسار ولهم طلب معلومات إضافية عن خطة إعادة التنظيم من المدين أو الدائنين الذين افرحوا الخطة، حسب مقتضى الحال.","title":"حق الاستيضاح في اجتماع الدائنين","memo":"⭐ للدائنين الحاضرين أو ممثليهم الاستيضاح حول تقرير وكيل الإعسار وطلب معلومات إضافية عن الخطة من المدين أو الدائنين المقترحين","qs":[{"q":"يحق للدائنين الحاضرين في اجتماع الدائنين طلب معلومات إضافية عن خطة إعادة التنظيم من:","o":["المدين أو الدائنين الذين اقترحوا الخطة","قاضي المحكمة","الجهة المسؤولة عن ترخيص وكلاء الإعسار","ممثلي العاملين لدى المدين"],"a":0},{"q":"يحق للدائنين الحاضرين في اجتماع الدائنين أو لممثليهم الاستيضاح وطلب معلومات حول تقرير:","o":["وكيل الإعسار","لجنة الدائنين","الخبير المعين من المحكمة","مدقق حسابات المدين"],"a":0}]},{"n":"89","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. يفتتح الاجتماع رئيس الجلسة ويتولى إدارتها والنظر في طلبات الحاضرين.\nب. تعرض الخطة المقترحة لإعادة التنظيم من معديها وإذا تم الاعتراض عليها يختار رئيس الجلسة شخصين من المؤيدين وشخصين من المعترضين لإبداء آرائهم وله أن يستوضح عن أي أمر يرى ضرورة إطلاع الدائنين الحاضرين عليه.\nج. للمدين أو الدائنين تقديم اقتراحات حول الخطة ويبدأ بمناقشة مقترحات المدين والتصويت عليها اولا ثم المقترحات المقدمة من الدائنين أصحاب الديون الأكبر قيمة ولا يطرح أي مقترح للنقاش بعد حصول الموافقة.","title":"إدارة اجتماع الدائنين ومناقشة الخطة","memo":"⭐ يفتتح رئيس الجلسة الاجتماع ويديره\n⭐ عند الاعتراض على الخطة يختار الرئيس شخصين من المؤيدين وشخصين من المعترضين لإبداء آرائهم\n⭐ تناقش مقترحات المدين ويصوت عليها أولا ثم مقترحات أصحاب الديون الأكبر قيمة، ولا يطرح مقترح بعد حصول الموافقة","qs":[{"q":"إذا تم الاعتراض على خطة إعادة التنظيم المعروضة في الاجتماع، يختار رئيس الجلسة لإبداء الآراء:","o":["شخصين من المؤيدين وشخصين من المعترضين","شخصا واحدا من كل طرف","ثلاثة من المؤيدين وثلاثة من المعترضين","جميع المعترضين فقط"],"a":0},{"q":"ما ترتيب مناقشة المقترحات المقدمة حول الخطة في اجتماع الدائنين؟","o":["مقترحات المدين أولا ثم مقترحات الدائنين أصحاب الديون الأكبر قيمة","مقترحات الدائنين الأكبر قيمة أولا ثم مقترحات المدين","حسب أسبقية تقديمها","مقترحات وكيل الإعسار أولا ثم مقترحات المدين"],"a":0}]},{"n":"90","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. تتم الموافقة على خطة إعادة التنظيم بالأغلبية المطلقة من إجمالي الديون.\nب. إذا تضمنت خطة إعادة التنظيم تخفيضا أكثر من (%50) من الديون أو إعادة جدولة ديون لمدة تتجاوز خمس سنوات فيجب أن يوافق عليها الدائنون الذين خفضت ديونهم أو تم تأجيلها بأغلبية (%60) على الأقل من اجمالي ديونهم.\nج. إذا تضمنت خطه إعادة التنظيم معامله مجموعة من الدائنين من ضمن الفئة ذاتها معاملة تفضيلية، فيجب أن يوافق عليها بشكل مستقل أغلبية الدائنين الذين سيلحقهم ضرر من منح هذه المعاملة التفضيئية.","title":"أغلبية الموافقة على خطة إعادة التنظيم","memo":"⭐ الموافقة بالأغلبية المطلقة من إجمالي الديون\n⭐ تخفيض أكثر من 50% من الديون أو جدولة تتجاوز 5 سنوات: موافقة المتضررين بأغلبية 60% على الأقل من إجمالي ديونهم\n⭐ المعاملة التفضيلية ضمن الفئة: موافقة مستقلة من أغلبية الدائنين المتضررين منها","qs":[{"q":"تتم الموافقة على خطة إعادة التنظيم كأصل عام بـ:","o":["الأغلبية المطلقة من إجمالي الديون","أغلبية (60%) من إجمالي الديون","أغلبية ثلثي الديون الممثلة في الاجتماع","أغلبية الحاضرين عددا"],"a":0},{"q":"تضمنت خطة إعادة التنظيم إعادة جدولة ديون فئة من الدائنين لمدة سبع سنوات، فما الأغلبية المطلوبة من هؤلاء الدائنين؟","o":["(60%) على الأقل من إجمالي ديونهم","الأغلبية المطلقة من إجمالي ديونهم","(75%) على الأقل من إجمالي ديونهم","إجماعهم"],"a":0},{"q":"تتطلب الخطة موافقة الدائنين الذين خفضت ديونهم بأغلبية (60%) إذا تضمنت تخفيضا من الديون يزيد على:","o":["(50%)","(25%)","(30%)","(60%)"],"a":0}]},{"n":"91","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. يجوز الموافقة على خطة إعادة التنظيم ولو لم تحصل فئة من الدائنين على الأغلبية المطلوبة خلال اجتماع الدائنين اذا تحققت الشروط التالية:\n1. أن لا يؤدي تنفيذ الخطة إلى وضع الدائنين من الفئة ذاتها في مرتبة أدنى من مرتبتهم فيما لو تمت تصفية النشاط الاقتصادي.\n2. أن لا يلحق ضرر بأي من أعضاء أي فئة مقارنة مع اعضاء الفئات الأخرى من المرتبة ذاتها.\n3. أن لا يتقاضى أي دائن من ضمن أي فئة أخرى من الدائنين مبلغا أعلى من إجمالي ديون تلك الفئة.\nب. تقرر المحكمة اعتماد خطه إعادة التنظيم الواردة في الفقرة (أ) من هذه المادة بناء على طلب وكيل الإعسار أو المدين وفي هذه الحالة على المحكمة عرضها على وكيل الإعسار .","title":"اعتماد الخطة دون أغلبية إحدى الفئات","memo":"⭐ تجوز الموافقة ولو لم تحصل فئة على الأغلبية بشروط: عدم وضع دائني الفئة في مرتبة أدنى من التصفية، عدم الإضرار بأعضاء فئة مقارنة بفئات المرتبة ذاتها، ألا يتقاضى دائن من فئة أخرى أعلى من إجمالي ديون فئته\n⭐ تقرر المحكمة الاعتماد بطلب وكيل الإعسار أو المدين، وتعرضها على وكيل الإعسار","qs":[{"q":"تقرر المحكمة اعتماد خطة إعادة التنظيم رغم عدم حصول فئة من الدائنين على الأغلبية المطلوبة بناء على طلب:","o":["وكيل الإعسار أو المدين","لجنة الدائنين","أي دائن من الفئة الرافضة","دائنين يمثلون (20%) من الديون"],"a":0},{"q":"أي مما يلي لا يعد من شروط اعتماد الخطة رغم عدم حصول فئة من الدائنين على الأغلبية؟","o":["موافقة جميع الدائنين أصحاب الحقوق المضمونة","ألا يؤدي تنفيذ الخطة لوضع دائني الفئة في مرتبة أدنى مما لو تمت التصفية","ألا يلحق ضرر بأعضاء أي فئة مقارنة مع أعضاء الفئات الأخرى من المرتبة ذاتها","ألا يتقاضى أي دائن من فئة أخرى مبلغا أعلى من إجمالي ديون تلك الفئة"],"a":0}]},{"n":"92","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ.1. بعد الموافقة على خطة إعادة التنظيم يتولى أمين سر اجتماع الدائنين إعداد محضر الاجتماع على أن يتضمن ملخص النقاش ومداخلات الحضور والمقترح الذي تم قبوله ونتائج التصويت و بيان تصنيف كل دائن قام بالتصويت.\n2. يقوم وكيل الإعسار بإيداع المحضر لدى المحكمة مرفقا به النسخة الموافق عليها من خطة إعادة التنظيم وجدول الحضور الذي يبين الديون الممثلة في الاجتماع ويحتفظ بنسخة منها وللفرقاء جميعهم الاطلاع على المحضر والوثائق المرفقة به .\nب. للمدين ووكيل الإعسار والدائنين الذين عارضوا اعتماد خطة إعادة التنظيم أو لم يحضروا الاجتماع أن يتقدموا باعتراض على قرار الموافقة على الخطة بسبب مخالفة أحكام هذا القانون فيما يتعلق بشروط إعداد الخطة أو تشكيل الأغلبية، بما في ذلك الحالة المنصوص عليها في المادة (91) منه، او الإجراءات المتعلقة بانعقاد اجتماع الدائنين وذلك خلال مدة عشرة أيام من تاريخ إيداع الخطه لدى المحكمة واذا لم يتم الاعتراض خلال هذه المدة فتقرر المحكمة اعتمادها دون الحاجة لاتخاذ أي إجراء آخر.\nج.1. للمدين أو وكيل الإعسار أو دائنين يمثلون (%20) على الأقل من الديون أن يعترضوا على خطة إعادة التنظيم بسبب عدم جدواها خلال المدة المنصوص عليها في الفقرة (ب) من هذه المادة.\n2. تبلغ المحكمة الاعتراض المنصوص عليه في البند (1) من هده الفقرة الى وكيل الاعسار ولجنه الدائنين، إذا تم تشكيلها، وتمنحهم مهلة للرد على الاعتراض وللمحكمه أن تعين خبيرا لبيان مدى جدوى خطة إعادة التنظيم إذا رأت ضرورة لذلك.\n3. تبت المحكمة في الاعتراض خلال مدة عشرة أيام من انتهاء المدة المشار اليها في الفقرة (ب) من هذه المادة.","title":"محضر الاجتماع والاعتراض على الخطة","memo":"⭐ يعد أمين السر المحضر ويودعه الوكيل لدى المحكمة مع الخطة الموافق عليها وجدول الحضور\n⭐ الاعتراض لمخالفة القانون (شروط الخطة، الأغلبية، انعقاد الاجتماع) من المدين والوكيل والدائنين المعارضين أو الغائبين خلال 10 أيام من إيداع الخطة، وإلا تعتمدها المحكمة\n⭐ الاعتراض لعدم الجدوى: من المدين أو الوكيل أو دائنين يمثلون 20% على الأقل، وتبت المحكمة خلال 10 أيام، ولها تعيين خبير","qs":[{"q":"ما مدة الاعتراض على قرار الموافقة على خطة إعادة التنظيم؟","o":["عشرة أيام من تاريخ إيداع الخطة لدى المحكمة","خمسة أيام من تاريخ الاجتماع","خمسة عشر يوما من تاريخ إيداع الخطة","ثلاثون يوما من تاريخ إشهار الخطة"],"a":0},{"q":"ما النسبة الدنيا من الديون التي يجب أن يمثلها الدائنون للاعتراض على خطة إعادة التنظيم بسبب عدم جدواها؟","o":["(20%)","(10%)","(25%)","(35%)"],"a":0},{"q":"أي مما يلي لا يملك الاعتراض على قرار الموافقة على الخطة بسبب مخالفة أحكام القانون وفق الفقرة (ب) من المادة (92)؟","o":["الدائن الذي حضر الاجتماع وصوت بالموافقة على الخطة","المدين","وكيل الإعسار","الدائن الذي لم يحضر الاجتماع"],"a":0},{"q":"من يتولى إعداد محضر اجتماع الدائنين بعد الموافقة على خطة إعادة التنظيم؟","o":["أمين سر اجتماع الدائنين","قاضي المحكمة","المدين","رئيس لجنة الدائنين"],"a":0}]},{"n":"93","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. للدائنين الذين اعترضوا على خطة اعادة التنظيم وفق الإجراءات المنصوص عليها في المادة (92) من هذا القانون وللمدين استئناف قرار الموافقة على الخطة أو رفضها بعد استكمال إجراءات الاعتراض.\nب. يجب تقديم الاستئناف خطيا خلال مدة عشرة أيام من تاريخ إشهار قرار المحكمة حول الاعتراض في سجل الإعسار وعلى محكمة الاستئناف البت في الاستئناف خلال مدة عشرة ايام من تاريخ وروده لها ويكون قرارها في هذا الشأن قطعيا.\nج. لا يوقف الاستئناف نفاذ خطة إعادة التنظيم ما لم تقرر محكمة الاستئناف خلاف ذلك.","title":"استئناف قرار الموافقة على الخطة أو رفضها","memo":"⭐ للدائنين المعترضين وفق المادة (92) وللمدين استئناف القرار بعد استكمال إجراءات الاعتراض\n⭐ الاستئناف خطيا خلال 10 أيام من إشهار قرار المحكمة في سجل الإعسار، وتبت محكمة الاستئناف خلال 10 أيام وقرارها قطعي\n⭐ لا يوقف الاستئناف نفاذ الخطة ما لم تقرر محكمة الاستئناف خلاف ذلك","qs":[{"q":"ما مدة استئناف قرار المحكمة بالموافقة على خطة إعادة التنظيم أو رفضها؟","o":["عشرة أيام من تاريخ إشهار قرار المحكمة حول الاعتراض في سجل الإعسار","ثلاثون يوما من تاريخ صدور القرار","خمسة عشر يوما من تاريخ التبلغ","خمسة أيام من تاريخ صدور القرار"],"a":0},{"q":"ما حكم قرار محكمة الاستئناف في استئناف قرار الموافقة على خطة إعادة التنظيم؟","o":["قطعي","قابل للطعن لدى محكمة التمييز","قابل للاعتراض أمام المحكمة ذاتها","قابل للطعن خلال ثلاثين يوما"],"a":0},{"q":"هل يوقف الاستئناف نفاذ خطة إعادة التنظيم؟","o":["لا، ما لم تقرر محكمة الاستئناف خلاف ذلك","نعم حكما إلى حين البت فيه","نعم إذا قدمه المدين","نعم إذا قدمه دائنون يمثلون (20%) من الديون"],"a":0}]},{"n":"94","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. لا تؤثر خطة إعادة التنظيم على حقوق دائني الإعسار في مواجهة الغير من الملتزمين بسداد دين المدين بما في ذلك الكفيل الشخصي او العيني .\nب. يكون التزام ذمة الاعسار تجاه الغير من الملتزمين بسداد ديون المدين في حدود ما هو مخصص للدين في خطة إعادة التنظيم.","title":"أثر الخطة على الكفلاء والملتزمين","memo":"⭐ لا تؤثر الخطة على حقوق دائني الإعسار في مواجهة الغير الملتزمين بسداد دين المدين بما فيهم الكفيل الشخصي أو العيني\n⭐ التزام ذمة الإعسار تجاه هؤلاء الغير في حدود ما هو مخصص للدين في الخطة","qs":[{"q":"خفضت خطة إعادة التنظيم دين أحد البنوك على المدين، وكان للدين كفيل شخصي، فما أثر الخطة على حق البنك تجاه الكفيل؟","o":["لا تؤثر الخطة على حق البنك في مواجهة الكفيل","ينخفض التزام الكفيل بالنسبة ذاتها","تبرأ ذمة الكفيل كليا","يتوقف حق البنك تجاه الكفيل حتى انتهاء تنفيذ الخطة"],"a":0},{"q":"يكون التزام ذمة الإعسار تجاه الغير من الملتزمين بسداد ديون المدين في حدود:","o":["ما هو مخصص للدين في خطة إعادة التنظيم","كامل ما دفعوه للدائن","نصف قيمة الدين الأصلي","ما تقرره لجنة الدائنين"],"a":0}]},{"n":"95","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. تتوقف آثار إشهار الإعسار بصدور قرار المحكمة بالموافقة على خطة إعادة التنظيم.\nب. مع مراعاة القيود التي تتضمنها الخطة، يسترد المدين كامل صلاحياته في إدارة أمواله والتصرف فيها، ويعتبر المدين مخلا بالخطة إذا تجاوز هذه القيود.\nج. يجوز أن تنص خطة إعادة التنظيم على تكليف شخص أو لجنة الدائنين بالإشراف على تنفيذها، وإذا تضمنت الخطة هذا الشرط و لم تعين شخصا لذلك فيعتبر وكيل الإعسار حكما مشرفا على تنفيذ خطة إعادة التنظيم على أن تحدد خطة إعادة التنظيم صلاحيات المشرف وحقوقه وواجباته وأتعابه.\nد. على المشرف على تنفيذ خطة إعادة التنظيم، أو المدين، إذا لم يعين مشرفا، أن يعد تقريرا سنويا حول سير تنفيذ الخطة ويودعه لدى المحكمة للتشاور مع الدائنين ما لم تنص الخطة على ميعاد أخر.\nهـ. لا يؤثر تعيين وكيل الإعسار مشرفا على تنفيذ خطة إعادة التنظيم على واجباته وفقا لأحكام هذا القانون.","title":"آثار قرار الموافقة على الخطة والإشراف على تنفيذها","memo":"⭐ تتوقف آثار إشهار الإعسار بصدور قرار المحكمة بالموافقة على الخطة، ويسترد المدين صلاحياته مع مراعاة قيود الخطة ويعد مخلا إن تجاوزها\n⭐ إذا نصت الخطة على الإشراف دون تعيين شخص يعتبر وكيل الإعسار حكما مشرفا\n⭐ يعد المشرف (أو المدين إن لم يعين مشرف) تقريرا سنويا يودع لدى المحكمة ما لم تنص الخطة على ميعاد آخر","qs":[{"q":"متى تتوقف آثار إشهار الإعسار في مرحلة إعادة التنظيم؟","o":["بصدور قرار المحكمة بالموافقة على خطة إعادة التنظيم","بانعقاد اجتماع الدائنين","بانتهاء تنفيذ الخطة بالكامل","بانتهاء المرحلة التمهيدية"],"a":0},{"q":"نصت خطة إعادة التنظيم على تكليف مشرف بالإشراف على تنفيذها دون أن تعين شخصا لذلك، فمن يعتبر مشرفا؟","o":["وكيل الإعسار حكما","لجنة الدائنين حكما","المدين","شخص تعينه المحكمة لاحقا"],"a":0},{"q":"ما دورية التقرير الذي يعده المشرف على تنفيذ خطة إعادة التنظيم ما لم تنص الخطة على ميعاد آخر؟","o":["سنوي","ربع سنوي","نصف سنوي","شهري"],"a":0}]},{"n":"96","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. على المشرف على تنفيذ خطة إعادة التنظيم أو أعضاء لجنة الدائنين أو أي دائن إشعار المحكمة فور علمهم بحصول إخلال جوهري بالخطة والطلب منها اصدار قرار بعدم التزام المدين بالخطه ويعتبر عدم سداد أي قسط من الأقساط المنصوص عليها في الخطه إخلالا جوهريا بها.\nب. تبلغ المحكمة المدين بالطلب المنصوص عليه في الفقرة (أ) من هذه المادة و عليه أن يقدم دفوعه خلال مدة خمسه أيام من تاريخ تبلغه.\nج. يترتب على قرار المحكمة بتأكيد وجود إخلال بخطة إعادة التنظيم البدء في مرحلة التصفية.\nد. يكون القرار الصادر عن المحكمة قابلا للاستئناف خلال مدة عشرة أيام من اليوم التالي لتاريخ صدوره أو تبلغه، حسب مقتضى الحال وعلى محكمة الاستئناف البت في الاستئناف خلال مدة عشرة ايام من تاريخ وروده لها ويكون قرارها في هذا الشأن قطعيا.","title":"الإخلال الجوهري بخطة إعادة التنظيم","memo":"⭐ يشعر المحكمة بالإخلال الجوهري: المشرف على تنفيذ الخطة أو أعضاء لجنة الدائنين أو أي دائن، فور علمهم\n⭐ عدم سداد أي قسط من أقساط الخطة يعد إخلالاً جوهرياً\n⭐ يقدم المدين دفوعه خلال (5) أيام من تبلغه؛ وتأكيد الإخلال يرتب البدء في مرحلة التصفية\n⭐ الاستئناف خلال (10) أيام، وتبت محكمة الاستئناف خلال (10) أيام وقرارها قطعي","qs":[{"q":"وفقاً لقانون الإعسار، يعتبر إخلالاً جوهرياً بخطة إعادة التنظيم:","o":["عدم سداد أي قسط من الأقساط المنصوص عليها في الخطة","عدم سداد ثلاثة أقساط متتالية من أقساط الخطة","عدم سداد ما يزيد على (50%) من أقساط الخطة","التأخر في سداد القسط لمدة تزيد على ستين يوماً"],"a":0},{"q":"بعد تبلغ المدين طلب إصدار قرار بعدم التزامه بخطة إعادة التنظيم، عليه أن يقدم دفوعه خلال مدة:","o":["خمسة أيام من تاريخ تبلغه","عشرة أيام من تاريخ تبلغه","سبعة أيام من تاريخ تبلغه","خمسة عشر يوماً من تاريخ تبلغه"],"a":0},{"q":"يترتب على قرار المحكمة بتأكيد وجود إخلال بخطة إعادة التنظيم:","o":["البدء في مرحلة التصفية","إعادة التفاوض على خطة جديدة لإعادة التنظيم","تمديد مدة تنفيذ الخطة","إبراء المدين من الديون غير المسددة"],"a":0}]},{"n":"97","chapter":"الفصل التاسع - مرحلة إعادة التنظيم الاعتيادية","notes":[],"source":"أ. عند انتهاء تنفيذ خطة إعادة التنظيم على المدين أن يتقدم بطلب الى المحكمة لإصدار قرار انتهاء تنفيد الخطة على أن يرفق بطلبه ما يثبت الالتزام بالشروط المتفق عليها في خطة إعادة التنظيم .\nب. يتم نشر قرار المحكمة بإعلان انتهاء تنفيذ المدين للخطة وفقا لأحكام المادة (139) من هذا القانون ولكل ذي مصلحة أن يعترض خطيا خلال مدة عشرة أيام من تاريخ نشر القرار.\nج. إذا قدم اعتراض على قرار المحكمة وفقا لأحكام الفقرة (ب) من هذه المادة تستمع المحكمة لأقوال المدين والمشرف على تنفيذ خطة إعادة التنظيم وتتخذ قرارا خلال مدة خمسه أيام من تقديم الاعتراض إما بانتهاء تنفيذ خطة إعادة التنظيم بالكامل أو ببدء إجراءات التصفية.\nد. يكون قرار البت في الاعتراض الصادر عن المحكمة قابلا للاستئناف خلال مدة عشرة أيام من اليوم التالي لصدوره أو تبلغه حسب مقتضى الحال.","title":"انتهاء تنفيذ خطة إعادة التنظيم","memo":"⭐ يتقدم المدين بطلب للمحكمة لإصدار قرار انتهاء تنفيذ الخطة مرفقاً بما يثبت الالتزام بشروطها\n⭐ ينشر القرار وفق المادة (139)، والاعتراض خطياً خلال (10) أيام من تاريخ النشر\n⭐ عند الاعتراض تستمع المحكمة للمدين والمشرف وتقرر خلال (5) أيام: انتهاء التنفيذ بالكامل أو بدء التصفية\n⭐ قرار البت في الاعتراض قابل للاستئناف خلال (10) أيام","qs":[{"q":"يحق لكل ذي مصلحة الاعتراض خطياً على قرار المحكمة بإعلان انتهاء تنفيذ المدين لخطة إعادة التنظيم خلال مدة:","o":["عشرة أيام من تاريخ نشر القرار","خمسة أيام من تاريخ نشر القرار","خمسة عشر يوماً من تاريخ نشر القرار","ثلاثين يوماً من تاريخ نشر القرار"],"a":0},{"q":"إذا قدم اعتراض على قرار انتهاء تنفيذ خطة إعادة التنظيم، تتخذ المحكمة قرارها خلال مدة:","o":["خمسة أيام من تقديم الاعتراض","عشرة أيام من تقديم الاعتراض","سبعة أيام من تقديم الاعتراض","عشرين يوماً من تقديم الاعتراض"],"a":0},{"q":"الجهة الملزمة بالتقدم بطلب إلى المحكمة لإصدار قرار انتهاء تنفيذ خطة إعادة التنظيم هي:","o":["المدين","المشرف على تنفيذ الخطة","لجنة الدائنين","وكيل الإعسار"],"a":0}]},{"n":"98","chapter":"الفصل العاشر - التصفية","notes":[],"source":"أ. يلزم المدين بتقديم طلب الى المحكمة للبدء بإجراءات التصفية في أي من الحالات التالية:\n1. اذا وجد أن النشاط الاقتصادي غير مجد.\n2. عدم إمكانيه وضع خطة اعادة تنظيم .\n3. عدم قدرته على الالتزام بتنفيذ خطة إعادة التنظيم .\nب. في جميع الأحوال للمدين أن يطلب التصفية في أي وقت خلال السير بإجراءات الإعسار.\nج. يترتب على إخلال المدين بواجبه المنصوص عليه في الفقرة (أ) من هذه المادة الأثر ذاته الذي يترتب على إخلاله بواجب التقدم بطلب إشهار الإعسار.\nد. تقرر المحكمة خلال مدة عشرة أيام من تاريخ تقديم طلب المدين بدء مرحلة التصفية ولها أن تستمع لاقوال وكيل الإعسار ولجنة الدائنين إن وجدت قبل البت في الطلب.\nهـ. يلتزم وكيل الإعسار بتقديم طلب الى المحكمة للبدء بإجراءات التصفية إذا توقف النشاط الاقتصادي أو إذا لم تتوافر أسباب موضوعية لتوقع الموافقة على خطة إعادة التنظيم وعلى المحكمة أن تستمع لأقوال المدين ولجنة الدائنين، إن وجدت، قبل إصدار قرارها.\nو. إذا كان بدء مرحلة التصفية ناجما عن عدم الالتزام في تنفيذ خطة إعادة التنظيم تكلف المحكمة وكيل الإعسار ليتولى أعمال التصفية، ما لم تقرر المحكمة تعيين وكيل إعسار آخر.\nز. يتم إشهار قرار بدء مرحلة التصفية بالطرق المنصوص عليها في المادة (139) من هذا القانون.","title":"طلب البدء بإجراءات التصفية","memo":"⭐ يلزم المدين بطلب التصفية إذا: النشاط غير مجدٍ، أو تعذر وضع خطة إعادة تنظيم، أو عجز عن الالتزام بتنفيذها؛ وله طلبها في أي وقت\n⭐ إخلاله بهذا الواجب يرتب أثر الإخلال بواجب طلب إشهار الإعسار\n⭐ تقرر المحكمة بدء التصفية خلال (10) أيام من تقديم طلب المدين\n⭐ يلتزم وكيل الإعسار بطلب التصفية إذا توقف النشاط أو لم تتوافر أسباب موضوعية لتوقع الموافقة على الخطة؛ ويشهر القرار وفق المادة (139)","qs":[{"q":"أي مما يلي لا يعد من الحالات التي يلزم فيها المدين بتقديم طلب البدء بإجراءات التصفية؟","o":["انخفاض أرباح النشاط الاقتصادي عن السنة السابقة","إذا وجد أن النشاط الاقتصادي غير مجدٍ","عدم إمكانية وضع خطة إعادة تنظيم","عدم قدرته على الالتزام بتنفيذ خطة إعادة التنظيم"],"a":0},{"q":"تقرر المحكمة بدء مرحلة التصفية بناء على طلب المدين خلال مدة:","o":["عشرة أيام من تاريخ تقديم الطلب","خمسة أيام من تاريخ تقديم الطلب","عشرين يوماً من تاريخ تقديم الطلب","ثلاثين يوماً من تاريخ تقديم الطلب"],"a":0},{"q":"إذا كان بدء مرحلة التصفية ناجماً عن عدم الالتزام في تنفيذ خطة إعادة التنظيم، فإن المحكمة تكلف بأعمال التصفية:","o":["وكيل الإعسار، ما لم تقرر تعيين وكيل إعسار آخر","المشرف على تنفيذ الخطة حكماً","لجنة الدائنين","المدين تحت إشراف المحكمة"],"a":0},{"q":"يلتزم وكيل الإعسار بتقديم طلب البدء بإجراءات التصفية في حالة:","o":["توقف النشاط الاقتصادي","تأخر المدين في تقديم القوائم المالية","طلب أي دائن ذلك","انقضاء ستة أشهر على إشهار الإعسار"],"a":0}]},{"n":"99","chapter":"الفصل العاشر - التصفية","notes":[],"source":"أ. يترتب على بدء إجراءات التصفية منع المدين من إدارة أمواله والتصرف فيها ونقل مسؤوليه إدارتها لوكيل الإعسار.\nب. لا يترتب على بدء إجراءات التصفية وقف النشاط الاقتصادي للمدين تلقائيا ما لم يصدر قرار من المحكمة بذلك بناء على طلب وكيل الاعسار في الحالات التالية :\n1. إذا كانت الإيرادات المتحققة من النشاط الاقتصادي لا تكفي لتغطية مصاريف التصفية .\n2. إذا لم تكن هناك إمكانية لبيع النشاط الاقتصادي مع الحفاظ عليه عاملا ومنتجا.\nج. لغايات السير في إجراءات التصفية تعتبر ديون المدين المؤجلة جميعها مستحقه الأداء ويتم تقييم كافة المطالبات غير المالية وتحويلها لمبالغ مالية.","title":"آثار بدء إجراءات التصفية","memo":"⭐ بدء التصفية يمنع المدين من إدارة أمواله والتصرف فيها وتنتقل إدارتها لوكيل الإعسار\n⭐ لا يوقف النشاط الاقتصادي تلقائياً إلا بقرار من المحكمة بطلب وكيل الإعسار إذا: لم تكفِ الإيرادات لمصاريف التصفية، أو تعذر بيع النشاط عاملاً ومنتجاً\n⭐ تعتبر الديون المؤجلة جميعها مستحقة الأداء، وتقيّم المطالبات غير المالية وتحول لمبالغ مالية","qs":[{"q":"يترتب على بدء إجراءات التصفية نقل مسؤولية إدارة أموال المدين إلى:","o":["وكيل الإعسار","لجنة الدائنين","المحكمة مباشرة","المشرف على تنفيذ خطة إعادة التنظيم"],"a":0},{"q":"وفقاً لقانون الإعسار، فإن بدء إجراءات التصفية بالنسبة للنشاط الاقتصادي للمدين:","o":["لا يوقفه تلقائياً ما لم يصدر قرار من المحكمة بذلك بناء على طلب وكيل الإعسار","يوقفه حكماً من تاريخ بدء التصفية","يوقفه بقرار من لجنة الدائنين","يوقفه بعد مرور عشرين يوماً على بدء التصفية"],"a":0},{"q":"لغايات السير في إجراءات التصفية، فإن ديون المدين المؤجلة:","o":["تعتبر جميعها مستحقة الأداء","تبقى مؤجلة حتى حلول آجالها","تسقط إذا لم يطالب بها خلال سنة","تستحق بعد موافقة لجنة الدائنين"],"a":0}]},{"n":"100","chapter":"الفصل العاشر - التصفية","notes":[],"source":"أثناء إجراءات التصفية يجب مراعاة الاعتبارات التالية:\nأ. تنقل ملكية النشاط الاقتصادي كليا أو وحدات مجزأة مع الحفاظ عليه عاملا ومنتجا كلما كان ذلك ممكنا .\nب. إذا تم نقل ملكية النشاط الاقتصادي كليا أو وحدات مجزأة تنتقل حكما:\n1. العقود التي يكون المدين طرفا فيها دون موافقة اطراف العقد الآخرين.\n2. الرخص والأذونات والموافقات الحكومية دون الحاجة لأي إجراء او موافقة مع التزام الشخص الذي تملك النشاط الاقتصادي بشروط استمراريه الرخص والأذونات والموافقات ما لم ينص القانون على غير ذلك.\nج.1. على الرغم مما ورد في أي تشريع آخر، إذا تمت التصفية بشكل مجزأ، يتم بيع الأموال التي تعتبر جزءا من ذمة الإعسار خلال الفترة الزمنية المحددة في خطة التصفية وبإشراف المحكمة بالتنسيق مع الجهه صاحبة الاختصاص.\n2. للمحكمة بناء على طلب وكيل الإعسار أن تقرر إجراء البيع بالمزاد العلني أو إجراء بيع مباشر أو أي نوع آخر من البيوع التي تراها مناسبة لنقل ملكية الأموال بشكل قانوني.\n3. تنظم إجراءات البيع بما في ذلك أنواع البيوع وشروط كل منها والوقت اللازم لاتمامها وإجراءاتها بموجب نظام يصدر لهذه الغايه وفقا لأحكام هذا القانون.\nد. يجوز نقل ملكية أموال بعينها لدائن أو أكثر سدادا لدينه شريطة الحصول على موافقه المحكمة.\nهـ. لا يجوز لأي من الأشخاص ذوي الصلة بالمدين أن يتملكوا النشاط الاقتصادي العائد له أو أي وحدات منه أو أيا من أمواله إلا بموافقة المحكمة.","title":"اعتبارات نقل الملكية في التصفية","memo":"⭐ تنقل ملكية النشاط كلياً أو وحدات مجزأة مع الحفاظ عليه عاملاً ومنتجاً كلما أمكن\n⭐ عند نقل الملكية تنتقل حكماً العقود دون موافقة الأطراف الآخرين، والرخص والأذونات دون أي إجراء أو موافقة\n⭐ للمحكمة بطلب وكيل الإعسار تقرير البيع بالمزاد العلني أو المباشر أو غيره؛ وتنظم البيوع بنظام\n⭐ نقل أموال لدائن سداداً لدينه، وتملك الأشخاص ذوي الصلة بالمدين: بموافقة المحكمة","qs":[{"q":"إذا تم نقل ملكية النشاط الاقتصادي للمدين كلياً، فإن العقود التي يكون المدين طرفاً فيها:","o":["تنتقل حكماً دون موافقة أطراف العقد الآخرين","تنتقل بشرط موافقة أطراف العقد الآخرين","تنفسخ حكماً بنقل الملكية","تنتقل بموافقة لجنة الدائنين"],"a":0},{"q":"يقرر إجراء البيع بالمزاد العلني أو البيع المباشر لأموال ذمة الإعسار:","o":["المحكمة بناء على طلب وكيل الإعسار","وكيل الإعسار منفرداً","لجنة الدائنين بالأغلبية","وزير الصناعة والتجارة والتموين"],"a":0},{"q":"حالة عملية: رغب شقيق المدين (من الأشخاص ذوي الصلة به) في شراء إحدى وحدات النشاط الاقتصادي للمدين أثناء التصفية، فإن ذلك:","o":["لا يجوز إلا بموافقة المحكمة","جائز دون قيد لأنه بيع بثمن المثل","ممنوع مطلقاً","جائز بموافقة وكيل الإعسار فقط"],"a":0}]},{"n":"101","chapter":"الفصل العاشر - التصفية","notes":[],"source":"أ. تتم تصفية ذمة الإعسار وفقا لخطة التصفية التي يضعها وكيل الاعسار خلال مدة عشرين يوما من تاريخ بدء مرحله التصفية، وللمحكمة تمديد هذه المدة لمدة لا تتجاوز عشرة أيام لأسباب مبررة.\nب. تودع خطة التصفية لدى المحكمة ولدى وكيل الإعسار وللمدين ودائنيه والعاملين لديه ابداء ملاحظاتهم واعتراضاتهم عليها لدى وكيل الاعسار خلال مدة خمسه عشر يوما من تاريخ إيداعها لدى المحكمة.\nج. لوكيل الإعسار خلال مدة خمسة أيام من تاريخ انتهاء المدة المنصوص عليها في الفقرة (ب) من هذه المادة أن يأخذ بالملاحظات والاعتراضات كليا أو جزئيا ويعدل الخطة أو أن يبقيها دون تغيير ويقدمها للمحكمة وعلى المحكمة اعتمادها بشكلها النهائي خلال مدة خمسة أيام من تاريخ ورودها اليها .","title":"خطة التصفية","memo":"⭐ يضع وكيل الإعسار خطة التصفية خلال (20) يوماً من بدء التصفية، وللمحكمة التمديد مدة لا تتجاوز (10) أيام\n⭐ تودع لدى المحكمة ووكيل الإعسار، والملاحظات والاعتراضات (من المدين والدائنين والعاملين) خلال (15) يوماً من إيداعها\n⭐ لوكيل الإعسار خلال (5) أيام الأخذ بالملاحظات أو إبقاؤها، وتعتمدها المحكمة نهائياً خلال (5) أيام من ورودها","qs":[{"q":"يضع وكيل الإعسار خطة التصفية خلال مدة:","o":["عشرين يوماً من تاريخ بدء مرحلة التصفية","عشرة أيام من تاريخ بدء مرحلة التصفية","ثلاثين يوماً من تاريخ بدء مرحلة التصفية","خمسة عشر يوماً من تاريخ بدء مرحلة التصفية"],"a":0},{"q":"للمحكمة تمديد مدة وضع خطة التصفية لأسباب مبررة لمدة لا تتجاوز:","o":["عشرة أيام","عشرين يوماً","خمسة أيام","شهرين"],"a":0},{"q":"يحق للمدين ودائنيه والعاملين لديه إبداء ملاحظاتهم واعتراضاتهم على خطة التصفية خلال مدة:","o":["خمسة عشر يوماً من تاريخ إيداعها لدى المحكمة","عشرة أيام من تاريخ إيداعها لدى المحكمة","خمسة أيام من تاريخ إيداعها لدى المحكمة","ثلاثين يوماً من تاريخ إيداعها لدى المحكمة"],"a":0}]},{"n":"102","chapter":"الفصل العاشر - التصفية","notes":[],"source":"يعد وكيل الإعسار تقريرا كل شهرين حول سير عملية تصفية النشاط الاقتصادي للمدين على أن يتضمن التقرير بيانا بالديون المترتبة بعد إشهار الاعسار وما تم سداده منها والرصيد المستحق وقائمه جرد وقائمة دائنين محدثتين وتودع هذه التقارير لدى المحكمة ووكيل الإعسار وللمدين ودائنيه ولكل ذي مصلحة إبداء ملاحظاتهم حولها .","title":"تقارير سير التصفية","memo":"⭐ يعد وكيل الإعسار تقريراً كل شهرين حول سير التصفية\n⭐ يتضمن: الديون المترتبة بعد إشهار الإعسار وما سدد منها والرصيد المستحق، وقائمة جرد وقائمة دائنين محدثتين\n⭐ تودع لدى المحكمة ووكيل الإعسار، ولكل ذي مصلحة إبداء ملاحظاته","qs":[{"q":"يعد وكيل الإعسار تقريراً حول سير عملية تصفية النشاط الاقتصادي للمدين:","o":["كل شهرين","كل شهر","كل ثلاثة أشهر","كل ستة أشهر"],"a":0},{"q":"أي مما يلي لا يشترط تضمينه في تقرير وكيل الإعسار الدوري حول سير التصفية؟","o":["خطة إعادة تنظيم جديدة للنشاط","بيان بالديون المترتبة بعد إشهار الإعسار وما تم سداده منها","قائمة جرد محدثة","قائمة دائنين محدثة"],"a":0}]},{"n":"103","chapter":"الفصل العاشر - التصفية","notes":[],"source":"أ. يلتزم وكيل الإعسار بتصفية أموال ذمة الإعسار وحقوقها خلال مدة سنة من تاريخ بدء مرحلة التصفية وإلا يسقط تعيينه ويفقد حقه في تقاضي أتعابه ويعد مسؤولا عن رد أي مبالغ كان قد قبضها ما لم تقرر المحكمة خلاف ذلك.\nب. للمحكمة أن تمنح وكيل الإعسار مهلة إضافية لا تتجاوز الشهرين لمرتين حدا أعلى بناء على أسباب مبررة.","title":"مدة التصفية وجزاء تجاوزها","memo":"⭐ يلتزم وكيل الإعسار بتصفية أموال ذمة الإعسار خلال (سنة) من بدء التصفية\n⭐ وإلا يسقط تعيينه ويفقد حقه في الأتعاب ويرد ما قبضه ما لم تقرر المحكمة خلاف ذلك\n⭐ للمحكمة منحه مهلة إضافية لا تتجاوز (شهرين) لمرتين حداً أعلى لأسباب مبررة","qs":[{"q":"يلتزم وكيل الإعسار بتصفية أموال ذمة الإعسار وحقوقها خلال مدة:","o":["سنة من تاريخ بدء مرحلة التصفية","ستة أشهر من تاريخ بدء مرحلة التصفية","سنتين من تاريخ بدء مرحلة التصفية","ثلاث سنوات من تاريخ إشهار الإعسار"],"a":0},{"q":"الحد الأعلى للمهلة الإضافية التي تمنحها المحكمة لوكيل الإعسار لإتمام التصفية هو:","o":["شهران لمرتين حداً أعلى","شهران لمرة واحدة","ثلاثة أشهر لمرتين حداً أعلى","ستة أشهر لمرة واحدة"],"a":0},{"q":"إذا لم يتم وكيل الإعسار تصفية أموال ذمة الإعسار خلال المدة القانونية دون مهلة، فإن من آثار ذلك:","o":["سقوط تعيينه وفقدان حقه في تقاضي أتعابه","حبسه مدة لا تزيد على ثلاث سنوات حكماً","تحويل الإجراءات إلى مرحلة إعادة التنظيم","انتقال التصفية إلى لجنة الدائنين حكماً"],"a":0}]},{"n":"104","chapter":"الفصل العاشر - التصفية","notes":[],"source":"أ. لا يجوز أداء أي دفعات لدائني الاعسار إلا بعد أن تصبح قائمة الدائنين نهائية وتبدا مرحلة التصفية على أنه يجوز لوكيل الاعسار إنشاء حساب احتياطي بمبلغ كاف لسداد بعض الديون الى حين إدراجها في قائمة الدائنين النهائية عند إجراء التوزيع.\nب. لوكيل الإعسار وبموافقة المحكمة توزيع المبالغ على دائني الإعسار قيل إتمام إجراءات التصفيه حال توفر مبالغ كافيه على أن يراعي وكيل الإعسار في توزيع المبالغ الأولويات المنصوص عليها في هذا القانون.","title":"الدفعات لدائني الإعسار","memo":"⭐ لا تؤدى دفعات لدائني الإعسار إلا بعد أن تصبح قائمة الدائنين نهائية وتبدأ مرحلة التصفية\n⭐ يجوز لوكيل الإعسار إنشاء حساب احتياطي لسداد بعض الديون إلى حين إدراجها في القائمة النهائية\n⭐ لوكيل الإعسار بموافقة المحكمة التوزيع قبل إتمام التصفية مع مراعاة الأولويات","qs":[{"q":"لا يجوز أداء أي دفعات لدائني الإعسار إلا بعد:","o":["أن تصبح قائمة الدائنين نهائية وتبدأ مرحلة التصفية","انتهاء إجراءات التصفية بالكامل","موافقة لجنة الدائنين بالإجماع","مرور سنة على إشهار الإعسار"],"a":0},{"q":"يجوز لوكيل الإعسار توزيع المبالغ على دائني الإعسار قبل إتمام إجراءات التصفية حال توفر مبالغ كافية بشرط:","o":["موافقة المحكمة ومراعاة الأولويات المنصوص عليها في القانون","موافقة المدين","موافقة أغلبية الدائنين غير المضمونين","إشعار وزارة الصناعة والتجارة والتموين"],"a":0}]},{"n":"105","chapter":"الفصل العاشر - التصفية","notes":[],"source":"يعد وكيل الإعسار قبل توزيع عوائد التصفية قائمة تتضمن الديون التي يتوجب اعتمادها لغايات التوزيع والمبلغ المتوفر للتوزيع من أموال ذمة الإعسار مع بيان حصة كل دائن من المبلغ وتودع القائمة لدى المحكمة ووكيل الإعسار لاطلاع أي شخص ذي مصلحة عليها.","title":"قائمة توزيع عوائد التصفية","memo":"⭐ يعد وكيل الإعسار قبل التوزيع قائمة بالديون الواجب اعتمادها والمبلغ المتوفر للتوزيع وحصة كل دائن\n⭐ تودع القائمة لدى المحكمة ووكيل الإعسار لاطلاع أي شخص ذي مصلحة","qs":[{"q":"الجهة التي تعد قائمة الديون المعتمدة لغايات توزيع عوائد التصفية هي:","o":["وكيل الإعسار","المحكمة","لجنة الدائنين","المدين"],"a":0},{"q":"تتضمن القائمة التي تعد قبل توزيع عوائد التصفية:","o":["الديون الواجب اعتمادها والمبلغ المتوفر للتوزيع وحصة كل دائن","خطة إعادة التنظيم المعدلة","أسماء العاملين لدى المدين ورواتبهم فقط","الدعاوى المقامة على المدين"],"a":0}]},{"n":"106","chapter":"الفصل العاشر - التصفية","notes":[],"source":"أ. مع مراعاة الفقرة (أ) من المادة (38) من هذا القانون تسدد الديون وفقا للأولويات التالية:\n1. الديون المضمونة وتسدد من حصيلة بيع الضمانة بعد تنزيل مصاريف بيعها.\n2. الديون الممتازة وفقا لأحكام هذا القانون.\n3. الديون غير المضمونة.\n4. الديون الأدنى في مرتبة الأولوية وفقا لأحكام هذا القانون.\nب. لا يجوز سداد أي مبلغ لأي فئة من الدائنين إلا بعد سداد كامل ديون الفئة ذات الاولوية الأعلى وتسدد الديون حسب الاولوية في الفئة ذاتها .\nج. إذا تعذر سداد كامل ديون فئة من الدائنين أو أحد الديون داخل الفئة ذاتها يقسم المبلغ بين دائني تلك الفئة أو الدين داخل الفئة قسمة غرماء.","title":"أولويات سداد الديون","memo":"⭐ ترتيب السداد: 1) المضمونة من حصيلة بيع الضمانة بعد مصاريف البيع 2) الممتازة 3) غير المضمونة 4) الأدنى في مرتبة الأولوية\n⭐ لا يسدد لأي فئة إلا بعد سداد كامل ديون الفئة الأعلى أولوية\n⭐ إذا تعذر السداد الكامل لفئة يقسم المبلغ بين دائنيها قسمة غرماء","qs":[{"q":"تأتي في المرتبة الأولى في أولويات سداد الديون وفقاً لقانون الإعسار:","o":["الديون المضمونة من حصيلة بيع الضمانة بعد تنزيل مصاريف بيعها","الديون الممتازة","الديون غير المضمونة","الديون الأدنى في مرتبة الأولوية"],"a":0},{"q":"تأتي الديون غير المضمونة في ترتيب أولويات السداد في المرتبة:","o":["الثالثة","الأولى","الثانية","الرابعة"],"a":0},{"q":"إذا تعذر سداد كامل ديون فئة من الدائنين، فإن المبلغ المتوفر يقسم بين دائني تلك الفئة:","o":["قسمة غرماء","بالتساوي بغض النظر عن قيمة الديون","حسب أقدمية الديون","حسب قرار لجنة الدائنين"],"a":0}]},{"n":"107","chapter":"الفصل الحادي عشر - انتهاء إجراءات الإعسار","notes":[],"source":"أ. تعلن المحكمة انتهاء إجراءات الإعسار بعد إتمام التوزيع النهائي أو إذا تم سداد كامل الديون أثناء السير في إجراءات الإعسار و يتم إشهار قرار المحكمة وسبب انتهاء الإجراءات بالطريقة المنصوص عليها في المادة (139) من هذا القانون.\nب. إذا كان المدين شخصا اعتباريا، تنتهي شخصيته الاعتبارية باستكمال توزيع العوائد ما لم يتم سداد ديونه بالكامل، وعلى وكيل الإعسار تبليغ الجهة التي تم تسجيل الشخص الاعتباري لديها بقرار المحكمة لغايات شطب تسجيله وفقا للتشريعات ذات العلاقة.","title":"إعلان انتهاء إجراءات الإعسار","memo":"⭐ تعلن المحكمة انتهاء الإجراءات بعد التوزيع النهائي أو إذا سددت كامل الديون أثناء الإجراءات، ويشهر القرار وسببه وفق المادة (139)\n⭐ الشخص الاعتباري تنتهي شخصيته باستكمال توزيع العوائد ما لم تسدد ديونه بالكامل\n⭐ يبلغ وكيل الإعسار جهة التسجيل بقرار المحكمة لغايات الشطب","qs":[{"q":"تعلن المحكمة انتهاء إجراءات الإعسار في أي من الحالتين:","o":["بعد إتمام التوزيع النهائي أو إذا تم سداد كامل الديون أثناء السير في الإجراءات","بعد انقضاء سنة على بدء التصفية أو بطلب المدين","بعد موافقة لجنة الدائنين أو بطلب وكيل الإعسار","بعد إقرار خطة التصفية أو بعد صدور الإبراء"],"a":0},{"q":"إذا كان المدين شخصاً اعتبارياً، فإن شخصيته الاعتبارية تنتهي:","o":["باستكمال توزيع العوائد ما لم يتم سداد ديونه بالكامل","بمجرد بدء مرحلة التصفية","بمجرد إشهار الإعسار","بعد مرور سنة على انتهاء الإجراءات"],"a":0},{"q":"يتولى تبليغ الجهة التي سجل لديها الشخص الاعتباري المدين بقرار المحكمة لغايات شطب تسجيله:","o":["وكيل الإعسار","المدين","لجنة الدائنين","مراقب عام الشركات من تلقاء نفسه"],"a":0}]},{"n":"108","chapter":"الفصل الحادي عشر - انتهاء إجراءات الإعسار","notes":[],"source":"أ. للمدين حسن النية تقديم طلب للمحكمة بالابراء من الديون غير المسددة وعلى المحكمة تبليغ هذا الطلب الى دائني هذه الديون ووكيل الإعسار فور وروده اليها ولهم الحق في تقديم دفوعهم واعتراضاتهم على طلب المدين بالإبراء خلال مدة سبعة أيام من تاريخ تبلغهم الطلب.\nب. تنظر المحكمة في الطلب تدقيقا ولها ان تقرر الموافقة على إبراء المدين من التزماته المتبقيه بعد التثبت من ان المدين قد تصرف بشكل يتفق وحسن النية على أن يتضمن قرار المحكمة إلزام المدين بما يلي وخلال ثلاث سنوات من تاريخ صدور قرار المحكمة بالإبراء:\n1. ممارسة نشاط ربحي أو السعي للحصول على عمل إذا كان عاطلا عن العمل وأن لا يستنكف عن قبول أي عمل يناسب مؤهلاته اذا كان المدين شخصا طبيعيا.\n2. دفع (%50) من دخله المستقبلي لدائنيه، ويشمل ذلك قيمة أي أموال تؤول اليه عن طريق الإرث اذا كان المدين شخصا طبيعيا.\n3. إشعار المحكمة فورا بأي تغيير في موطنه أو مكان عمله أو بأي دخل تحقق له أو أموال آلت اليه .","title":"إبراء المدين حسن النية","memo":"⭐ للمدين حسن النية طلب الإبراء من الديون غير المسددة، وللدائنين ووكيل الإعسار الاعتراض خلال (7) أيام من تبلغهم\n⭐ تنظر المحكمة الطلب تدقيقاً بعد التثبت من حسن نية المدين\n⭐ يلزم المدين خلال (3) سنوات من قرار الإبراء بـ: ممارسة نشاط أو السعي لعمل، ودفع (50%) من دخله المستقبلي بما فيه الإرث (للشخص الطبيعي)، وإشعار المحكمة فوراً بتغير موطنه أو عمله أو أي دخل","qs":[{"q":"يحق لدائني الديون غير المسددة ووكيل الإعسار تقديم اعتراضاتهم على طلب المدين بالإبراء خلال مدة:","o":["سبعة أيام من تاريخ تبلغهم الطلب","خمسة أيام من تاريخ تبلغهم الطلب","عشرة أيام من تاريخ تبلغهم الطلب","خمسة عشر يوماً من تاريخ تبلغهم الطلب"],"a":0},{"q":"يتضمن قرار المحكمة بإبراء المدين الشخص الطبيعي إلزامه بدفع نسبة من دخله المستقبلي لدائنيه مقدارها:","o":["(50%)","(25%)","(30%)","(75%)"],"a":0},{"q":"مدة التزامات المدين المترتبة على قرار المحكمة بالإبراء هي:","o":["ثلاث سنوات من تاريخ صدور قرار الإبراء","سنة واحدة من تاريخ صدور قرار الإبراء","خمس سنوات من تاريخ صدور قرار الإبراء","ثماني سنوات من تاريخ صدور قرار الإبراء"],"a":0}]},{"n":"109","chapter":"الفصل الحادي عشر - انتهاء إجراءات الإعسار","notes":[],"source":"ترفض المحكمة منح المدين الإبراء في الحالات التالية:\nأ. اذا صدر حكم قطعي بإدانته بأي جرم جزائي ارتكب خلافا لأحكام هذا القانون .\nب. إذا قام المدين خلال السنوات الثلاث السابقة لطلب إشهار الإعسار أو بعد تقديم الطلب عن قصد أو إهمال بإعطاء تصريح خطي كاذب أو منقوص حول وضعه المالي لغايات الحصول على قرض أو منحة أو للتهرب من أداء مبالغ تعود للخزينة.\nج. إذا كان المدين حاصلا على إبراء من رصيد التزامات في السنوات الثماني السابقة لطلب الإبراء.\nد. إذا قام المدين خلال السنة السابقة لطلب الإبراء أو بعد تقديم الطلب عن قصد أو إهمال بأي فعل من شأنه التأثير سلبا على فدرته على سداد ديونه أو تأخير إشهار الإعسار .\nهـ. إذا كان المدين قد قام عن قصد أو إهمال، بإعطاء تصريح خطي كاذب أو منقوص عند إعداد القوائم والكشوفات المطلوب تقديمها حول أمواله ودخله ودائنيه وديونه وفقا لأحكام هذا القانون.","title":"حالات رفض منح الإبراء","memo":"⭐ ترفض المحكمة الإبراء: الإدانة بحكم قطعي بجرم خلافاً لهذا القانون\n⭐ تصريح خطي كاذب أو منقوص خلال (3) سنوات قبل طلب الإشهار أو بعده للحصول على قرض أو منحة أو التهرب من مبالغ للخزينة\n⭐ الحصول على إبراء في السنوات (8) السابقة لطلب الإبراء\n⭐ فعل يؤثر سلباً على القدرة على السداد أو يؤخر الإشهار خلال السنة السابقة لطلب الإبراء؛ أو تصريح كاذب في القوائم والكشوفات","qs":[{"q":"ترفض المحكمة منح المدين الإبراء إذا كان حاصلاً على إبراء من رصيد التزامات خلال السنوات السابقة لطلب الإبراء وعددها:","o":["ثماني سنوات","خمس سنوات","ثلاث سنوات","عشر سنوات"],"a":0},{"q":"ترفض المحكمة الإبراء إذا أعطى المدين عن قصد أو إهمال تصريحاً خطياً كاذباً حول وضعه المالي للحصول على قرض خلال:","o":["السنوات الثلاث السابقة لطلب إشهار الإعسار أو بعد تقديم الطلب","السنة السابقة لطلب إشهار الإعسار فقط","السنوات الخمس السابقة لطلب الإبراء","السنوات الثماني السابقة لطلب الإبراء"],"a":0},{"q":"حالة عملية: قام المدين قبل ستة أشهر من طلب الإبراء، عن إهمال، بفعل أثر سلباً على قدرته على سداد ديونه، فإن المحكمة:","o":["ترفض منحه الإبراء","تمنحه الإبراء لأن الفعل وقع عن إهمال لا عن قصد","تمنحه الإبراء بشرط دفع (50%) من دخله","تؤجل البت في الطلب ثلاث سنوات"],"a":0}]},{"n":"110","chapter":"الفصل الحادي عشر - انتهاء إجراءات الإعسار","notes":[],"source":"لا يسري الإبراء على ما يلي:\nأ. الالتزامات المالية الناشئة عن الجرائم المخلة بالثقة العامة والجرائم الواقعة على الأموال .\nب. التزامات المدين المالية تجاه أولاده القصر.\nج. الغرامات الجزائية والإدارية المستحقة للخزينة.\nد. الالتزامات المالية الناشئة عن المسؤولية الناجمة عن الإضرار بالغير أو التسبب بالوفاة.","title":"التزامات لا يسري عليها الإبراء","memo":"⭐ لا يسري الإبراء على: الالتزامات الناشئة عن الجرائم المخلة بالثقة العامة والجرائم الواقعة على الأموال\n⭐ التزامات المدين المالية تجاه أولاده القصر\n⭐ الغرامات الجزائية والإدارية المستحقة للخزينة\n⭐ الالتزامات الناشئة عن الإضرار بالغير أو التسبب بالوفاة","qs":[{"q":"أي مما يلي يسري عليه إبراء المدين وفقاً لقانون الإعسار؟","o":["الديون التجارية غير المضمونة غير المسددة","التزامات المدين المالية تجاه أولاده القصر","الغرامات الجزائية والإدارية المستحقة للخزينة","الالتزامات الناشئة عن التسبب بالوفاة"],"a":0},{"q":"لا يسري الإبراء على الالتزامات المالية الناشئة عن:","o":["الجرائم المخلة بالثقة العامة والجرائم الواقعة على الأموال","عقود القرض المصرفية","عقود الإيجار التجاري","فواتير الموردين"],"a":0}]},{"n":"111","chapter":"الفصل الحادي عشر - انتهاء إجراءات الإعسار","notes":[],"source":"أ. إذا ظهرت أموال جديدة للمدين خلال مدة سنة من تاريخ انتهاء إجراءات الإعسار أو ظهر ما يثبت قيام المدين بتصرف خاضع لاجراءات عدم النفاذ وفقا لأحكام هذا القانون، أو تحققت مسؤولية الشخص الذي يتولى إدارة المدين أو شركائه، فلأي دائن أن يطلب إعادة السير في إجراءات الإعسار.\nب. لا يحول انتهاء الشخصية الاعتبارية أو شطب المدين أو الغاء تسجيله دون إعادة السير في إجراءات الإعسار بحيث تتم إعادة تسجيله لغايات إعادة السير في إجراءات الاعسار فقط.\nج. يجوز إعادة السير في إجراءات الإعسار إذا ظهرت أموال أو أسباب كافية للادعاء على الغير لتغطية نفقات الإجراءات وتوفير مبالغ قابلة للسداد بما نسبته (%5) على الأقل للدائنين أصحاب الديون الممتازة.\nد. تقتصر إعادة السير في إجراءات الإعسار على استرداد وبيع الأموال أو اتخاذ الإجراءات اللازمة بهدف توزيع العوائد على الدائنين وفق قواعد الأولوية المنصوص عليها في هذا القانون .\nهـ. تعين المحكمة وكيل الإعسار ذاته ما لم تقرر خلاف ذلك وعلى وكيل الإعسار أن يعد قائمة جديدة للتوزيع وينفذ المهام المنصوص عليها في الفقرة (د) من هذه المادة.","title":"إعادة السير في إجراءات الإعسار","memo":"⭐ لأي دائن طلب إعادة السير إذا ظهرت أموال جديدة خلال (سنة) من انتهاء الإجراءات، أو ظهر تصرف خاضع لعدم النفاذ، أو تحققت مسؤولية المدير أو الشركاء\n⭐ انتهاء الشخصية الاعتبارية أو الشطب لا يحول دون إعادة السير، ويعاد التسجيل لهذه الغاية فقط\n⭐ شرط: أموال أو أسباب تكفي النفقات وتوفر (5%) على الأقل للدائنين أصحاب الديون الممتازة\n⭐ تعين المحكمة وكيل الإعسار ذاته ما لم تقرر خلاف ذلك","qs":[{"q":"يجوز لأي دائن طلب إعادة السير في إجراءات الإعسار إذا ظهرت أموال جديدة للمدين خلال مدة:","o":["سنة من تاريخ انتهاء إجراءات الإعسار","ستة أشهر من تاريخ انتهاء إجراءات الإعسار","ثلاث سنوات من تاريخ انتهاء إجراءات الإعسار","خمس سنوات من تاريخ انتهاء إجراءات الإعسار"],"a":0},{"q":"يشترط لإعادة السير في إجراءات الإعسار ظهور أموال أو أسباب تكفي لتغطية النفقات وتوفير مبالغ قابلة للسداد للدائنين أصحاب الديون الممتازة بنسبة لا تقل عن:","o":["(5%)","(10%)","(25%)","(50%)"],"a":0},{"q":"عند إعادة السير في إجراءات الإعسار، تعين المحكمة:","o":["وكيل الإعسار ذاته ما لم تقرر خلاف ذلك","وكيل إعسار جديداً حكماً","أحد الدائنين أصحاب الديون الممتازة","لجنة دائنين جديدة تتولى التوزيع"],"a":0}]},{"n":"112","chapter":"الفصل الثاني عشر - حالات الإعسار في حال عدم وجود أموال لدى المدين","notes":[],"source":"أ. ينشأ لدى وزارة الصناعة والتجارة والتموين حساب لتغطية النفقات الضرورية المتعلقة بإجراءات الإعسار في حال عدم وجود أموال لدى المدين.\nب. يغطي الحساب النفقات القضائية وأتعاب وكيل الإعسار .\nج. تتكون المصادر المالية لهذا الحساب مما يلي:\n1. مبلغ مخصص من الخزينة يحدد بقرار من مجلس الوزراء.\n2. نسبة من رسوم تسجيل المدينين المنصوص عليهم في هذا القانون.\n3. نسبة من رسوم ترخيص وكلاء الإعسار.\n4. نسبة من أتعاب وكلاء الإعسار.\nد. تحدد قيمة المساهمات المبينة في البنود (2) و (3) و(4) من الفقرة (ج) من هذه المادة وكيفية الصرف من هذا الحساب ومراقبة الدفعات وآليات تحديد الحد الأدنى لأتعاب وكلاء الإعسار في حالات الإعسار بدون أموال بشكل سنوي بمقتضى النظام الصادر لهذه الغاية.","title":"حساب الإعسار بدون أموال","memo":"⭐ ينشأ لدى وزارة الصناعة والتجارة والتموين حساب لتغطية نفقات الإعسار عند عدم وجود أموال لدى المدين\n⭐ يغطي النفقات القضائية وأتعاب وكيل الإعسار\n⭐ مصادره: مبلغ من الخزينة بقرار مجلس الوزراء، ونسبة من رسوم تسجيل المدينين، ومن رسوم ترخيص وكلاء الإعسار، ومن أتعابهم\n⭐ تحدد المساهمات وكيفية الصرف بنظام بشكل سنوي","qs":[{"q":"ينشأ حساب تغطية النفقات الضرورية لإجراءات الإعسار في حال عدم وجود أموال لدى المدين لدى:","o":["وزارة الصناعة والتجارة والتموين","وزارة المالية","البنك المركزي الأردني","وزارة العدل"],"a":0},{"q":"يحدد المبلغ المخصص من الخزينة لحساب الإعسار بدون أموال بقرار من:","o":["مجلس الوزراء","وزير الصناعة والتجارة والتموين","وزير المالية","المحكمة المختصة"],"a":0},{"q":"أي مما يلي لا يعد من المصادر المالية لحساب تغطية نفقات الإعسار في حال عدم وجود أموال لدى المدين؟","o":["نسبة من عوائد التصفية في جميع حالات الإعسار","نسبة من رسوم تسجيل المدينين","نسبة من رسوم ترخيص وكلاء الإعسار","نسبة من أتعاب وكلاء الإعسار"],"a":0}]},{"n":"113","chapter":"الفصل الثالث عشر - العقوبات","notes":[],"source":"أ. يعاقب بالحبس مدة لا تزيد على ثلاث سنوات المدين اذا كان شخصا طبيعيا والشخص الطبيعي الذي يتولى إدارته اذا كان المدين شخصا اعتباريا ، مع الزامهما برد الأموال لحساب الدائنين اذا ارتكب أيا من الأفعال\nالتالية:\n1. أخفى أي اموال تدخل ضمن ذمة الإعسار.\n2. بالغ في تقدير قيمة الأموال التي تدخل ضمن ذمة الإعسار بقصد التحايل، في الاتفاق الجاري مع دائنيه.\n3. اختلق دائنا وهميا أو بالغ في مبلغ دين أحد الدائنين أو أدرج اسم دائن نشأ دينه عن سبب غير مشروع في قائمة الدائنين بقصد إشراكه في مفاوضات الدائنين أو بالتصويت على خطة إعادة التنظيم.\n4. امتنع قاصدا عن تقديم البيانات والقيود التي تطلبها منه المحكمة أو وكيل الإعسار أو قدم بيانات وقيودا خاطئة.\n5. تعمد حذف اي من الديون أو الدائنين من القوائم والكشوفات.\n6. أبرم اتفاقية مع دائن بهدف منحه أو منح دائن آخر مزايا مقابل التصويت لصالح المدين أو الحاق الضرر بباقي الدائنين.\n7. تصرف في أي من أمواله بعد إشهار الاعسار بهدف اخفاء هذه الأموال أو استثنائها من عوائد التصفية.\nب. إذا ارتكب المدين إذا كان شخصا طبيعيا أو مديره إذا كان شخصا اعتباريا أي فعل من الافعال المنصوص عليها في الفقرة (أ) من هذه المادة خلال المرحلة التمهيديه أو مرحله اعادة التنظيم فللمحكمة السير في إجراءات التصفية وفقا لأحكام هذا القانون اذا رأت مقتضى لذلك.\nج. دون الإخلال بالعقوبات المنصوص عليها في هذا القانون، يعتبر تضمين الوثائق والاقرارات المقدمة من المدين بموجب أحكام هذا القانون بيانات كاذبة جرما جزائيا يعاقب عليه بموجب أحكام قانون العقوبات.\nد. يعد امتناع المدين عن التعاون أو قيامه بإعطاء معلومات كاذبة أو إخفاء الأموال جرائم جزائية معاقبا عليها بموجب هذه المادة، كما ينشأ عنها مسؤولية الأشخاص الذين يتولون إدارة الشخص الاعتباري وإذا كان المدين شخصا طبيعيا فإن ارتكابه لهذه الأفعال يسقط حقه في الحصول على الإبراء من الديون.","title":"جرائم المدين وعقوباتها","memo":"⭐ الحبس مدة لا تزيد على (3) سنوات للمدين الطبيعي أو مدير المدين الاعتباري مع رد الأموال لحساب الدائنين\n⭐ من الأفعال: إخفاء أموال، المبالغة في قيمتها، اختلاق دائن وهمي، الامتناع عن تقديم البيانات، حذف ديون أو دائنين، اتفاق لمنح مزايا مقابل التصويت، التصرف بالأموال بعد الإشهار لإخفائها\n⭐ ارتكابها في المرحلة التمهيدية أو إعادة التنظيم يجيز للمحكمة السير في التصفية\n⭐ امتناع المدين الطبيعي عن التعاون أو إعطاء معلومات كاذبة أو إخفاء الأموال يسقط حقه في الإبراء","qs":[{"q":"يعاقب المدين الشخص الطبيعي الذي أخفى أموالاً تدخل ضمن ذمة الإعسار بـ:","o":["الحبس مدة لا تزيد على ثلاث سنوات مع إلزامه برد الأموال لحساب الدائنين","غرامة لا تزيد على (5000) دينار فقط","الحبس مدة لا تزيد على سنة أو غرامة لا تزيد على (1000) دينار","الحبس مدة لا تقل عن خمس سنوات"],"a":0},{"q":"إذا ارتكب المدين أحد الأفعال المجرمة خلال المرحلة التمهيدية أو مرحلة إعادة التنظيم، فللمحكمة:","o":["السير في إجراءات التصفية إذا رأت مقتضى لذلك","إنهاء إجراءات الإعسار وإعادة الحال لما كان عليه","تعيين المدين مشرفاً على تنفيذ الخطة","منحه الإبراء بشروط"],"a":0},{"q":"يترتب على امتناع المدين الشخص الطبيعي عن التعاون أو إعطائه معلومات كاذبة، بالإضافة إلى المسؤولية الجزائية:","o":["سقوط حقه في الحصول على الإبراء من الديون","تحويل ديونه غير المضمونة إلى ديون ممتازة","وقف إجراءات الإعسار نهائياً","انتهاء شخصيته القانونية"],"a":0}]},{"n":"114","chapter":"الفصل الثالث عشر - العقوبات","notes":[],"source":"يعاقب بالحبس مدة لا تزيد على ثلاث سنوات أو بغرامة لا تزيد على (5000) خمسة آلاف دينار أو بكلتا هاتين العقوبتين مع إلزامه برد الأموال التي حصل عليها من ذمة الإعسار كل دائن للمدين قام بما يلي:\nأ. تعمد المبالغة في قيمة الديون المستحقة له على المدين أو طالب بديون وهمية باسمه أو باسم شخص ثالث بزعمه أنها مستحقة في ذمة الإعسار .\nب. اشترك في المداولات والتصويت على إعادة التنظيم مع علمه بأنه ليس مخولا بذلك.\nج. تعمد إبرام تصرف مع المدين قبل إشهار الإعسار للحصول على امتيازات خاصة بشكل يضر بالدائنين الآخرين.\nد. أبرم عن قصد تصرف مع المدين بعد إشهار الإعسار للحصول على امتيازات خاصة بشكل يضر بالدائنين الآخرين وفي هذه الحالة على المحكمة أن تحكم من تلقاء ذاتها بعدم نفاذ التصرف وبالتعويض بناء على طلب الجهات ذات العلاقة.","title":"جرائم الدائنين وعقوباتها","memo":"⭐ يعاقب الدائن بالحبس مدة لا تزيد على (3) سنوات أو بغرامة لا تزيد على (5000) دينار أو بكلتيهما مع رد ما حصل عليه\n⭐ الأفعال: المبالغة في ديونه أو المطالبة بديون وهمية، الاشتراك في التصويت دون تخويل، إبرام تصرف مع المدين قبل الإشهار أو بعده للحصول على امتيازات تضر بالدائنين\n⭐ في التصرف بعد الإشهار تحكم المحكمة من تلقاء ذاتها بعدم نفاذ التصرف","qs":[{"q":"الحد الأعلى للغرامة التي يعاقب بها الدائن الذي تعمد المبالغة في قيمة ديونه المستحقة على المدين هو:","o":["(5000) دينار","(1000) دينار","(10000) دينار","(3000) دينار"],"a":0},{"q":"إذا أبرم دائن عن قصد تصرفاً مع المدين بعد إشهار الإعسار للحصول على امتيازات خاصة تضر بباقي الدائنين، فعلى المحكمة أن تحكم من تلقاء ذاتها بـ:","o":["عدم نفاذ التصرف","بطلان إجراءات الإعسار","شطب الدائن من قائمة الدائنين نهائياً","تحويل دينه إلى دين أدنى في مرتبة الأولوية"],"a":0},{"q":"أي مما يلي لا يعد من الأفعال المعاقب عليها للدائن وفقاً لقانون الإعسار؟","o":["الاعتراض على خطة التصفية خلال المدة القانونية","المطالبة بديون وهمية باسمه أو باسم شخص ثالث","الاشتراك في التصويت على إعادة التنظيم مع علمه بعدم تخويله","تعمد إبرام تصرف مع المدين قبل الإشهار للحصول على امتيازات تضر بالدائنين"],"a":0}]},{"n":"115","chapter":"الفصل الثالث عشر - العقوبات","notes":[],"source":"يعاقب بالحبس مدة لا تزيد على ثلاث سنوات مع إلزامه برد أي مبالغ أو أتعاب حصل عليها من ذمة الإعسار كل وكيل إعسار قام بما يلي:\nأ. أساء إدارة أموال المدين أو التصرف فيها.\nب. استخدم صلاحياته لتحقيق مصلحة شخصية له.\nج. تعمد حجب أي معلومات أو تقديم معلومات أو اقرارات كاذبة بخصوص إعادة التنظيم أو التصفية بشكل أضر بمصالح المدين أو أي من الدائنين.","title":"جرائم وكيل الإعسار وعقوباتها","memo":"⭐ يعاقب وكيل الإعسار بالحبس مدة لا تزيد على (3) سنوات مع رد المبالغ والأتعاب التي حصل عليها\n⭐ الأفعال: إساءة إدارة أموال المدين أو التصرف فيها، استخدام الصلاحيات لمصلحة شخصية، تعمد حجب معلومات أو تقديم معلومات أو إقرارات كاذبة أضرت بالمدين أو الدائنين","qs":[{"q":"يعاقب وكيل الإعسار الذي استخدم صلاحياته لتحقيق مصلحة شخصية له بـ:","o":["الحبس مدة لا تزيد على ثلاث سنوات مع إلزامه برد أي مبالغ أو أتعاب حصل عليها","غرامة لا تزيد على (5000) دينار فقط","إلغاء ترخيصه دون أي عقوبة جزائية","الحبس مدة لا تقل عن سنة أو غرامة لا تقل عن (1000) دينار"],"a":0},{"q":"أي مما يلي يعد من الأفعال المعاقب عليها لوكيل الإعسار؟","o":["إساءة إدارة أموال المدين أو التصرف فيها","طلب مهلة إضافية من المحكمة لإتمام التصفية","إنشاء حساب احتياطي لسداد بعض الديون","تقديم طلب البدء بإجراءات التصفية"],"a":0}]},{"n":"116","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"تختص المحكمة بالاعتراف بأحكام الإعسار الدولية والتعاون مع المحاكم الأجنبية وغيرها من الهيئات المختصة شريطة المعامله بالمثل.","title":"الاعتراف بأحكام الإعسار الدولية","memo":"⭐ تختص المحكمة بالاعتراف بأحكام الإعسار الدولية والتعاون مع المحاكم الأجنبية والهيئات المختصة\n⭐ شرط ذلك: المعاملة بالمثل","qs":[{"q":"يشترط لاختصاص المحكمة بالاعتراف بأحكام الإعسار الدولية والتعاون مع المحاكم الأجنبية:","o":["المعاملة بالمثل","موافقة وزير العدل","وجود اتفاقية ثنائية مصادق عليها","موافقة لجنة الدائنين"],"a":0}]},{"n":"117","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"لوكيل الإعسار الأجنبي تقديم طلب إشهار الإعسار في المملكة إذا توافرت الشروط المنصوص عليها في هذا القانون.","title":"طلب الإشهار من وكيل إعسار أجنبي","memo":"⭐ لوكيل الإعسار الأجنبي تقديم طلب إشهار الإعسار في المملكة إذا توافرت الشروط المنصوص عليها في القانون","qs":[{"q":"يحق لوكيل الإعسار الأجنبي تقديم طلب إشهار الإعسار في المملكة:","o":["إذا توافرت الشروط المنصوص عليها في قانون الإعسار","بعد موافقة مجلس الوزراء","إذا كان المدين أجنبي الجنسية فقط","لا يحق له ذلك مطلقاً"],"a":0}]},{"n":"118","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"إذا تم الاعتراف باجراءات اعسار أجنبية يحق لوكيل الإعسار الأجنبي الاشتراك في إجراءات الاعسار التي تتم في المملكة فيما يتعلق بالديون والأموال وفقا لأحكام هذا الفصل.","title":"اشتراك وكيل الإعسار الأجنبي","memo":"⭐ إذا اعترف بإجراءات إعسار أجنبية يحق لوكيل الإعسار الأجنبي الاشتراك في إجراءات الإعسار في المملكة فيما يتعلق بالديون والأموال","qs":[{"q":"يحق لوكيل الإعسار الأجنبي الاشتراك في إجراءات الإعسار التي تتم في المملكة فيما يتعلق بالديون والأموال:","o":["إذا تم الاعتراف بإجراءات الإعسار الأجنبية","بمجرد تعيينه في الدولة الأجنبية","بموافقة المدين","بعد انتهاء إجراءات الإعسار في المملكة"],"a":0},{"q":"يقتصر اشتراك وكيل الإعسار الأجنبي في إجراءات الإعسار التي تتم في المملكة، بعد الاعتراف بالإجراءات الأجنبية، على ما يتعلق بـ:","o":["الديون والأموال وفقاً لأحكام فصل الإعسار الدولي","الدعاوى الجزائية المقامة على المدين","تعيين وكيل الإعسار المحلي","إصدار قرار الإبراء"],"a":0}]},{"n":"119","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"أ. يتمتع الدائنون الأجانب بالحقوق الممنوحة للدائنين المحليين بخصوص الحق في إشهار الإعسار والاشتراك في الإجراءات بموجب أحكام هذا الفصل.\nب. لا تؤثر أحكام الفقرة (أ) من هذه المادة على ترتيب أولوية الديون في إجراءات الإعسار التي تتم وفقا لهدا القانون .","title":"حقوق الدائنين الأجانب","memo":"⭐ يتمتع الدائنون الأجانب بحقوق الدائنين المحليين في إشهار الإعسار والاشتراك في الإجراءات\n⭐ لا يؤثر ذلك على ترتيب أولوية الديون","qs":[{"q":"وفقاً لقانون الإعسار، يتمتع الدائنون الأجانب بخصوص الحق في إشهار الإعسار والاشتراك في الإجراءات بـ:","o":["الحقوق الممنوحة للدائنين المحليين","حقوق أقل من الدائنين المحليين","أولوية على الدائنين المحليين","الحقوق التي تقررها المحكمة في كل حالة"],"a":0},{"q":"مساواة الدائنين الأجانب بالدائنين المحليين في الحقوق:","o":["لا تؤثر على ترتيب أولوية الديون في إجراءات الإعسار","تجعل ديونهم ديوناً ممتازة","تجعل ديونهم في المرتبة الأدنى","تمنحهم أولوية على الديون المضمونة"],"a":0}]},{"n":"120","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"أ. في الحالات التي يشترط فيها هذا القانون إشعار الدائنين يجب إشعار الدائنين الأجانب الذين ظهرت ديونهم في سجلات المدين بوجود إجراءات إعسار بموجب أحكام هذا القانون ويوجه الإشعار أيضا للدائنين المعلومين والذين ليس لهم عنوان في المملكة و للمحكمة أن تأمر باتخاذ الخطوات اللازمة لغايات تبليغ الدائنين الذين ليست لهم عناوين معروفة.\nب. يوجه الاشعار لكل من الدائنين الأجانب المشار اليهم في الفقرة (أ) من هذه المادة على حدة ما لم تقرر المحكمه توجيه الإشعارات بشكل آخر و يجوز أن يوجه الإشعار للدائنين الأجانب المعلومين عن طريق الإعلان في الصحف الأجنبية التي يرى وكيل الإعسار أنها الأنسب لضمان وصولها لعلم الدائنين المعلومين دون حاجة لتوجيه كتب رسميه لهم.\nج. يجب أن يتضمن إشعار إشهار الإعسار الموجه للدائنين الأجانب ما يلي :\n1. مهلة زمنيه معقولة للتقدم بالمطالبات ومكان تقديمها.\n2. بيانا عما إذا كان على الدائنين اصحاب الحقوق المضمونة التقدم بمطالباتهم.\n3. أي معلومات أخرى يجب تضمينها في هذا الاشعار وفقا لاحكام هذا القانون أو ترى المحكمة لزوم تقديمها.","title":"إشعار الدائنين الأجانب","memo":"⭐ يجب إشعار الدائنين الأجانب الظاهرة ديونهم في سجلات المدين، والمعلومين ممن ليس لهم عنوان في المملكة\n⭐ يوجه الإشعار لكل منهم على حدة ما لم تقرر المحكمة غير ذلك، ويجوز بالإعلان في الصحف الأجنبية التي يراها وكيل الإعسار الأنسب\n⭐ يتضمن: مهلة زمنية معقولة للمطالبات ومكانها، وبياناً عما إذا كان على أصحاب الحقوق المضمونة التقدم بمطالباتهم، وأي معلومات أخرى","qs":[{"q":"يجوز أن يوجه الإشعار للدائنين الأجانب المعلومين دون حاجة لتوجيه كتب رسمية لهم عن طريق:","o":["الإعلان في الصحف الأجنبية التي يرى وكيل الإعسار أنها الأنسب","النشر في الجريدة الرسمية فقط","السفارات الأردنية في الخارج حصراً","وزارة الخارجية"],"a":0},{"q":"أي مما يلي لا يشترط تضمينه في إشعار إشهار الإعسار الموجه للدائنين الأجانب؟","o":["قيمة أتعاب وكيل الإعسار","مهلة زمنية معقولة للتقدم بالمطالبات ومكان تقديمها","بيان عما إذا كان على الدائنين أصحاب الحقوق المضمونة التقدم بمطالباتهم","أي معلومات أخرى ترى المحكمة لزوم تقديمها"],"a":0}]},{"n":"121","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"أ. يتم الاعتراف بالإجراءات الأجنبية التي تندرج تحت تعريف إجراءات الإعسار بالمعنى المقصود في هذا القانون وبموجب طلب يتقدم به وكيل إعسار بالمعنى المقصود في هذا القانون الى المحكمة ويرفق بطلب\nالاعتراف ما يلي :\n1. صورة مصدقة عن قرار إشهار الإعسار وتعيين وكيل الإعسار الأجنبي في الدولة الأجنبية.\n2. شهادة صادرة عن المحكمة الأجنبية بوجود إجراءات إعسار أجنبية وتعيين وكيل الإعسار الأجنبي.\n3. أي بينة أخرى تقبلها المحكمة تدل على وجود إجراءات إعسار أجنبية وتعيين وكيل إعسار أجنبي في حال عدم توفر البينات المنصوص عليها في البندين (1) و (2) من هذه الفقرة.\n4. بيان يحدد الإجراءات الأجنبية كافة وأي إجراءات بموجب هذا القانون تتعلق بالدين وأي إجراءات معروفة لوكيل الإعسار الأجنبي.\nب. للمحكمة تكليف وكيل الإعسار بتقديم ترجمة للوثائق المقدمة لإثبات طلب الاعتراف الى اللغة العربية. ج. للمحكمة اعتبار أي وثيقة أخرى تقدم لتعزيز طلب الاعتراف صحيحة وسواء أكانت مصدقة أم غير مصدقة. د. تبت المحكمة في طلب الاعتراف بالإجراءات الأجنبية بشكل مستعجل وفي جميع الأحوال خلال مدة خمسة عشر يوما من تاريخ تقديمه.\nهـ. يعتبر المقر المسجل للمدين أو مكان إقامته المعتاد هو مركز مصالحه الرئيس، ما لم يثبت عكس ذلك .","title":"طلب الاعتراف بالإجراءات الأجنبية","memo":"⭐ يرفق بطلب الاعتراف: صورة مصدقة عن قرار الإشهار وتعيين الوكيل الأجنبي، أو شهادة من المحكمة الأجنبية، أو أي بينة أخرى تقبلها المحكمة، وبيان بالإجراءات الأجنبية كافة\n⭐ للمحكمة تكليف وكيل الإعسار بتقديم ترجمة إلى العربية، واعتبار أي وثيقة صحيحة مصدقة أم غير مصدقة\n⭐ تبت المحكمة بشكل مستعجل وخلال (15) يوماً من تقديم الطلب\n⭐ المقر المسجل أو مكان الإقامة المعتاد هو مركز المصالح الرئيس ما لم يثبت العكس","qs":[{"q":"تبت المحكمة في طلب الاعتراف بالإجراءات الأجنبية بشكل مستعجل وفي جميع الأحوال خلال مدة:","o":["خمسة عشر يوماً من تاريخ تقديمه","عشرة أيام من تاريخ تقديمه","ثلاثين يوماً من تاريخ تقديمه","خمسة أيام من تاريخ تقديمه"],"a":0},{"q":"يعتبر مركز المصالح الرئيس للمدين، ما لم يثبت عكس ذلك:","o":["المقر المسجل للمدين أو مكان إقامته المعتاد","مكان وجود أكبر أصوله","مكان إقامة أكبر دائنيه","الدولة التي صدر فيها أول قرار إشهار"],"a":0},{"q":"بالنسبة للوثائق المقدمة لتعزيز طلب الاعتراف بالإجراءات الأجنبية، فإن للمحكمة:","o":["اعتبار أي وثيقة صحيحة سواء أكانت مصدقة أم غير مصدقة","قبول الوثائق المصدقة من وزارة الخارجية فقط","قبول الوثائق المترجمة من مترجم محلف فقط","رفض أي وثيقة غير مصدقة حكماً"],"a":0}]},{"n":"122","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"يتم الاعتراف بالإجراءات الأجنبية على النحو التالي:\nأ. بوصفها إجراءات أجنبية رئيسة إذا تمت في الدولة التي يوجد بها مركز المصالح الرئيسة للمدين.\nب. بوصفها إجراءات أجنبية ثانوية إذا كان للمدين منشأة في الدولة الأجنبية.","title":"أنواع الإجراءات الأجنبية","memo":"⭐ رئيسة: إذا تمت في الدولة التي يوجد بها مركز المصالح الرئيسة للمدين\n⭐ ثانوية: إذا كان للمدين منشأة في الدولة الأجنبية","qs":[{"q":"يتم الاعتراف بالإجراءات الأجنبية بوصفها إجراءات أجنبية رئيسة إذا تمت في الدولة التي:","o":["يوجد بها مركز المصالح الرئيسة للمدين","يوجد للمدين فيها منشأة","يقيم فيها أكبر دائني المدين","يحمل المدين جنسيتها"],"a":0},{"q":"حالة عملية: شركة مركز مصالحها الرئيسة في الأردن ولها فرع (منشأة) في دولة أجنبية بدأت فيها إجراءات إعسار، فإن هذه الإجراءات يعترف بها بوصفها:","o":["إجراءات أجنبية ثانوية","إجراءات أجنبية رئيسة","إجراءات إعسار محلية","إجراءات مؤقتة لا يعترف بها"],"a":0}]},{"n":"123","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"على وكيل الإعسار الأجنبي أن يشعر المحكمة فور تقديم طلب الاعتراف بالإجراءات الأجنبية بما يلي: أ. أي تغيير جوهري يتعلق بالإجراءات الأجنبية المطلوب الاعتراف بها أو بتعيين وكيل الإعسار.\nب. أي إجراءات أجنبية أخرى تتعلق بالدين ذاته أو أي إجراء آخر يصبح معلوما لدى وكيل الإعسار الأجنبي.","title":"التزامات إشعار وكيل الإعسار الأجنبي","memo":"⭐ يشعر وكيل الإعسار الأجنبي المحكمة فور تقديم طلب الاعتراف بأي تغيير جوهري يتعلق بالإجراءات الأجنبية أو بتعيينه\n⭐ وبأي إجراءات أجنبية أخرى تتعلق بالدين ذاته أو أي إجراء يصبح معلوماً لديه","qs":[{"q":"على وكيل الإعسار الأجنبي أن يشعر المحكمة فور تقديم طلب الاعتراف بالإجراءات الأجنبية بـ:","o":["أي تغيير جوهري يتعلق بالإجراءات الأجنبية أو بتعيين وكيل الإعسار","أتعابه المتفق عليها في الدولة الأجنبية","أسماء جميع الدائنين المحليين","خطة التصفية المقترحة في المملكة"],"a":0},{"q":"يقع واجب إشعار المحكمة بأي إجراءات أجنبية أخرى تتعلق بالدين ذاته بعد تقديم طلب الاعتراف على:","o":["وكيل الإعسار الأجنبي","المدين","الدائنين الأجانب","وزارة العدل"],"a":0}]},{"n":"124","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"أ. للمحكمة قبل البت في طلب الاعتراف و بناء على طلب وكيل الإعسار الأجنبي ان تمنح مساعدة مؤقتة بشكل مستعجل لغايات اتخاذ الإجراءات اللازمة لحماية أموال المدين أو مصلحة الدائنين بما في ذلك ما يلي: 1. أن توقف التنفيذ على أموال المدين.\n2. أن تعهد الى وكيل الإعسار الأجنبي أو أي وكيل إعسار مؤقت بعملية إدارة وتحصيل أموال المدين الموجودة في المملكة كليا أو جزئيا بهدف حماية تلك الأموال والمحافظة على قيمتها بسبب طبيعتها أو لأي ظروف أخرى. 3. أن تمنح أي مساعدة منصوص عليها في البندين (2) و(4) من الفقرة (أ) من المادة (126) من هذا القانون.\nب. للمحكمة أن ترد طلب منح المساعدة بموجب هذه المادة إذا رأت أن من شأن قبول الطلب التدخل في سير إجراءات الإعسار الرئيسة الأجنبية.\nج. مع مراعاة أحكام المادة (126) من هذا القانون ينتهي أثر فرار منح المساعدة بموجب أحكام هذه المادة عند البت بطلب الاعتراف.","title":"المساعدة المؤقتة قبل الاعتراف","memo":"⭐ للمحكمة قبل البت في طلب الاعتراف وبطلب من وكيل الإعسار الأجنبي منح مساعدة مؤقتة مستعجلة لحماية أموال المدين أو مصلحة الدائنين\n⭐ تشمل: وقف التنفيذ على أموال المدين، وتكليف الوكيل الأجنبي أو وكيل مؤقت بإدارة وتحصيل الأموال في المملكة\n⭐ للمحكمة رد الطلب إذا كان سيتدخل في سير الإجراءات الرئيسة الأجنبية\n⭐ ينتهي أثر المساعدة عند البت بطلب الاعتراف (مع مراعاة المادة 126)","qs":[{"q":"تمنح المساعدة المؤقتة بموجب أحكام الإعسار الدولي قبل البت في طلب الاعتراف بناء على طلب:","o":["وكيل الإعسار الأجنبي","المدين","أي دائن محلي","النيابة العامة"],"a":0},{"q":"ينتهي أثر قرار منح المساعدة المؤقتة المقدمة قبل الاعتراف بالإجراءات الأجنبية:","o":["عند البت بطلب الاعتراف","بعد مرور خمسة عشر يوماً على منحها","عند انتهاء إجراءات الإعسار الأجنبية","بعد سنة من تاريخ منحها"],"a":0},{"q":"للمحكمة أن ترد طلب منح المساعدة المؤقتة إذا رأت أن من شأن قبوله:","o":["التدخل في سير إجراءات الإعسار الرئيسة الأجنبية","زيادة نفقات الإجراءات","تأخير إجراءات التصفية في المملكة شهرين","المساس بحقوق المدين في الإبراء"],"a":0}]},{"n":"125","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"أ. دون الإخلال بالحق في طلب إشهار الإعسار وفقا لأحكام هذا القانون يترتب على الاعتراف بالإجراءات الأجنبية الرئيسة ما يلي:\n1. عدم قبول الدعاوى أو الإجراءات الفردية المتعلقة بأموال المدين أو حقوقه أو التزاماته أو مسؤولياته أو الاستمرار فيها باستثناء الدعاوى أو أي إجراءات فردية يقيمها أي شخص للمدى اللازم لحماية حقوقه في مواجهه المدين.\n2. وقف التنفيذ على أموال المدين.\n3. وقف الحق في التصرف بأي أموال عائدة للمدين أو إثقالها بحقوق أو التصرف فيها بأي شكل آخر إلا فيما يخص تسيير أعماله المعتادة.\nب. تراعي المحكمة عند اتخاذ الإجراءات المنصوص عليها في الفقرة (أ) من هذه المادة توفير الحماية الكافية لمصالح مواطني المملكة في الإجراءات الأجنبية الرئيسة.","title":"آثار الاعتراف بالإجراءات الأجنبية الرئيسة","memo":"⭐ يترتب على الاعتراف بالإجراءات الأجنبية الرئيسة: عدم قبول الدعاوى والإجراءات الفردية أو الاستمرار فيها، إلا ما يلزم لحماية الحقوق في مواجهة المدين\n⭐ وقف التنفيذ على أموال المدين\n⭐ وقف حق التصرف بأمواله أو إثقالها إلا فيما يخص تسيير أعماله المعتادة\n⭐ تراعي المحكمة حماية مصالح مواطني المملكة","qs":[{"q":"أي مما يلي لا يعد من الآثار المترتبة على الاعتراف بالإجراءات الأجنبية الرئيسة؟","o":["إبراء المدين من ديونه في المملكة","وقف التنفيذ على أموال المدين","عدم قبول الدعاوى أو الإجراءات الفردية المتعلقة بأموال المدين","وقف الحق في التصرف بأموال المدين أو إثقالها بحقوق"],"a":0},{"q":"يستثنى من وقف الحق في التصرف بأموال المدين المترتب على الاعتراف بالإجراءات الأجنبية الرئيسة:","o":["ما يخص تسيير أعماله المعتادة","بيع العقارات","رهن أمواله لصالح دائن جديد","التبرع بأمواله"],"a":0},{"q":"تراعي المحكمة عند اتخاذ آثار الاعتراف بالإجراءات الأجنبية الرئيسة توفير الحماية الكافية لمصالح:","o":["مواطني المملكة في الإجراءات الأجنبية الرئيسة","وكيل الإعسار الأجنبي","الدولة الأجنبية","المحكمة الأجنبية"],"a":0}]},{"n":"126","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"أ. للمحكمة بعد الاعتراف بإجراءات الإعسار الأجنبية وبطلب من وكيل الاعسار الأجنبي منح المساعدة اذا رأت فى ذلك حمايه لأموال المدين أو لمصالح الدائنين ويشمل ذلك ما يلي:\n1. اتخاذ أي من الاجراءات المنصوص عليها في الفقرة (أ) من المادة (125) في حال لم يتم اتخادها بعد الاعتراف بالاجراءات الأجنبية .\n2. اتخاذ التدابير اللازمة للاستماع لأقوال الشهود أو جمع البينات أو تسليم المعلومات فيما يتعلق بأموال المدين أو شؤونه أو حقوقه أو التزاماته .\n3. أن تعهد لوكيل الإعسار الأجنبي أو لأي شخص تعينه بإدارة وتحصيل أموال المدين الموجودة في المملكه. 4. أن تمنح وكيل الإعسار الأجنبي التسهيلات الممنوحة لوكيل الإعسار وفقا لأحكام هذا القانون .\nب. للمحكمة بعد الاعتراف بالإجراءات الأجنبية وبناء على طلب وكيل الاعسار الأجنبي أن تعهد له أو لأي شخص آخر بتوزيع أموال المدين الموجودة في المملكة إذا تحققت من أن في ذلك حماية كافية لمصالح الدائنين في المملكة.","title":"المساعدة بعد الاعتراف","memo":"⭐ للمحكمة بعد الاعتراف وبطلب الوكيل الأجنبي منح المساعدة لحماية أموال المدين أو مصالح الدائنين\n⭐ تشمل: آثار المادة (125/أ) إن لم تتخذ، الاستماع للشهود وجمع البينات، إدارة وتحصيل الأموال، منح الوكيل الأجنبي تسهيلات وكيل الإعسار\n⭐ للمحكمة تكليفه أو غيره بتوزيع أموال المدين في المملكة إذا تحققت حماية كافية لمصالح الدائنين في المملكة","qs":[{"q":"للمحكمة بعد الاعتراف بالإجراءات الأجنبية أن تعهد لوكيل الإعسار الأجنبي بتوزيع أموال المدين الموجودة في المملكة إذا تحققت من:","o":["أن في ذلك حماية كافية لمصالح الدائنين في المملكة","موافقة المدين على ذلك","أن الإجراءات الأجنبية ثانوية","انقضاء سنة على الاعتراف"],"a":0},{"q":"أي مما يلي لا يعد من صور المساعدة التي تمنحها المحكمة بعد الاعتراف بإجراءات الإعسار الأجنبية؟","o":["إبراء المدين من الالتزامات المالية تجاه أولاده القصر","الاستماع لأقوال الشهود أو جمع البينات","أن تعهد لوكيل الإعسار الأجنبي بإدارة وتحصيل أموال المدين في المملكة","منح وكيل الإعسار الأجنبي التسهيلات الممنوحة لوكيل الإعسار"],"a":0}]},{"n":"127","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"أ. على المحكمة عند منح المساعدة او رفضها بعد أن تتحقق من حماية مصالح الدائنين وذوي المصلحه بمن فيهم المدين بشكل كاف ولها في سبيل ذلك وضع الشروط التي تراها مناسبة لمنح المساعدة .\nب. للمحكمة من تلقاء ذاتها أو بناء على طلب وكيل الإعسار الأجنبي أو أي شخص آخر يتأثر بمنح المساعدة أن تعدل أو تنهي تلك المساعدة.","title":"شروط منح المساعدة وتعديلها","memo":"⭐ تتحقق المحكمة عند منح المساعدة أو رفضها من حماية مصالح الدائنين وذوي المصلحة بمن فيهم المدين، ولها وضع الشروط المناسبة\n⭐ للمحكمة من تلقاء ذاتها أو بطلب الوكيل الأجنبي أو أي متأثر تعديل المساعدة أو إنهاؤها","qs":[{"q":"يحق للمحكمة تعديل المساعدة الممنوحة لوكيل الإعسار الأجنبي أو إنهاؤها:","o":["من تلقاء ذاتها أو بناء على طلب وكيل الإعسار الأجنبي أو أي شخص آخر يتأثر بها","بناء على طلب وكيل الإعسار الأجنبي فقط","بناء على طلب المدين فقط","بموافقة وزير العدل"],"a":0},{"q":"عند منح المساعدة لوكيل الإعسار الأجنبي أو رفضها، تتحقق المحكمة من حماية مصالح:","o":["الدائنين وذوي المصلحة بمن فيهم المدين بشكل كاف","الدائنين الأجانب فقط","الخزينة العامة فقط","وكيل الإعسار الأجنبي"],"a":0}]},{"n":"128","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"أ. يمنح الاعتراف بالإجراءات الأجنبية وكيل الإعسار الأجنبي الحق في اتخاذ أي إجراء لتقرير عدم نفاذ التصرفات التي تضر بالدائنين.\nب. إذا كانت الاجراءات الأجنبية ثانوية فعلى المحكمة أن تبين في قرارها بأن الإجراءات تتعلق بأموال يوجب هذا القانون إدارتها من وكيل إعسار أجنبي.","title":"دعاوى عدم النفاذ والإجراءات الثانوية","memo":"⭐ الاعتراف يمنح وكيل الإعسار الأجنبي حق اتخاذ أي إجراء لتقرير عدم نفاذ التصرفات المضرة بالدائنين\n⭐ في الإجراءات الثانوية تبين المحكمة في قرارها أن الإجراءات تتعلق بأموال يوجب القانون إدارتها من وكيل إعسار أجنبي","qs":[{"q":"يمنح الاعتراف بالإجراءات الأجنبية وكيل الإعسار الأجنبي الحق في:","o":["اتخاذ أي إجراء لتقرير عدم نفاذ التصرفات التي تضر بالدائنين","إبراء المدين من ديونه","إصدار قرار بدء التصفية في المملكة","تعيين لجنة الدائنين"],"a":0},{"q":"إذا كانت الإجراءات الأجنبية ثانوية، فعلى المحكمة أن تبين في قرارها أن الإجراءات تتعلق بـ:","o":["أموال يوجب هذا القانون إدارتها من وكيل إعسار أجنبي","جميع أموال المدين داخل المملكة وخارجها","ديون الدائنين المحليين فقط","الدعاوى الجزائية المقامة على المدين"],"a":0}]},{"n":"129","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"لوكيل الإعسار الأجنبي وبمجرد صدور قرار الاعتراف بالإجراءات الأجنبية أن يطلب ادخاله في أي إجراءات في المملكة يكون المدين طرفا فيها.","title":"إدخال وكيل الإعسار الأجنبي في الإجراءات","memo":"⭐ لوكيل الإعسار الأجنبي بمجرد صدور قرار الاعتراف أن يطلب إدخاله في أي إجراءات في المملكة يكون المدين طرفاً فيها","qs":[{"q":"يحق لوكيل الإعسار الأجنبي أن يطلب إدخاله في أي إجراءات في المملكة يكون المدين طرفاً فيها:","o":["بمجرد صدور قرار الاعتراف بالإجراءات الأجنبية","بعد مرور خمسة عشر يوماً على قرار الاعتراف","بمجرد تقديم طلب الاعتراف","بعد انتهاء إجراءات الإعسار الأجنبية"],"a":0}]},{"n":"130","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"أ. على المحكمة أن تتعاون مع المحاكم ووكلاء الاعسار الأجانب مباشرة أو من خلال وكيل الإعسار في المسائل المنصوص عليها في هذا الفصل ولها في سبيل ذلك أن تطلب منهم المساعدة أو أي معلومات ضروريه.\nب. على وكيل الاعسار التعاون مع المحاكم ووكلاء الإعسار الأجانب تحت اشراف المحكمة .\nج. يعد تعاونا لغايات هذه المادة ما يلي:\n1. تكليف أي شخص لتنفيذ أوامر المحكمة.\n2. تقديم المعلومات بأي وسيلة تراها المحكمة مناسبة.\n3. التنسيق بخصوص إدارة أموال المدين وشؤونه والاشراف عليها بما في ذلك موافقة المحكمة على الاتفاقيات المتعلقة بتنسيق الإجراءات ومتابعه تنفيذها.\n4. تنسيق الإجراءات المتزامنة التي تخص المدين ذاته.","title":"التعاون مع المحاكم ووكلاء الإعسار الأجانب","memo":"⭐ تتعاون المحكمة مع المحاكم ووكلاء الإعسار الأجانب مباشرة أو من خلال وكيل الإعسار، ولها طلب المساعدة والمعلومات\n⭐ يتعاون وكيل الإعسار معهم تحت إشراف المحكمة\n⭐ صور التعاون: تكليف أي شخص لتنفيذ أوامر المحكمة، تقديم المعلومات بأي وسيلة، التنسيق في إدارة الأموال والاتفاقيات، تنسيق الإجراءات المتزامنة","qs":[{"q":"يتعاون وكيل الإعسار مع المحاكم ووكلاء الإعسار الأجانب:","o":["تحت إشراف المحكمة","بصورة مستقلة دون إشراف","تحت إشراف وزارة الصناعة والتجارة والتموين","بموافقة لجنة الدائنين"],"a":0},{"q":"أي مما يلي لا يعد من صور التعاون مع المحاكم ووكلاء الإعسار الأجانب وفقاً لقانون الإعسار؟","o":["التنازل عن اختصاص المحكمة للمحكمة الأجنبية","تكليف أي شخص لتنفيذ أوامر المحكمة","تقديم المعلومات بأي وسيلة تراها المحكمة مناسبة","تنسيق الإجراءات المتزامنة التي تخص المدين ذاته"],"a":0}]},{"n":"131","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"لا يجوز إشهار إعسار بموجب هذا القانون بعد الاعتراف بإجراءات إعسار أجنبية إلا إذا كان للمدين أموال في المملكة.","title":"الإشهار بعد الاعتراف بإجراءات أجنبية","memo":"⭐ لا يجوز إشهار إعسار بموجب القانون بعد الاعتراف بإجراءات إعسار أجنبية إلا إذا كان للمدين أموال في المملكة","qs":[{"q":"بعد الاعتراف بإجراءات إعسار أجنبية، لا يجوز إشهار إعسار المدين بموجب قانون الإعسار الأردني إلا إذا:","o":["كان للمدين أموال في المملكة","كان المدين أردني الجنسية","وافق وكيل الإعسار الأجنبي","زادت ديونه المحلية على (50%) من مجموع ديونه"],"a":0}]},{"n":"132","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"اذا تزامنت إجراءات إعسار أجنبية مع إجراءات إعسار في المملكة بخصوص المدين ذاته فعلى المحكمة التعاون بموجب أحكام هذا القانون وتطبيق الأحكام التالية:\nأ. إذا تزامن السير في إجراءات الإعسار مع تقديم طلب الاعتراف بالاجراءات الأجنبية:\n1. يجب ان لا تتعارض المساعدة الممنوحة بموجب أحكام هذا الفصل مع إجراءات الإعسار في المملكة.\n2. لا تسري أحكام المادة (125) من هذا القانون على الحالات التي يتم فيها الاعتراف بإجراءات الإعسار الأجنبية في المملكة كإجراءات إعسار أجنبية ثانوية.\nب. إذا بدأت اجراءات الاعسار في المملكة بعد الاعتراف بإجراءات الإعسار الأجنبية أو بعد تقديم طلب\nللاعتراف بها تقوم المحكمة بما يلي :\n1. تعديل أو الغاء المساعدة الممنوحة بموجب أحكام هذا الفصل اذا تعارضت مع إجراءات الإعسار في المملكة.\n2. تعديل أو إلغاء الإجراءات المنصوص عليها في الفقرة (أ) من المادة (125) اذا تعارضت إجراءات إعسار أجنبية رئيسة مع إجراءات الإعسار في المملكة.\nج. على المحكمة التي تمنح المساعدة لوكيل إعسار أجنبي في اجراءات إعسار أجنبية ثانوية أو تمددها أو تعدلها أن تتحقق من أن المساعدة تتعلق بأموال يوجب هذا القانون أن تتم إدارتها من خلال إجراءات إعسار أجنبية ثانوية أو تتعلق بمعلومات مطلوبة لمثل هذه الإجراءات.","title":"تزامن الإجراءات الأجنبية والمحلية","memo":"⭐ إذا تزامن السير في الإجراءات المحلية مع طلب الاعتراف: يجب ألا تتعارض المساعدة مع إجراءات المملكة، ولا تسري المادة (125) على الإجراءات الأجنبية الثانوية\n⭐ إذا بدأت الإجراءات المحلية بعد الاعتراف أو طلبه: تعدل المحكمة أو تلغي المساعدة المتعارضة، وآثار المادة (125/أ) عند تعارض الإجراءات الرئيسة\n⭐ المساعدة في الإجراءات الثانوية يجب أن تتعلق بأموال يوجب القانون إدارتها من خلالها أو بمعلومات مطلوبة لها","qs":[{"q":"إذا تزامن السير في إجراءات الإعسار في المملكة مع تقديم طلب الاعتراف بالإجراءات الأجنبية، فإن المساعدة الممنوحة:","o":["يجب أن لا تتعارض مع إجراءات الإعسار في المملكة","تقدم على إجراءات الإعسار في المملكة","توقف إجراءات الإعسار في المملكة","تلغى حكماً"],"a":0},{"q":"لا تسري الآثار المنصوص عليها في المادة (125) على الحالات التي يتم فيها الاعتراف بإجراءات الإعسار الأجنبية بوصفها:","o":["إجراءات إعسار أجنبية ثانوية","إجراءات إعسار أجنبية رئيسة","إجراءات تتعلق بشخص طبيعي","إجراءات تتعلق بمدين له أموال في المملكة"],"a":0},{"q":"إذا بدأت إجراءات الإعسار في المملكة بعد الاعتراف بالإجراءات الأجنبية وتعارضت المساعدة الممنوحة معها، فإن المحكمة:","o":["تعدل المساعدة أو تلغيها","توقف إجراءات الإعسار في المملكة","تحيل الأمر إلى المحكمة الأجنبية","تبقي المساعدة دون تغيير"],"a":0}]},{"n":"133","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"اذا تزامنت إجراءات أجنبية بخصوص المدين ذاته فعلى المحكمة التعاون بموجب أحكام هذا القانون وتطبيق الأحكام التالية :\nأ. يجب أن لا تتعارض المساعدة الممنوحة لوكيل إعسار أجنبي بموجب احكام هذا الفصل مع إجراءات إعسار أجنبية رئيسه بعد الاعتراف بها.\nب. إذا تم الاعتراف بإجراءات إعسار أجنبية ثانوية بعد الاعتراف بإجراءات إعسار أجنبية ثانوية أخرى أو قدم طلب للاعتراف بها فعلى المحكمة مراجعة أي مساعدة ممنوحه بموجب احكام هذا الفصل وتعديلها او الغاؤها إذا كانت لا تتسق مع إجراءات الإعسار الأجنبية الرئيسة.\nج. إذا تم الاعتراف باجراءات إعسار أجنبية ثانوية بعد الاعتراف بإجراءات ثانوية أخرى، فعلى المحكمة أن تمنح المساعدة وتعدلها وتنهيها لغايات تسهيل التنسيق بين الاجراءات.","title":"تزامن عدة إجراءات أجنبية","memo":"⭐ يجب ألا تتعارض المساعدة الممنوحة لوكيل أجنبي مع إجراءات إعسار أجنبية رئيسة بعد الاعتراف بها\n⭐ تراجع المحكمة المساعدة وتعدلها أو تلغيها إذا لم تتسق مع الإجراءات الرئيسة\n⭐ عند الاعتراف بإجراءات ثانوية بعد أخرى ثانوية تمنح المحكمة المساعدة وتعدلها وتنهيها لتسهيل التنسيق","qs":[{"q":"إذا تزامنت إجراءات إعسار أجنبية بخصوص المدين ذاته، فإن المساعدة الممنوحة لوكيل إعسار أجنبي يجب ألا تتعارض مع:","o":["إجراءات الإعسار الأجنبية الرئيسة بعد الاعتراف بها","إجراءات الإعسار الأجنبية الثانوية","مصالح وكيل الإعسار الأجنبي","قرارات لجنة الدائنين الأجنبية"],"a":0},{"q":"إذا تم الاعتراف بإجراءات إعسار أجنبية ثانوية بعد الاعتراف بإجراءات ثانوية أخرى، فعلى المحكمة أن تمنح المساعدة وتعدلها وتنهيها لغايات:","o":["تسهيل التنسيق بين الإجراءات","تقديم الإجراءات الأحدث","حماية وكيل الإعسار الأجنبي","تسريع التصفية في المملكة"],"a":0}]},{"n":"134","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"لا يحق للدائن الذي استوفى جزءا من دينه بموجب إجراءات إعسار تمت وفقا لقانون أجنبي أن يستوفي أي مبلغ عن الدين ذاته بموجب إجراءات إعسار في مواجهة المدين ذاته في المملكة طالما أن المبلغ المدفوع للدائنين الآخرين من نفس المرتبة أقل نسبيا من المبلغ الذي قبضه الدائن بالفعل، وذلك باستثناء الديون المضمونة.","title":"قاعدة الاستيفاء من إجراءات أجنبية","memo":"⭐ الدائن الذي استوفى جزءاً من دينه بإجراءات إعسار أجنبية لا يستوفي عن الدين ذاته في المملكة طالما أن ما دفع للدائنين الآخرين من نفس المرتبة أقل نسبياً مما قبضه\n⭐ يستثنى من ذلك الديون المضمونة","qs":[{"q":"حالة عملية: دائن عادي استوفى (40%) من دينه في إجراءات إعسار أجنبية، ودفع للدائنين الآخرين من نفس المرتبة في المملكة (20%) من ديونهم، فإن هذا الدائن:","o":["لا يستوفي أي مبلغ عن الدين ذاته في المملكة طالما بقي ما دفع للآخرين أقل نسبياً","يستوفي حصته كاملة إلى جانب ما قبضه في الخارج","يستوفي (20%) إضافية فوراً","يحرم من دينه في المملكة نهائياً"],"a":0},{"q":"يستثنى من قاعدة عدم الاستيفاء في المملكة للدائن الذي استوفى جزءاً من دينه بموجب إجراءات إعسار أجنبية:","o":["الديون المضمونة","الديون الممتازة","الديون غير المضمونة","الديون الأدنى في مرتبة الأولوية"],"a":0}]},{"n":"135","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"إذا حصل تعارض بين هذا القانون والتزامات المملكة الناشئة عن معاهدات دولية تكون المملكة طرفا فيها، تطبق أحكام الاتفاقيات الدولية.","title":"أولوية المعاهدات الدولية","memo":"⭐ عند التعارض بين قانون الإعسار والتزامات المملكة الناشئة عن معاهدات دولية هي طرف فيها، تطبق أحكام الاتفاقيات الدولية","qs":[{"q":"إذا حصل تعارض بين قانون الإعسار والتزامات المملكة الناشئة عن معاهدات دولية تكون طرفاً فيها، فإنه يطبق:","o":["أحكام الاتفاقيات الدولية","أحكام قانون الإعسار","ما تقرره المحكمة وفق تقديرها","أحكام قانون التجارة"],"a":0}]},{"n":"136","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"عند تفسير أحكام هذا الفصل تؤخذ مصادره الدولية بعين الاعتبار لغايات توحيد تطبيقه.","title":"تفسير أحكام الإعسار الدولي","memo":"⭐ عند تفسير أحكام فصل الإعسار الدولي تؤخذ مصادره الدولية بعين الاعتبار لغايات توحيد تطبيقه","qs":[{"q":"عند تفسير أحكام الفصل المتعلق بالإعسار الدولي تؤخذ بعين الاعتبار لغايات توحيد تطبيقه:","o":["مصادره الدولية","أحكام قانون التجارة لسنة 1966","اجتهادات المحاكم المحلية فقط","تعليمات وزارة الصناعة والتجارة والتموين"],"a":0}]},{"n":"137","chapter":"الفصل الرابع عشر - الإعسار الدولي","notes":[],"source":"لا تحول أحكام هذا القانون دون صلاحية المحكمة برفض اتخاذ أي إجراء منصوص عليه في هذا الفصل إذا كان يشكل مخالفة للنظام العام في المملكة.","title":"النظام العام في الإعسار الدولي","memo":"⭐ للمحكمة رفض اتخاذ أي إجراء في فصل الإعسار الدولي إذا كان يشكل مخالفة للنظام العام في المملكة","qs":[{"q":"للمحكمة رفض اتخاذ أي إجراء منصوص عليه في فصل الإعسار الدولي إذا كان:","o":["يشكل مخالفة للنظام العام في المملكة","مكلفاً للخزينة","مطلوباً من دائن أجنبي","يتعلق بشركة أجنبية"],"a":0},{"q":"حالة عملية: طلب وكيل إعسار أجنبي من المحكمة اتخاذ إجراء بموجب فصل الإعسار الدولي يشكل مخالفة للنظام العام في المملكة، فإن المحكمة:","o":["لها صلاحية رفض اتخاذ هذا الإجراء","ملزمة باتخاذه شريطة المعاملة بالمثل","ملزمة باتخاذه لأولوية الاتفاقيات الدولية","تحيل الطلب إلى مجلس الوزراء للبت فيه"],"a":0}]},{"n":"138","chapter":"الفصل الخامس عشر - أحكام ختامية","notes":[],"source":"أ. تختص المحكمة بالنظر في إجراءات الإعسار بناء على الطلبات التي يقدمها الخصوم، ولها من تلقاء ذاتها أن تنظر تدقيقا في أي مسائل أو طلبات تتعلق بإجراءات الإعسار إذا رأت ذلك ضروريا.\nب. تختص المحكمة بالنظر في أي مسائل تتعلق بتطبيق أحكام هذا القانون وفي أي دعاوى أو طلبات تؤثر على ذمه الإعسار، بما في ذلك ما يلي:\n1. القضايا التنفيذية.\n2. أي إجراءات تحفظية تتعلق بأموال ذمة الإعسار.\n3. دعاوى عدم نفاذ تصرفات المدين.\n4. الدعاوى المتعلقة بمسؤولية المدين والأشخاص الذين يتولون إدارته و مدققي حساباته.\nه. الدعاوى المتعلقة بقبول طلبات تسجيل ديون الدائنين أو الاعتراض عليها.\n6. الدعاوى المقامة لتعديل او إنهاء العقود الجاري تنفيذها وعقود العمل وفقا لأحكام هذا القانون.\nج. لا تختص المحكمة بالنظر في الدعاوى المقامة من المدين إلا في الحالات المنصوص عليها في الفقرة (ج) من المادة (21) من هذا القانون.","title":"اختصاص محكمة الإعسار","memo":"⭐ تنظر المحكمة في إجراءات الإعسار بناء على طلبات الخصوم، ولها من تلقاء ذاتها النظر تدقيقاً في أي مسائل إذا رأت ذلك ضرورياً\n⭐ تختص بالقضايا التنفيذية والإجراءات التحفظية ودعاوى عدم النفاذ ومسؤولية المدين ومديريه ومدققي حساباته وتسجيل الديون وتعديل أو إنهاء العقود الجارية وعقود العمل\n⭐ لا تختص بالدعاوى المقامة من المدين إلا في حالات الفقرة (ج) من المادة (21)","qs":[{"q":"أي مما يلي لا يدخل في اختصاص محكمة الإعسار وفقاً للمادة المتعلقة باختصاصها؟","o":["الدعاوى المقامة من المدين في غير الحالات المنصوص عليها في الفقرة (ج) من المادة (21)","دعاوى عدم نفاذ تصرفات المدين","الدعاوى المتعلقة بمسؤولية مدققي حسابات المدين","الإجراءات التحفظية المتعلقة بأموال ذمة الإعسار"],"a":0},{"q":"للمحكمة أن تنظر تدقيقاً في أي مسائل أو طلبات تتعلق بإجراءات الإعسار:","o":["من تلقاء ذاتها إذا رأت ذلك ضرورياً","بناء على طلب وكيل الإعسار فقط","بموافقة لجنة الدائنين","بطلب من وزير الصناعة والتجارة والتموين"],"a":0}]},{"n":"139","chapter":"الفصل الخامس عشر - أحكام ختامية","notes":[],"source":"أ. باستثناء ما نص عليه صراحة في هذا القانون:\n1. يتم تبليغ المدين بالبريد المسجل أو أي من وسائل التبليغ المعتمدة بموجب قانون أصول المحاكمات المدنيه والأنظمة الصادرة بمقتضاه وذلك خلال مدة خمسة عشر يوما من تاريخ صدور أي قرار يتعلق بإجراءات الإعسار.\nوإذا لم يكن للمدين عنوان معروف أو مسجل، فيتم تبليغه وفقا لقانون أصول المحاكمات المدنيه .\n2. يتم تبليغ الدائنين بأي قرار يتعلق بإجراءات الإعسار خلال مدة خمسة عشرة يوما من تاريخ صدوره عن طريق نشر القرار في صحيفتين يوميتين على ان تكون إحداهما صحيفة أجنبية اذا كان يوجد بها طرف اجنبي وفي سجل الإعسار إذا رأت ذلك ضروريا.\nب. يتم تبليغ الجهات الأخرى ذات العلاقة بالإجراءات المتخذة لدى المحكمة خلال مدة خمسة أيام من تاريخ اتخاذ الإجراء وفقا لقانون أصول المحاكمات المدنية.\nج. في الحالات التي لم يرد عليها نص تطبق أحكام قانون أصول المحاكمات المدنية المتعلقة بالتبليغات ومواعيد الاستئناف وحساب المواعيد .","title":"التبليغات في إجراءات الإعسار","memo":"⭐ يبلغ المدين بالبريد المسجل أو وسائل التبليغ المعتمدة خلال (15) يوماً من صدور القرار، وإن لم يكن له عنوان فوفق قانون أصول المحاكمات المدنية\n⭐ يبلغ الدائنون خلال (15) يوماً بالنشر في صحيفتين يوميتين إحداهما أجنبية إن وجد طرف أجنبي، وفي سجل الإعسار إن رأت المحكمة ذلك\n⭐ تبلغ الجهات الأخرى ذات العلاقة خلال (5) أيام من اتخاذ الإجراء\n⭐ فيما لا نص فيه يطبق قانون أصول المحاكمات المدنية في التبليغات ومواعيد الاستئناف وحساب المواعيد","qs":[{"q":"يتم تبليغ الدائنين بأي قرار يتعلق بإجراءات الإعسار عن طريق:","o":["نشر القرار في صحيفتين يوميتين خلال خمسة عشر يوماً من صدوره","البريد المسجل لكل دائن خلال عشرة أيام","النشر في الجريدة الرسمية خلال ثلاثين يوماً","التبليغ بالذات خلال خمسة أيام"],"a":0},{"q":"يتم تبليغ الجهات الأخرى ذات العلاقة بالإجراءات المتخذة لدى المحكمة خلال مدة:","o":["خمسة أيام من تاريخ اتخاذ الإجراء","خمسة عشر يوماً من تاريخ اتخاذ الإجراء","عشرة أيام من تاريخ اتخاذ الإجراء","سبعة أيام من تاريخ اتخاذ الإجراء"],"a":0},{"q":"يتم تبليغ المدين بأي قرار يتعلق بإجراءات الإعسار، باستثناء ما نص عليه صراحة، خلال مدة:","o":["خمسة عشر يوماً من تاريخ صدور القرار","خمسة أيام من تاريخ صدور القرار","عشرة أيام من تاريخ صدور القرار","ثلاثين يوماً من تاريخ صدور القرار"],"a":0}]},{"n":"140","chapter":"الفصل الخامس عشر - أحكام ختامية","notes":[],"source":"تلغى أحكام الإفلاس والصلح الواقي منه الواردة في المواد من (290) ولغاية (477) من قانون التجارة رقم (12) لسنة 1966 ولا يعمل بأي نص ورد في أي تشريع آخر إلى المدى الذي يتعارض فيه مع أحكام هذا القانون.","title":"إلغاء أحكام الإفلاس","memo":"⭐ تلغى أحكام الإفلاس والصلح الواقي منه في المواد (290) لغاية (477) من قانون التجارة رقم (12) لسنة 1966\n⭐ لا يعمل بأي نص في تشريع آخر إلى المدى الذي يتعارض فيه مع قانون الإعسار","qs":[{"q":"ألغى قانون الإعسار أحكام الإفلاس والصلح الواقي منه الواردة في:","o":["المواد من (290) ولغاية (477) من قانون التجارة رقم (12) لسنة 1966","المواد من (1) ولغاية (289) من قانون التجارة رقم (12) لسنة 1966","قانون الشركات رقم (22) لسنة 1997","المواد من (290) ولغاية (477) من القانون المدني"],"a":0},{"q":"أي نص ورد في تشريع آخر يتعارض مع أحكام قانون الإعسار:","o":["لا يعمل به إلى المدى الذي يتعارض فيه مع أحكام قانون الإعسار","يقدم على قانون الإعسار","يلغى بالكامل حتى فيما لا يتعارض فيه","يطبق بقرار من المحكمة"],"a":0}]},{"n":"141","chapter":"الفصل الخامس عشر - أحكام ختامية","notes":[],"source":"يصدر مجلس الوزراء الأنظمة اللازمة لتنفيذ أحكام هذا القانون بما في ذلك:\nأ. سجل الإعسار.\nب. ترخيص وكلاء الإعسار .\nج. حساب معالجة حالات الإعسار مع عدم وجود أموال.\nد. شروط تشكيل لجنة الدائنين .\nهـ. تحديد معايير أتعاب وكلاء الإعسار.\nو. بيع الأموال المنقولة وغير المنقولة في حالة التصفية.","title":"الأنظمة التنفيذية لقانون الإعسار","memo":"⭐ يصدر مجلس الوزراء الأنظمة اللازمة لتنفيذ القانون\n⭐ منها: سجل الإعسار، ترخيص وكلاء الإعسار، حساب الإعسار بدون أموال، شروط تشكيل لجنة الدائنين، معايير أتعاب وكلاء الإعسار، بيع الأموال المنقولة وغير المنقولة في التصفية","qs":[{"q":"الجهة المختصة بإصدار الأنظمة اللازمة لتنفيذ أحكام قانون الإعسار هي:","o":["مجلس الوزراء","وزير الصناعة والتجارة والتموين","المجلس القضائي","وزير العدل"],"a":0},{"q":"أي مما يلي لا يعد من المسائل التي نص القانون على تنظيمها بالأنظمة الصادرة بمقتضاه؟","o":["تحديد عقوبات جرائم وكلاء الإعسار","سجل الإعسار","شروط تشكيل لجنة الدائنين","تحديد معايير أتعاب وكلاء الإعسار"],"a":0}]},{"n":"142","chapter":"الفصل الخامس عشر - أحكام ختامية","notes":[],"source":"رئيس الوزراء والوزراء مكلفون بتنفيذ حكام هذا القانون .","title":"تنفيذ القانون","memo":"⭐ رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام القانون","qs":[]}]};
